INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('2Base Technologies Pvt Ltd', 'IT Services', '', '11C, Tower 1, TransAsia Cyber Park,  Infopark Phase II SEZ,  Infopark Campus,  Kochi, KL, India - 682303', 'careers@2basetechnologies.com', 'www.2basetechnologies.com', '2Base Technologies is an enterprise software development company specializing in end-to-end IT digital transformation services. With registered offices in the UK, USA, and Australia and R&D centers in Kochi and Palakkad, India, we help businesses worldwide drive efficiency, innovation, and growth through custom software solutions.  With 16+ years of expertise, we have delivered tailored digital solutions across industries, including InsurTech, EdTech, Transportation & Logistics, Travel & Tourism, Healthcare, FinTech, SaaS, Agriculture, Oil & Gas, Non-Profit, and Hi-Tech. Trusted by 200+ global clients, we focus on co-creating digital strategies that align with long-term business goals.  Our core services include Custom Software Development, Business Process Optimization, IT Application Development, Product Engineering, Data Analytics & AI, Startup & Digital Transformation Consulting, SaaS Product Development, Web & Mobile Application Development, IoT, and AI & ML Solutions.  At 2Base, we engineer digital growth, helping businesses scale, innovate, and lead in an evolving digital world.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('2Hats Logic Solutions Pvt. Ltd.', 'IT Services', '0484 487 8903', 'Wing – 1, 4th Floor Jyothirmaya Building  Infopark Phase II,   Brahmapuram, P.O. Kochi – 682303', 'hr@2hatslogic.com', 'www.2hatslogic.com', '2Hats Logic Solutions is a professional outsourcing agency based in India for web and mobile application development, founded in 2012. We act as outsourcing partners for agencies in Europe and the USA providing IT talents/developers. We provide developers with flexible contracts which helps the growth of agencies in the West by saving time and effort in the talent hunt. Most projects we work on are either support or development of complex web applications mostly built on Laravel and Zend frameworks. We also do a lot of e-commerce development with Magento, Shopware, Shopify and Prestashop. We have a lot of expertise in WordPress and the development of its plugins and themes.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('42Square Technologies', 'IT Services', 'Office No.9,  Tower 1, 9th Floor,  Trans Asia Cyber Park,  Infopark Phase-II', '8078186103', 'support@42square.ai', 'www.42square.ai', '42Square is a global player in software consulting and product development. Our solutions work across web, mobile, and embedded software products for clients in the US, Europe, India & Middle East. We have helped our partners to build prestigious products ranging from simple content management systems to full-blown smart city projects with IoT and micro-services architecture.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('9Commerce Technologies', 'E-Commerce', '', '9995080656', 'hr@commerce9.io', 'www.commerce9.io', 'About US 9Commerce is a purely eCommerce-based technology service provider, mainly focusing on Magento, Cloud Computing and Customized eCommerce solutions for clients around the globe which is having a presence in UAE (Commerce9 FZCO) and India.   Today we’re a team of dedicated Magento eCommerce specialists and cloud infrastructure management experts. Our customer verticals provide us the experiences of how the eCommerce industry goes through on a day-to-day basis. We have extensive experience in all aspects of eCommerce & our focus remains on streamlining businesses, making them more efficient, reducing administration & operational time, improving sales revenue and conversion rates.   We also continue to run our own successful international eCommerce stores, so we truly practice what we preach!   We started life as a cloud support provider and were looking to grow into the cloud eCommerce space. Since the launch of Magento in 2008 provided, what we believed to be a game-changing eCommerce solution, built on an open-source framework we could own and tailor to our needs as we grew with the support of the Magento community. AWS / GCP Cloud providers gave us an edge in the market as we blend Magento in the right way. Our clients reach new heights in terms of business and online penetration for mobile and desktop users.   As a cloud service provider for eCommerce, we continually monitor the performance of the Magento App/cloud server Infra and optimize according to the needs 24 x 7 by our cloud and Magento Experts.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Aabasoft Technologies India Private Limited', 'IT Services', 'VismayaInfopark Kakkanad, Kochi Kerala - India', '914844172222', 'info@aabasoft.com', 'www.aabasoft.com', 'Aabasoft is a global End-to-End IT/ITES services and solutions provider helps the customers to do business better with our industry wide experience, deep technology expertise and comprehensive portfolio of services.  We are a pro-business, simple, efficient organization. We provides end to end consulting and solutions to our clients. We believe that IT infrastructure is the nervous system of any modern organization that connects the various systems and functions. We will help to build a robust IT infrastructure that gives you a big advantage in modern market environment.  Aabasoft is a client oriented company. We believe in three important factors which are quality, value, and time. Our clocks function to deliver you the very best at the right time and at the right cost. Our philosophy is to have the client at the focus point of all discussions and planning so that the product/service will be essentially client oriented.  We are an equal opportunities employer. We select our people very carefully; we look forward to work with people who are passionate, with the willingness to go that extra mile. Aabasoft provides its people with a professional environment to grow and succeed. We provide continuous training to our people not just in technology, but also in communication skills, client service and marketing.  We believe that apart from everything, the technology, the jargons, we do business with real people. Our clients don’t just buy a product or service, but a relationship. We believe that our people don’t just work for career growth and perks, but work for the Aabasoft family which they are part of. We don’t just add clients and workforce, we add members to our family.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Aarbee Structures Pvt.Ltd', 'Engineering', '', '+91-9544407555', 'aarbee@aarbeestructures.com', 'www.aarbeestructures.com', 'AARBEE based at Bangalore, India has come ahead of time to the forefront since its inception in 1998. The Company has written a new era in the field of Structural Steel Designing and Detailing.  Our strong clientele base enabled us to carve a niche in this arena. We, at AARBEE provide world class quality services adhering to AISC (American Institute for Steel Construction) and BS (British standard codes for steel detailing) standards in Structural Design & Steel Detailing of residential, commercial and industrial structures.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Abel Techsoft Private Limited', 'IT Services', '', '919995005969', 'info@abeltechsoft.com', 'www.abeltechsoft.com', 'Founded in 2009 and based in Kochi, Kerala, Abel Techsoft is a digital transformation partner delivering scalable software, AI-powered platforms, and human-cantered digital experiences. Evolving from a media and web studio into a full-service technology firm, we empower businesses to innovate, scale, and thrive through smart, sustainable solutions.  We specialize in modernization, AI-led transformation, cloud-native development, strategic consulting, and automation—designed to enhance agility and drive measurable impact. Our design-first approach integrates behavioural insights, usability research, and intuitive UX to deliver seamless digital interactions that convert and engage.  Through AI-driven Quality Engineering, automated testing, and shift-left strategies, we ensure fast, secure, and reliable delivery of high-performance products. We also provide elite tech talent across engineering, UI/UX, QA, and DevOps, helping clients scale capabilities and accelerate execution.Our branding team builds cohesive digital identities that resonate across platforms—merging purpose, creativity, and precision to create brands that perform.  At Abel Techsoft, our delivery model—Explore, Design, Develop, Deliver—ensures alignment from discovery to deployment, backed by ongoing support and optimization. Whether reimagining legacy systems or launching new platforms, we prioritize business outcomes and long-term value. We are also building the future with a growing team of engineers, designers, and analysts. Our career opportunities span full-stack development, mobile, UX, and QA, offering a platform to work on impactful, tech-forward projects.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Abilytics Consulting Pvt Ltd', 'Digital Marketing', '', '+91 9496061623', 'hr@abilytics.com', 'www.abilytics.com', 'Abilytics is setting new industry standards and reshaping the way businesses engage with their audiences in the digital age. Empowering businesses with hyper-personalized data-led digital transformation is at the heart of our mission. We strive to democratize access to advanced technologies, making them accessible and effective for enterprises of all sizes, as we lead the way in redefining the future of digital business.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Acabes International Pvt. Ltd.', 'FinTech', '9B-2, Jyothirmaya,Phase II, Infopark Kochi.', '4844225166', 'gopikaprabhu@acabes.com', 'www.acabesinternational.com', 'Acabes International Pvt Ltd (AIPL) provides software development, support and services to businesses across Arab Bank and its Affiliates and subsidiaries globally. AIPL is a global capability center, supporting Arab Bank businesses worldwide, delivering innovative end-to-end business solutions in Financial Technology and Functions.  Working collaboratively in the banking environment, AIPL is underpinned by technology Innovation and operational excellence, to ensure superlative outcomes for our customers by adopting and building innovative solution platforms.  This global capability center will deliver best-in-class technology services and we stand committed to providing value for its customers, business partners, ecosystem, and the communities we serve.  Acabes International’s main business focus in India: Be a center of excellence for seamless, scalable, and sustainable technology solutions for our subsidiaries. Deliver Innovative solutions in a fast-paced environment by maintaining governance and ensuring compliance with our group policies. Be a key enabler in Arab Bank’s Innovation Journey and provide the capability to deliver our customer promise.  At Acabes, outstanding performance is always rewarded, and career growth is carefully nurtured with professional development opportunities in a dynamic environment. We offer our employees exciting, long-term careers with a variety of opportunities to develop their skills, while also helping them to balance work, Hybrid work options to also meet your personal goals. Having an inclusive culture means we can offer talented people many ways to fulfil their potential in a nurturing environment that encourages the right behaviour. We want you to feel you can act with integrity and you are empowered to do the right thing here at Acabes.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Accelray Technologies Pvt Ltd', 'IT Services', '', '+9188486 20593', 'info@accelray.com', 'www.accelray.com', 'Established in 2019, Accelray Technologies is a leading IT solutions provider based in Kochi Infopark. We specialize in delivering cutting-edge web and mobile applications, workflow automation as well as innovative AI and LLM-powered solutions.Our team of seasoned professionals is committed to understanding your unique business needs and crafting tailored solutions that drive growth and efficiency. We pride ourselves on our ability to deliver high-quality, cost-effective, and scalable solutions that exceed expectations.Our Services: • Web and Mobile Application Development:  ? Custom web and mobile app development for diverse industries ? User-centric design and development ? Seamless integration with existing systems • Workflow Automation Solutions for SME’s:  ? Automating business workflow thereby reducing man hours for repetitive tasks and increase productivity • AI and LLM Application Development:  ? Leveraging the power of AI and LLM to automate tasks and enhance decision-making ? Building intelligent chatbots and virtual assistants ? Developing predictive analytics and machine learning modelsWhether you''re looking to modernize your business processes, enhance customer experiences, or launch a new digital product, Accelray Technologies is your ideal partner. Contact us today to discuss your project requirements.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Aceware Fintech Services Pvt Ltd (Radiant Acemoney)', 'FinTech', '0806 898 3333', 'Head Office : 1st Floor, PAM TOWER, Seaport - Airport Rd, Vallathol junction, Thrikkakkara, Kochi, 682021.  Infopark : 8th floor, Vismaya, Infopark Phase -1, Kakkanad 682042', 'info@acemoney.in', 'www.acemoney.in', 'Acemoney, developed and promoted by Aceware Fintech Services Pvt Ltd, (subsidiary of Radiant Cash Management Services Ltd, a Public Listed Company) is a trusted fintech brand offering a wide range of products to meet the digital banking and payment needs of common people. Acemoney focuses on financially including underbanked individuals, with a specific emphasis on the rural population.   Acemoney’s product portfolio of services includes Doorstep ATM,Wearable Cards (TEORA),Micro ATM,AEPS,Neo Banking,UPI/QR,BBPS, Insurance & Ticket booking  Acemoney Teora Wearable Payment Rings are the latest addition to our product line. This is a lifestyle product that would make payments the most convenient and stylish thing to do');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Acube Innovations', 'IT Services', '', '6235866111', 'contact-if@acube.co', 'acubeinnovations.com', 'Established in 2011, Acube Innovations specializes in ERPNext implementation and digital transformation. As an official ERPNext partner, we have successfully delivered projects for clients like KSRTC, KSEB, Muthoot Securities, and Mahindra Powerol. We excel in providing comprehensive ERPNext solutions that streamline processes and boost efficiency. Our team works closely with clients to design tailored ERP systems and ensure seamless integration with existing infrastructure. In addition to ERPNext, we spearhead digital transformation initiatives, including cloud computing, AI, and data analytics, helping clients optimize operations and enhance competitiveness. Our goal is to empower clients to make data-driven decisions and deliver superior customer experiences. Our team of skilled IT professionals develops customized software solutions, from mobility and web applications to intuitive UI/UX designs. We engage closely with clients, involving key stakeholders throughout the project lifecycle to ensure our solutions align with strategic goals and deliver tangible value. If you’re seeking a reliable partner for ERPNext implementation and digital transformation, Acube Innovations is here to assist. Contact us to learn how our tailored solutions can drive your organization’s success.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('adesso India Private Ltd', 'IT Services', '', '+91- 77360 95222', 'info@adesso.in', 'www.adesso.in', 'adesso India was established in 2023, with its primary development center in Kochi, complemented by two business centers in Trivandrum. adesso is one of the leading IT service providers in the German-speaking area and focuses its consulting and software development activities on the core business processes of companies and public authorities.   adesso’s strategy is based on three pillars: the comprehensive industry-specific know-how of its staff, extensive expertise in technology that is independent of manufacturers and the application of reliable methods in software implementation projects. adesso delivers the right IT solutions to increase the ability of companies and organisations to compete in the core sectors of insurance/reinsurance, banking and financial services, healthcare and life sciences, energy supply, public administration, automotive and manufacturing industry, trade, transport, media, entertainment, lottery and sports.adesso India specializes in optimization of core business processes for organizations.   Our focus is on providing state-of-the-art solutions that streamline operations and elevate productivity to new heights.Comprised of a team of industry experts and experienced technology professionals, we ensure that our software development and implementations are reliable, robust, and seamlessly integrated with the latest technologies. Our expertise extends across a broad spectrum, ranging from Insurtech and Fintech to Automotive, Retail, Healthcare, Hospitality, and the dynamic world of e-commerce.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Admaren Tech Pvt Ltd', 'IT Services', '', '+91 96333 84111', 'info@admaren.com', 'admaren.com', 'We Admaren Tech Pvt Ltd are a team of dynamic engineers specialized in Software Development and in providing ancillary services such as CAD development, cargo engineering, ship hydrostatics & hydrodynamics. Our primary focus is to develop a software that integrates and create a platform for bulk, breakbulk and project cargo industry where the users can collaborate and perform transportation related analysis such as cargo loading, stowage visualization & simulation etc.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Advenser Engineering Services Private Limited', 'Engineering Services', '', '+91 484 4040708', 'info@advenser.com', 'www.advenser.com', 'Advenser, a versatile engineering services company, brings cutting-edge engineering solutions to the construction industry. Derived from ADVanced ENgineering SERvices, our name Advenser reflects our commitment to pushing the boundaries of innovation and expertise. Since our establishment in 2007, we have become a trusted provider, leveraging state-of-the-art tools like BIM to deliver exceptional results.  With our motto, Partners in Engineering Excellence, we prioritize collaboration and understand the importance of working closely with our clients. Our impressive track record spans a wide range of complex projects across multiple countries, showcasing our ability to deliver tailored engineering solutions that surpass expectations.  At Advenser, we have honed our expertise and gained a multidisciplinary perspective through hands-on experience, serving a diverse clientele in the AEC industry. Architects, engineers, contractors, fabricators, and facility managers rely on us to adapt to their ever-evolving needs.  Our team consists of highly skilled professionals who are deeply committed to delivering exceptional services and solutions to our valued clients across various sectors. We maintain a humble approach, always seeking opportunities for learning and improvement. Our unwavering passion for engineering and relentless pursuit of excellence drive us to continually push boundaries while understanding the unique requirements of each client.  We prioritize individual clients by placing them at the forefront of our sales and project management processes. Our engineering processes and frameworks have been meticulously defined and streamlined to uphold the highest quality standards. Our team of experts from diverse domains collaborate closely, customizing and optimizing techniques to meet the specific expectations of each client.  Experience the ADVENSER difference and unlock a new level of engineering excellence for your projects. Contact us today to embark on a journey ');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Affiliated Computer Services of India, A Xerox Company', 'Unknown', '', '0484 4090136', 'Praseel.Nambiar@xerox.com', 'www.xerox.com', '');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Airo Global Software Pvt Ltd', 'IT Services', '', '+91-7034966777', 'hiring@airoglobalsoftware.com', 'www.airoglobal.com', 'Airo Global Software: Empowering Your Success with Cutting-Edge IT Solutions.   Experience unparalleled excellence with Airo Global Software, a renowned software development company offering professional IT solutions to clients across the globe. Backed by an impressive track record and a steadfast commitment to industry-leading practices, we ensure optimum quality and efficiency in all our projects.  Unleash the Power of Expert Development: Android, IOS,  PHP Codeignitor, MSSQL, Mysql, Angular, Flutter, Dart, Kotlin, BlockChain, Power Apps, Crypto Exchange, Node.js,Oddo, Sale Force, MS Dynamics, Quick Book Integrations, Shopify, Magento, AWS, Azure, Google Cloud Management, Chatbot,CRM Development     Discover the breadth of our services by watching our captivating video   Our expertise spans web, software, and mobile app development, harnessing the latest technologies such as Socket.io, Node.js, PHP, WordPress, and frameworks like ASP.NET MVC, Zend, CodeIgniter, Laravel, HTML, CSS, Bootstrap, Angular With our comprehensive and innovative approach, we deliver top-notch web/software solutions.  As pioneers in Blockchain and Cryptocurrency development, we stay at the forefront, enabling our clients to leverage this transformative technology and stay ahead of the competition.  In the realm of mobile applications, our proficiency shines through. We specialize in developing exceptional applications for iPhone, Android, iPad, Tablets, and even Watch App platforms. With expertise in Swift, Objective-C, Android Java and Kotlin, Flutter Dart, and Power Apps, we create seamless and captivating mobile experiences tailored to your target audience.  Furthermore, our networking and cyber security team excels in managing our own state-of-the-art data center, providing robust server solutions and efficient cloud management services that effortlessly align with your business requirements.  Choose Airo Global Software as your trusted partner to unlock the full potential of your busin');
