INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('ALB Technologies Pvt Ltd', 'LegalTech', '', '+91- 6238295987', 'hr@accuratelegalbilling.com', 'www.accuratelegalbilling.com', 'Accurate Legal Billing (ALB Technologies Pvt. Ltd.) operates as the Global Capability Center (GCC) of Accurate Legal Billing, Inc., USA — a leading provider of legal billing and e-billing management solutions for law firms and corporate legal departments. Established in Infopark, Kochi, ALB Technologies supports the parent organization through specialized backend operations, billing analysis, appeals management, and IT-enabled services tailored for the legal industry.  Our core expertise lies in legal billing accuracy, compliance with client billing guidelines, and advanced data management processes using industry-standard platforms and technologies. The Kochi center plays a vital role in ensuring operational excellence, process efficiency, and timely service delivery across global markets.  By combining legal domain knowledge with process automation and technology-driven solutions, ALB Technologies continues to enhance the quality, accuracy, and transparency of legal billing services. The Infopark office functions as a strategic extension of our U.S. operations, driving innovation and value creation for clients worldwide.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('AlignMinds Technologies', 'IT Services', '', '8590036453', 'careers@alignminds.com', 'alignminds.com', 'We are a Fifteen-year-old technology consulting company based in Cochin having our own development facility with offices in North America and Africa. We have won numerous accolades for our team''s innovation skills and our continuous focus on emerging technologies. Working with AlignMinds means being part of a team that values innovation, creativity and freedom at its best. The services we offer Product Engineering, Product Modernization, Product Support and Maintenance and IT Infrastructure Management, etc..');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('ALTOS Technologies', 'IT Services', '', '', 'info@altostechnologies.in', 'altostechnologies.in', 'ALTOS Technologies is a leading software and web development company based in Kochi, Kerala. with the latest technology and framework, we continuously strive to improve ideas as a team of young, innovative thinkers. We are located in the IT hub of Kerala, Infopark Kochi, and have been helping businesses and individuals realize their full potential for years with our expertise in software, web development, mobile application development, 3d modelling, game development etc. we are also providing on-the-job training (online) to students with the knowledge we have gained over the past few years in order for them to build a great career under professionals of multinational companies.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Amara Raja Design Alpha Private Limited', 'IT Services', '', '+91 8590905049', 'aswathi@designalpha.in', 'www.amararajadesignalpha.com', 'Amara Raja Design Alpha Pvt. Ltd (ARDA) , a proud subsidiary of Amara Raja Electronics Ltd.  ARDA stands out with its concept of Design Factory, where ideas translated to commercial products. With its very flexible and client aligned services mode combined with the full and holistic product design expertise, ARDA has earned its acceptance among customers within a short span of time.');
