INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Amla Consultancy Pvt Ltd', 'E-Commerce', '', '+91 99613 69999', 'info@amlaconsultancy.com', 'www.amlaconsultancy.com', 'We are specialized in ecommerce consultancy, development, implementation, mobile app. Having a team of business, management, ecommerce , IT consultancy with a dedicated team for development in various technologies. Also have a great team for development of content management websites and mobile applications with native, flutter, ionic technologies. Our Specialized team is capable of developing and implementing various ERP software products in various domains');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Amplitude Software Systems Pvt Ltd', 'IT Services', '', '91 6282902505', 'hr@jupiterbs.com', 'www.jupiterbs.com', 'Amplitude Software Systems Pvt Limited (ASSPL), incorporated in 2008, is a part of Jupiter Business System FZC (JBSFZC), incorporated in 2006.  JBSFZC has developed an ERP platform (Jupiter Business Manager - JBM) on Microsoft Technology.  The product has a matured and proven solution to automate the shipping and logistics business in the Middle East, India and now Africa. ASSPL works as a software development company engaged in the following activity: •   Operate as a Dedicated Development Center for JBSFZC •  Handle the sales and servicing of the product JBM in India •  Handles support (online) and servicing of the JBM for global clientele •   ASSPL is currently operating with offices in Thrissur, Navi Mumbai and Bengaluru •   ASSPL also serves as a back office for the group’s global operations');
