INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Apps Team Technologies Pvt.Ltd.', 'IT Services', '', '+91 484 2982554', 'hello@appsteamtechnologies.com', 'appsteamtechnologies.com', 'Apps Team Technologies Pvt. Ltd. is the industry leader in mobile app development. Our smartphone developers expertise on both native and web applications. We create cross-platform apps that work on both phone and tablet interfaces for Apple, Android, Windows, and Blackberry.  We are a provider of custom mobile application development services and can port existing applications or develop them from scratch. Our unique combination of skills and experience makes us the ideal choice to develop your smartphone application and bring your ideas to life.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Apro IT Solutions Pvt Ltd', 'Digital Marketing', '', '+91 6238683058', 'info@aproitsolutions.com', 'www.aproitsolutions.com', 'Founded in 2018, Apro IT Solutions is a dynamic and innovative digital solutions company, offering a comprehensive suite of services tailored to meet the evolving needs of businesses worldwide. Specializing in Graphic Design & Branding, Website & App Development, UI/UX Design, Digital Marketing & SEO, Social Media Marketing, Pay-Per-Click advertising ,we are committed to empowering our clients with cutting-edge solutions that drive growth and enhance brand visibility.   At Apro IT Solutions, we pride ourselves on our personalized approach, delivering visually stunning websites, robust web applications, and strategic marketing campaigns designed to achieve tangible results for our clients. With a focus on excellence, expertise, and continuous innovation, we strive to be the trusted partner that businesses turn to for all their digital needs.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Armia Systems Pvt. Ltd', 'IT Services', '0484 297 3123', '', 'jobs@armia.com', 'www.armia.com', 'Armia Systems (P) Ltd., is a recognised provider of Technical Support Services, Software products and Solutions aimed at helping Web Hosting Companies and net enreprenures to leverage the amazing opportunity available over the internet. Our goal is to provide Internet Companies and individuals, the one asset thats needed more than anything else: time and business scalability!The Company owns SupportPRO, a globally renowned brand of Technical Support Services Providers. A right mix of technical and language skills backed by a robust infrastructure and highly dedicated workforce goes into making SupportPRO a hit among clients worldwide.www.supportpro.com The Software development team helps you unleash the full potential of your business leveraging the Internet through a host of quality products branded as "iScripts" products. Our custom tuned software goes one step further in making it suit your very business.www.iscripts.comÂ Â');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Array Platforms Pvt Ltd', 'IT Services', '', '0484-4041580', 'neha.r@array.team', 'array.team', 'Array Platforms Pvt Ltd (earlier Macrosive) is a premier technology consulting firm and a distinguished Microsoft Partner, specializing in Tech Business Applications Consulting, Low Code No Code Apps, Business AI, and Software RPA. Our commitment to innovation and state-of-the-art solutions empowers businesses to harness technology for enhanced efficiency and growth. Beyond our technology consulting expertise, we proudly offer a suite of cutting-edge products designed to meet specific business needs. These products leverage the latest advancements in Tech Business Applications, Low Code No Code Apps, Business AI, and Software RPA, ensuring our clients stay at the forefront of technological progress. Our parent company, Macrosive Ltd., is based at 33 Herbert Lane, Dublin 2, Ireland, with a branch located at Athulya Annexe, Infopark Campus, Kakkanad P.O, Kochi, Kerala, 682042, India. Our dedicated team comprises 40 members in India and a small team in Ireland, all committed to delivering exceptional service and solutions.');
