INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Aspire Systems Digital Private Limited', 'IT Services', '', '0484 4061901', 'keerthana.jayaraj@aspiresys.com', 'www.aspiresys.com', 'Aspire Systems is a global technology services firm serving as a trusted technology partner for our customers. We work with some of the world''s most innovative enterprises and independent software vendors, helping them leverage technology and outsourcing in our specific areas of expertise. Our services include Product Engineering, Enterprise Solutions, Independent Testing Services and IT Infrastructure Support services. Our core philosophy of "Attention. Always." communicates our belief in lavishing care and attention on our customers and employees.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('AVENTUS INFORMATICS', 'IT Services', '', '7907091213', 'hr@aventusinformatics.com', 'www.aventusinformatics.com', 'We are a complete 360° Digital, Marketing, and IT company focusing on creating the most suitable technological solutions for your problems. Aventus Informatics has a global presence with headquarters in Kerala, India, and offices in Koratty, New Delhi, India and Doha, Qatar. Our 50+-strong and experienced in-house development, marketing and creative teams enable us to offer both onshore and nearshore delivery. We will help you take your business to the next level with the best combination of the latest technological enhancements and digital strategies. You have a problem? Consider IT solved with Aventus!');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Ayata Commerce Tech Solutions Pvt Ltd', 'E-Commerce', '', '919995473245', 'hr@ayatacommerce.com', 'www.ayatacommerce.com', 'About Us  AyataCommerce is a digital commerce solutions agency that delivers world class digital services and value to businesses. Our story  AyataCommerce was founded by Shine Mathew, an E-commerce enthusiast in 2016 in Bracknell, UK. His experience with well-known retail brands across the globe helps Ayata follow its principle “making people’s lives easier.” This applies to our customers, employees and partners; our ecommerce implementations always have  convenience in mind, and our ‘remote first’ culture greatly eases the impact of work on our employees’ lives. Even though we started as ecommerce solution implementers, after a few project engagements with initial clients we became their trusted advisors. We believe this is a result of our key focus: customer success, when required we will always go the extra mile to exceed their expectations.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Banzan Studios', 'Gaming', '0', '', 'info@banzan.co', 'www.banzan.co', 'Banzan Studios is an indie entertainment studio building a global character TRANSMEDIA from India with a GAMING first approach. We are a product focused Gaming and Interactive Entertainment company operational since 2020 with interests across content production and building distribution platform through our own SUPER APP. We have built more than 60 Games and 1000+ comic content under our portfolio. We are the creators of BaBlah®, the Monk who aspires to become ''World''s First Virtual Actor''.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Beinex Consulting Pvt Ltd', 'IT Services', '', '6238389957', 'careers@beinex.com', 'www.beinex.com', 'At Beinex, we help shape your business with data and analytics! As a digital transformation organization enrooted with ideas, innovation and unparallel customer service, our broad range of analytics modernization and training services will empower you to forge an intelligent and agile enterprise by making data a competitive advantage. We help change the way our clients approach the business by enabling them to analyze data, mitigate risks, identify opportunities, and automate processes. Beinex empower organizations to make meaningful decisions by maximizing technology and helping employees to be more productive by coupling data with the right tools.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Beth Soft Technologies India Private Limited', 'IT Services', '', '9633849485', 'info@bethsofttechnologies.com', 'www.bethsofttechnologies.com', 'Beth Soft Technologies India Private Limited');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Bhooshan''s Junior', 'Kids Entertainment', '', '4843539863', 'info@bhooshansjr.in', 'www.bhooshansjr.in', 'Bhooshan’s Junior is a Global Digital-first Kids Entertainment Company focused on Building high-quality, scalable IPs, dedicated to creating original animation series for kids and iconic cartoon IPs for children aged 2–14 years. Our mission is to craft high-quality kids’ cartoons and educational entertainment videos that inspire creativity, laughter, and learning.  Bhooshan’s Junior was born from a bold idea — that India could create world-class kids’ entertainment IPs capable of standing shoulder to shoulder with the biggest global franchises. We believe in the power of stories to shape young minds, cross cultural boundaries, and live far beyond the screen.  We are passionate about building a franchise-first ecosystem — where our animation IPs seamlessly extend into games, music, toys, books, consumer products, theme  Our Vision  To position India as a global powerhouse in kids’ entertainment, delivering animation and storytelling that inspire joy, learning, and imagination for children aged 2–14, no matter where they live.  Our Mission  • Create Iconic IPs – Develop original characters and stories that resonate across languages, cultures, and generations. • Build Global Franchises – Expand beyond animation into products, experiences, and interactive media. • Inspire & Educate – Blend entertainment with learning to nurture curiosity and creativity in every child. • Innovate Fearlessly – Leverage technology, creative collaboration, and unique GTM models to lead the future of kids’ entertainment.  Our Promise  At Bhooshan’s Junior, we are committed to crafting joyful, safe, and meaningful content that parents trust, kids love, and partners are proud to support — creating global childhood memories, made in India.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('BIMEX Engineers', 'IT Services', 'Unit 5A-6, 5th Floor, Carnival Infopark - Phase II, Kakkanad, Kochi, India - 682 030', '+91 81293 21656', 'info@bimexeng.com', 'bimexeng.com', 'BIMEX Engineers drives digital transformation in the built environment through advanced Building Information Modelling (BIM) and Virtual Design and Construction (VDC) practices. Founded in 2015, we provide comprehensive solutions across the entire project lifecycle; from design and coordination to construction and facility management. Our expertise includes 3D modelling, clash detection, construction documentation, and customized BIM & VDC implementation strategies that empower architects, engineers, contractors, and developers to collaborate more effectively and make data-driven decisions.  With a strong focus on innovation and quality, BIMEX Engineers helps clients reduce risks, optimize resources, and deliver projects with enhanced efficiency and accuracy. We have successfully partnered with leading organizations across Europe, the Middle East, the U.S., India, New Zealand, and Australia, supporting projects ranging from commercial and residential developments to large-scale infrastructure, ensuring sustainable and future-ready built environments.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Binaries', 'IT Services', 'Infopark TBC, 8 Floor, Vismaya, Infopark Phase-1, Kakkanad, Kochi-42.', '918547644145', 'info@binariesindia.com', 'www.binariesindia.com', 'Binaries is a cloud computing services provider established in the year 2012 in the city of Kochi. We are a Microsoft partner providing their various cloud solutions. We provide computer network management consulting its design and implementation solutions. Cyber security and VOIP services are other areas of our focus.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('BJ Corps Technologies (OPC) Private Limited', 'Digital Marketing', '', '9846691115', 'info@bjcorps.com', 'www.bjcorps.com', 'We, at the BJ Corps, provide a complete range of affordable web design & website development services, starting from the initial process of taking inputs from clients, planning on the basis of such inputs to final implementation and testing. Apart from this, other services include, eCommerce website designing services, digital Marketing service, mobile application development services and much more. When it comes to Website designing Services, we always focus on fresh, interactive and fast loading website development and layout, which helps users in finding what they are looking for. The complete process of designing and development is done by our qualified and highly experienced web designers and developers. We are capable of doing most of the web techniques, most of PHP frameworks, custom made web applications, mobile compatible websites, jQuery/CSS3 animated websites, HTML5 websites, or whatever one website can serve. Our mission is to provide both new and existing customers with the best online solution or tools for their business. WEB DESIGN, WEB APPS, SEO & SMO. As a leading digital Marketing service provider in Kochi, we have an array of clientele that is spread across the world. You can now get our top-notch services across India, UK, Canada, United Arab Emirates, Australia and lots.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Braddock Infotech Pvt. Ltd.', 'IT Services', '', '+91 9447530986', 'careers@braddockinfotech.com', 'www.braddockinfotech.com', 'Braddock Infotech Pvt. Ltd. is an offshore development centre located in Kerala, India, that provides application development, application maintenance, system integration and network operations support services to a global clientele. We design, build, implement, integrate, support and manage tactical and strategic solutions using cutting edge technology.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Braid Technologies Pvt. Ltd', 'IT Services', '', '9847128982', 'info@braidtechnologies.com', '.', 'An Infopark company that delivers web-based enterprise software for international clients. Gain experience building and maintaining the latest technology used by more than 300K users, utilizing Agile, and managing a customizable product. You should have experience working on your own to take ownership of Agile sprints.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Bramma IT Solutions', 'IT Services', '', '+91 9895027444', 'preetha@brammait.com', 'www.brammait.com', 'Bramma It solutions is a leading Software Development  company & digital Marketing Company with offices located in UAE and Cochin. We are handling more than 1000 major clients both in India and abroad in the last 15 years. The industry experience and our expertise in our field helped the company get awards and recognition from leading business magazines and other organizations.   15 Year Old Company');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Brennan IT India Private Limited', 'IT Services', '', '8097548206', 'india.recruitment@brennanit.com.au', 'www.brennanit.com.au', 'Brennan IT is an Australia based company established and formed in September 1997 with offices in Australia at Sydney, Melbourne, Brisbane and Newcastle. Brennan has 3 offices outside of Australia – 2 in Mumbai & 1 in Kochi. Brennan started its India operations in June 2014, located at Millennium Business Park, Mahape, Navi Mumbai. Brennan has long been reputed as the leader in help in businesses reach their full potential, delivering outsourced IT service solutions that scale and enable our  clients to focus on what matters to them most. We pride ourselves on being a “quality” service provider within the IT industry and commit to delivering on service promises and strive to exceed client expectations.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('BroadTech IT Solutions Pvt Ltd', 'IT Services', '', '+91 9048654482', 'contact@broadtech-innovations.com', 'www.broadtech-innovations.com', 'BroadTech IT Solutions Pvt Ltd is a specialized technology firm focused on Odoo ERP solutions. With more than 15+ years of experience in OdooERP, we are dedicated to delivering comprehensive Odoo services that help businesses enhance their operations, improve efficiency, and drive growth.We serve a variety of sectors, including but not limited to Trading, Manufacturing, Retail, Logistics delivering tailored solutions that meet industry-specific challenges.At BroadTech IT Solutions Pvt Ltd, we are passionate about helping businesses leverage the full potential of Odoo, ensuring they stay competitive in today''s fast-paced digital landscape.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Bytestrone India Private Limited', 'IT Services', '', '+91-87146 24107', 'info@bytestrone.com', 'www.bytestrone.com', 'Bytestrone provides end-to-end Software Engineering Services to breakthrough innovators. Our pragmatic approach solves complex Software Engineering by bringing projects to precision-crafted teams that are built on character, excel in Engineering, and embody true agility. Engineering Excellence comes second nature to us, as our teams have been continuously sharpening their skills and acquiring new knowledge.  Bytestrone is founded by technology experts with decades of experience in Digital Engineering. Our unique service offerings, combined with our vast experience in the digital space can be leveraged by product companies for its digital needs. We have expertise in Full-Stack Cloud-Native Development, Technology Consulting, Systems Integration and Reference Implementation.  Reach out to us at info@bytestrone.com to learn more about our service offerings and how we can help you in your digital journey.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Cabot Technology Solutions Pvt. Ltd.', 'IT Services', '0484 404 5555', '204, Second Floor, Lulu Cyber Tower-1, Infopark, Kakkanad,  Kochi-682042.', 'info@cabotsolutions.com', 'www.cabotsolutions.com', 'Cabot is a value-based technology consulting firm providing end-to-end IT solutions for its clients across North America, Europe, and Australia. We have a highly skilled team in the areas of Healthcare software development, Cloud Computing, Product Design & Development Development, Business Intelligence, and IoT. Since our inception, we have delivered over 500+ projects on the web and mobile platforms using cutting-edge technologies. Our dedicated teams seamlessly integrate with the onsite development teams of our clients and add value to the client business by providing technical knowledge and flexibility. We take pride in our high-quality deliverables and our attention to our clients and partners.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Calpine Group', 'IT Services', '+91 484 241 5030', '', 'info@calpinetech.com', 'www.calpinetech.com', 'Company Profile Exceptional Solutions at an Exceptional PriceCalpine Technologies is a company specialized in custom software development, web design, Internet /Intranet applications and consulting services. The company has potential and experience in development of complex solutions for its customers - implementation of concepts for data security, corporate and virtual private networks, databases and software development. We create modern software products for business management, based on Client/Server and Internet/Intranet technology decisions in accordance with the leading world standards in the field of IT. We create Internet sites led by the demands of our clients - with advertisement exposure, aimed at marketing or containing database. We provide planning, professional development and management of web sites plus hosting, promotion, up dating and support. The Business: Calpine Technologies is in the business of solving problems for small to midsize companies while helping them extend their reach globally. The Scope: Calpine Technologies specializes in delivering value-proposition solutions and cater to the needs of the following domains:  Life Science Solutions e-Commerce ERP Solutions Design Services Remote Server Administration Quality Control  Our areas of interest include:  Managed Support Services Information Technology Software Development Web Services & Integration Graphic Design & Branding  Core Mission Statement: Our core ideology is to find a way to offer high quality and high value with our solutions. Not one or the other. Although this goes against many management and operational theories, we can and will, under most situations, deliver premier solutions at an affordable price. If, through our discovery session, we can’t deliver high quality at high value, then we will not take on a project. We are adamant about not taking on a project unless we can cross the chasm between quality and price.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('CareRevenue (Good Methods Software Solutions Pvt Ltd)', 'Healthcare', '', '7510200399', 'careers@carerevenue.com', 'https://carerevenue.com/', 'Good Methods Global is a product company with CareStack as its flagship product. 4 years after the successful launch of CareStack, we wanted to partner with our customers to help them achieve higher revenue outcomes. Therefore, in 2019 we started CareRevenue-an all-in-one platform that offers a comprehensive solution to all the billing needs for Carestack customers. By combining technology and functionality, we aim to help healthcare professionals manage all their revenue cycle operations with comfort and ease.https://carerevenue.com/');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Carnegie Worldwide Services Pvt Ltd', 'Legal Services', '', '4844609761', 'worldwidecarnegie@gmail.com', 'www.carnegieworldwideservices.com', 'Carnegie Worldwide Services Pvt Ltd is a LPO in US Immigration with headquarters in New Jersey, USA. We provide back office services to various US visa categories and have 50 plus employees working in the unit. We are a growing firm with lot of career aspects and virtues.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Carol Solutions', 'IT Services', '', '+91 9846010135', 'lissamma@carolsolutions.com', 'www.carolsolutions.com', 'Established in 2001, Carol Solutions has emerged as a frontrunner in the field of ERP software solutions, catering to the requirements of businesses globally. Headquartered in Infopark, Kochi, we have positioned ourselves as a premier entity in computer software development, with a primary focus on delivering comprehensive ERP solutions. Our extensive expertise spans various industries, enabling us to offer customized solutions tailored to meet diverse business demands.At Carol Solutions, we pride ourselves on going beyond conventional implementation practices. Our commitment extends to providing comprehensive support, including immersive classroom training, personalized one-on-one sessions, and continuous telephonic assistance. Through these efforts, we aim to foster sustained proficiency and success for our esteemed clients.We offer a ready-made Enterprise Solution tailored for Trading and Manufacturing Industries, specifically designed to deliver speed, agility, and adaptability necessary to thrive in today''s dynamic business landscape.In collaboration with Amazon Web Services, we leverage secure, resizable compute capacity in the cloud, ensuring robust and scalable solutions for our clientele.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Cascade Revenue Management Pvt. Ltd', 'IT Services', 'Cascade Revenue Management Pvt. Ltd.  Unit No 504,5th Floor, World Trade Center Kochi, Info Park Kochi – Phase 1 SEZ, Infopark P.O , Kakkanad, Kochi, Kerala – 682 042', '0484 4861626', 'hrd@aimagroup.co.uk', 'www.aimabms.com', 'Cascade is a part of AIMA Group Company. AIMA Group works with partners and customers across the USA, Canada, U.K., India, China and the Philippines, operating a hub & spoke business model with current international headquarters based in Surrey, UK. We are outsourcing IT/ITES business services of Healthcare, Business and Legal, Software Development, Software Testing, Interface Development and UK Payroll processing.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Cavli Wireless', 'IoT', '', '8893204111', 'careers@cavliwireless.com', 'www.cavliwireless.com', 'Cavli Wireless is an Internet of Things technology company that brings to market the primary blocks necessary to build, connect & scale ''Smart'' Products around the globe. We have a portfolio that includes - Smart IoT modules integrated with eSIM, Global telco network access & IoT connectivity and Cloud platform for connectivity & modem management. We take away the headache of IoT connectivity management, so that ‘Smart’ product/solution makers can focus on their core business proposition, at the same time leverage the power of smart connectivity to improve their customer experience and optimize their product. Our customers are spread across industries & use cases ranging from asset tracking, smart street lighting to EV bikes and smart kiosks around the globe. We get to work with the smartest minds at emerging technology startups to established enterprises who have been leaders in their space for decades.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('CCS Technologies (P) Ltd', 'IT Services', '', 'Fourth Floor, Lulu Cyber Tower, Infopark, Kusumagiri P.O,  Kakkanad, Kochi - 682030', 'careers@ccs-technologies.com', 'www.ccs-technologies.com', 'CCS Technologies provides professsional services of the highest degree from its development centers in Infopark Campus, Kochi and Kottayam . The company has excellent track record of more than 30 years and  proud to have associated with a large number of satisfied clients. The focus areas are SAP R/3, ECC6 and BusinessOne, Microsoft SharePoint and Custom developments in .Net, Java and Clarion.Net technologies. We are an SAP Partner with more than 70 Functional and Technical consultants having many years of implementation and support experience for various industry verticals in India and abroad.  CCS is also a Microsoft Silver Partner with high caliber resources in MS SharePoint and .Net Technologies.   Services we provide:  1.      Implementation and Support of SAP (R/3, ECC6 and NetWeaver), ABAP Development, SAP - Bespoke Application Integration, BASIS Support - Version Upgrade & Performance Monitoring and SAP Business One. 2.  Implementation and Support of SAP BusinessOne, development of add-on modules for customer specific requirements with tight integration to SAP BusinessOne. 3.      Microsoft SharePoint Portal Installation & Configuration, Workflow, Collaboration, Document Management, BI, CMS, Migration to new versions and Security Management. 4.      Custom WEB and Client / Server Application development  for any kind of requirements using state-of-the art technologies like SOA & Web Services in MS.Net, Java/J2EE or Clarion. Our professionals have got very good knowledge of Oracle Database. 5.CCS also provides manpower outsourcing at customer location or offshore.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('CEREIV Advisory LLP', 'Cybersecurity', '', '9745767949', 'info@cereiv.com', 'www.cereiv.com', 'CEREIV Advisory LLP is a Cyber Security Company headquartered in Kerala, India, which offers its services to small, medium and large enterprises. The area of expertise includes Information / Cyber Security Certifications, Registrations and Independent Validations. CEREIV strives to provide best-in-class Cybersecurity services to organizations, retaining their strategic goals and offering a highly protected IT infrastructure.Our certified and experienced professionals uncover the vulnerabilities and gaps in the cyber security posture, thereby helping organizations meet all the compliance requirements. Our broad range of cybersecurity services includes ISO 27001, Security Assessments(VAPT), SOC2 Type1 & 2 Assessments, IS Audits against RBI guidelines, Compliance Review Services, NBFC Compliance Services, DISHA Assessments, SEBI Audits,  etc. To know more, visit our website www.cereiv.com or drop us an email at info@cereiv.com');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('CHISQUARE LABS', 'Healthcare', '', '7356949900', 'hr@chisquarelabs.com', 'chisquarelabs.com', 'Chisquare Labs is an India-based technology product engineering startup focused on the Life Sciences, Healthcare, Retail, and Supply Chain domains. Our Life Sciences & Healthcare Technology and Clinical Decision Support Solutions are designed to transform how healthcare is delivered and regulated—through intelligent, purpose-built solutions. We partner with global pharma, medtech, CROs, and digital health innovators to deliver data-driven solutions in clinical operations, regulatory tech, pharmacovigilance automation, and AI-powered analytics. At our core, we believe in advancing human health through digital innovation. Whether it’s streamlining a clinical trial, or automating clinical workflows—we design with purpose.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('CipherPeak Private Limited', 'IT Services', '', '+91 90747 07573, +91 97467 11096', 'cipherpeak@gmail.com', 'cipherpeakpvtltd.com', 'CipherPeak Private Limited is a Kerala-based IT and digital marketing company with a strong focus on serving international clients. We specialize in website and app development, software solutions, digital marketing, branding, video production, and ad shoots, helping businesses across the globe strengthen their digital presence.  Most of our work comes from overseas, where we partner with clients in different industries to deliver customized and result-driven solutions. Our team combines creativity with modern technologies to ensure that every project meets international standards while addressing the unique needs of each business.  By establishing our operations at Infopark Cherthala (SEZ), we aim to expand our global footprint, take on larger international projects, and build long-term partnerships with businesses worldwide. Our vision is to grow as a trusted digital solutions provider from Kerala, contributing to the state’s IT exports and creating opportunities for talented professionals.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Classic Technologies & Business Solutions Pvt. Ltd.', 'IT Services', '', '+91 9048400038', 'careers@ctebs.com', 'www.ctebs.com', 'Classic Technologies and Business Solutions Pvt Ltd (CTeBS) is a software product development company, located in Cochin, focusing on building world-class business enterprise applications for manufacturing industries. CTeBS was established in 2014 in as the technology innovation centre for Apparel Industries. We are a team of technology enthusiasts with a vision to transform today''s apparel manufacturing businesses ready for tomorrow. We focus on providing simple to use and intuitive digital solutions that enhances the productivity of Apparel business units.');
