INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('CloudHouse Technologies Pvt.Ltd', 'IT Services', '', '0480 2737360', 'info@cloudhousetechnologies.com', 'cloudhousetechnologies.com', 'CloudHouse Technologies Pvt. Ltd. is a premier IT and software development firm specializing in cloud solutions, ERP integrations, and innovative software products. With extensive expertise in cloud infrastructure, server management, and enterprise software, CloudHouse delivers scalable, secure, and cost-effective IT solutions to businesses worldwide.  The company is known for its flagship product, CloudStick, a powerful cloud control panel that simplifies server and website management. Additionally, CloudHouse provides ERP solutions, custom software development, and server management services through GetMyAdmin. It leverages open-source technologies and cutting-edge architectures to drive business efficiency and digital transformation.  CloudHouse prioritizes reliability, security, and performance, ensuring its solutions align with the unique needs of SMEs, enterprises, and digital agencies. With a mission to empower businesses through automation and cloud innovation, CloudHouse fosters long-term partnerships by delivering tailored IT solutions.  Backed by a skilled team of engineers, the company continues to expand its product offerings, integrating AI-driven features and modern development frameworks to stay ahead in the competitive tech landscape.');
