INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('CLOUDVICE', 'IT Services', '', '9037122872', 'info@cloudvice.com', 'www.cloudvice.com', 'CLOUDVICE is a trusted Oracle Partner recognized for its strong expertise in artificial intelligence and enterprise-grade cloud solutions. With a deep foundation in Oracle technologies and a forward-thinking AI approach, we help organizations accelerate transformation, automate intelligently, and build scalable, future-ready digital ecosystems. CLOUDVICE as a strategic partner for enterprises looking to unlock the full potential of AI and the cloud.');
