INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('CodeDesign Technologies Pvt Ltd', 'Digital Marketing', '', '7558825266', 'info@codedesign.in', 'codedesign.in', 'Codedesign Technologies is a technology company driven by creativity. We design, develop and market brands. We are a team of website developers & designers, graphic designers, videographers and digital marketing experts. We have a complete ecommerce development & support team and also create customized web based applications. In our 10 years of experience, our clientele spans across India, US, UK, Middle East and Australia.');
