INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Cognicor Technologies Pvt.Ltd', 'FinTech', '0484 241 5600', '1st Floor Thapasya Building, Infopark, Kusumagiri P.O  Kakkanad, Kochi - 682030', 'hr@cognicor.com', 'www.cognicor.com', 'CogniCor is the leading AI Digital Assistant platform enabling Financial Services firms in the insurance, wealth management and retail banking sectors in the US market to accelerate business growth by improving efficiency in sales and support. Using CogniCor’s platform, our customers were able to achieve exceptional ROIs such as 35% reduction in calls, 30% reduction in call transfer rates and CSAT scores beyond 95%. In 2020, we were recognized by some outstanding national and global awards - CogniCor was selected by NASSCOM as one of the Deep Tech Club startups, propelling deep technological research and product development in India. We won SheLoves Tech global award for the best female global technology company, Entrepreneur of the Year award sponsored by Microsoft and Diversity in Tech, invited by the Monetary Authority of Singapore to speak in the Singapore Fintech Festival and spotlighted by Oracle as a startup that scales with the Oracle Knowledge Platform. We were also picked up by leading prestigious financial accelerators - Mass challenge fintech Boston, On-Ramp insurance accelerator in Minneapolis run by Allianz Life and Securian Financial and nominated by VentureBeat for the Annual Women in AI award.');
