INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Coinone Global Solutions Pvt Ltd', 'IT Services', '+91 999 5205 444', '', 'info@coinoneglobal.com', 'www.coinoneglobal.com', 'Coinone Global Solution Pvt. Ltd. operates from Infopark Technology Business Centre, Kochi. The predominant  focus is on custom built CRM and ERP software development. The project execution begins with requirement  analysis, followed by phase wise well defined milestones and subsequently conducting user acceptance testing  (UAT) and finally ''Go-live''. Our team brings into the table a massive wealth of knowledge and technical background  that have been amalgamated over a dozen years of industry experience. Having worked across various projects  on global basis, our team is capable of handling complex dynamics in accounting, trading and manufacturing.  We at Coinone, are always self-motivated to bring in new technology innovations to meet the needs of business houses.  Our Vision  We empower our clients with technology which help to achieve their business goals. Our vision is to  enhance your business and scale new heights in productivity and profitability.  Our Business Verticals  Our Business Verticals · Manufacturing · Retail Business · Trading · Service Management · Marine Export · Textiles & Boutique · Community Management · Academic & Timetable · Restaurants  Product Features  · E-Invoice & E-Way Billing Enabled System  · Access from anywhere in the globe · On premise and cloud based versions · Import and export data easily · Multi level approval settings · Sales campaign monitoring · Maximize Sales conversions · Tracking inventory for accurate purchase decisions · Very precise P&L reports · Tightly integrated accounting system · Easy understanding with effective training · Improve Return on Investment (ROI)');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('COMNSEC Technologies Pvt. Ltd', 'IT Services', '', '8921003958', 'info@comnsec.com', 'www.comnsec.com', 'We envision to be the most admired, innovative, and technology-oriented solutions and service provider in all domains of business needs. As a jewel to sparkle bright, precision in its cuts is of atmost importance. Rooted in this belief and equipped with technology expertise, at COMNSEC the company committed to providing relevant solutions to the world of business & Industry. We provide easily configurable software solutions which meet the various industry requirements of Finance, Inventory, Manufacturing, Sales (both wholesale and retail with Point of Sale), Customer Relationship Management, and more. At COMNSEC, we have a packaged software solution for all micro verticals.');
