INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('ContactPoint 360', 'IT Services', '', '', 'hr.india@cp-360.com', 'www.contactpoint360.com', 'ContactPoint 360, Inc. is a global organization offering Software Development, onshore & nearshore contact center solutions. We’re proud to call ourselves innovative leaders in the industry and value how we’ve been able to grow significantly. We offer custom software development and co-development services for clients who need personalized solutions to complex workflow problems. Our team of developers and subject matter experts work to understand your unique needs and goals to deliver tailored solutions which are agile, responsive and provide superior user experience. We are proud to announce that we are certified as a Great Place to Work after a thorough and independent analysis conducted by Great Place to Work Institute Canada. We offer an award-winning culture that is enthusiastic about adding next level talent as we continue to expand. We trust and empower our team when it comes to providing the best human experiences. We believe in thinking and acting differently.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('CoolMinds Technologies Pvt Ltd.', 'IT Services', '0484 241 5121', '', 'career@coolmindsinc.com', 'www.coolmindsinc.com', 'We have designed and developed holistic e-commerce ASP (Application Service Provider) platforms and SaaS (Software as a Service) models for various leading organizations in India and abroad. We also offer a wide spectrum of software solutions for varied industry verticals.  Our technically skilled expertise has pioneered the art of developing quality performance-oriented business solutions across time zones. We adopt systematic and transparent methodologies to address the customer requirements and deliver effective and efficient services on time. Our Adaptive Global Delivery model facilitates quick ramp up and ramp down of resources, reduces overheads, and improves productivity.  Located in the God’s own country - Kerala, India, CoolMinds Technologies operates from Infopark, Kochi. We are a privately held company, registered under the Registrar of Companies, Kerala, India.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('CORRA', 'Digital Commerce Agency', '+91 484 403 0222', 'Corra Technology Research and Development India Private Limited, Athulya Building, Ground Floor, Infopark Kochi, Kerala, India - 682030', 'hr@corra.com', 'corra.com', 'We are the agency that helps you make great decisions across your entire digital commerce ecosystem.Corra is the global digital agency that lifestyle brands trust to accelerate their growth. Working at the intersection of commerce technology and customer experience strategy, we are known for our unmatched ability to deliver comprehensive digital solutions to leading B2C and B2B retailers.  Over the past 15+ years, we have helped merchants enable and scale their commerce vision, channeling our expertise and passion in the Magento Commerce, Adobe Experience Cloud, SAP Commerce Cloud, and Shopify Plus platforms along with many vetted technology partners. Winner of Great Places to Work, we offer exciting and challenging projects with industry-leading companies, competitive health benefits, flexible work arrangements, ongoing career development, company outings, and tons of other bonuses.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Crossgen Technologies', 'IT Services', '', '0484-2992021', 'info@crossgentech.com', 'www.crossgentech.com', 'CROSSGEN as a system Integrator is at the leading edge of IT trans- formation which enables to hold its customers along with the fast-moving technology. We ensure that our services and solutions exceed customer expectation which includes support on mission critical systems there by improving the customer’s business and productivity. As a trusted partner of various brands, our solutions and services include Datacenter solutions, Networks, Hyper Convergence Solutions, Cyber Security, ERP, IOT, IT consultancy and, Data Analytics etc. The Company is BS EN ISO 9001:2015 & ISO 27001:2013 management standard certified. We work with clients through a combination of deep level understanding of their business needs, extensive technical knowledge and highly capable delivery teams.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('CSEIDC TECHNOLOGIES PVT LTD', 'FinTech', '', '+91 9037005084', 'cseidctechnologies@gmail.com', 'www.cse.com.sa', 'CSE is a well-known software company operating in the Kingdom of Saudi Arabia. For more than thirty years now, CSE has been providing software services to banks, ministries and private sector organizations. From Year 2000, CSE started exclusive focus on Financial Services Industry Solutions. CSE has around 1200 Man-Years of experience in delivering solutions to FSI Industry in Saudi Arabia.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Cubet Techno Labs Pvt.Ltd', 'IT Services', '', '0484-4054324', 'infopark@cubettech.com', 'www.cubettech.com', 'We are ''Cubet'', a young and vibrant software firm located in Kerala, ‘the God’s Own Country’, India. Within a short span of our operations we have proven to be a team of highly competent technocrats passionate about providing the best customer support. Our clientele is spread across the globe and we believe in customer delight and going the extra mile to make their business a success. We understand our clients’ business requirements and collaborate with them to deliver customized solutions to suit their business strategies. This provides them with the necessary competitive advantage making them winners in their own arena."');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Currentware India Pvt Ltd.', 'IT Services', '', '+91-484-4055678', 'india@codework-solutions.com', 'www.currentware.com', 'Codework is an international software services company with offices in North America, Europe and Asia. Codework provides a vital source of innovative tools to help I.T. managers and Network administrators automate, improve and manage their systems. Our software utilities address the areas of PC Cloning, Software Distribution, Employee or Student Internet Access Restriction, Application Usage Blocking and Metering, Remote Control, Software / Hardware Asset Management. Disk Space Management, Print Quota / Reporting and more! Our dedicated development team will use their knowledge and experience to maximise the effectiveness of your business processes, integrate existing systems and build dynamic bespoke solutions. We are able to work with a variety of platforms and technologies which enable us to solve the most demanding of business problems and deliver the optimum solution in terms of performance, functionality, reliability, security and cost effectiveness.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('CVS Info Solutions Private Limited', 'IT Services', 'Ground Floor, Lulu Cyber Tower 1,  Infopark Phase 1, Kochi', '918921947372', 'Aditya@cvsinfosolutions.com', 'www.cvsinfosolutions.com', 'As a premier provider of comprehensive software solutions, CVS Info Solutions empowers businesses with next-generation digital solutions. We offer a wide range of technology services, including Enterprise Applications, Cybersecurity, Cloud & Infrastructure, Platform Operations, Consulting, Quality Engineering.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Cyberion Software Solutions Pvt. Ltd', 'IT Services', '', '+91 9995801261', 'hr@cyberionsoft.com', 'www.pharma-erp.com', 'Cyberion Software Solutions (www.cyberionsoft.com)  is a technology-driven enterprise specializing in the development of advanced software solutions, with a strong focus on AI-enabled ERP systems for the pharmaceutical and manufacturing sectors. Our comprehensive service offerings span the entire software development lifecycle — from product design and coding to testing, deployment, and ongoing support. We are committed to delivering high-performance, scalable solutions that address the complex operational and compliance needs of regulated industries.  At Cyberion, we actively integrate emerging technologies such as Artificial Intelligence (AI), Blockchain, and the Internet of Things (IoT) into our platforms to enhance traceability, regulatory compliance, and operational efficiency for our global clientele. Driven by innovation and guided by industry best practices, Cyberion Software Solutions empowers businesses to achieve digital transformation through intelligent, secure, and future-ready enterprise applications.  Cyberion Software Solutions delivers a single, powerful ERP platform for the entire pharmaceutical industry. Integrating Pharma 4.0 intelligence, our solution seamlessly connects manufacturing, distribution, and pharmacy operations. We replace complexity with clarity, providing the AI-driven tools to automate processes, guarantee compliance, and accelerate business growth from production to patient.  PharevX (www.pharma-erp.com)  B2B SaaS ERP is an AI-, Blockchain-, and IoT-powered enterprise platform designed exclusively for pharmaceutical manufacturing and distribution companies. It unifies operations across Sales, CRM, Finance, HR, Inventory, Regulatory, and Compliance, enabling real-time decision-making, predictive insights, and end-to-end process automation. Built on the latest Microsoft stack, PharevX offers enterprise-grade security, multi-company scalability, and cloud-native reliability, delivering operational excellence and digital transformat');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Cybrosys Technologies Pvt. Ltd.', 'IT Services', '0484 320 0080', '1st Floor, Thapasya Building,  Infopark, Kakkanad,  Kochi, Kerala 682030', 'info@cybrosys.com', 'www.cybrosys.com', 'Cybrosys is a well-established ISO Certified software Development Company which provides quality services all over the world. We serve our widespread customers around the globe via our offices located in London, Bangalore, Kochi, and Calicut We have been working on solutions exclusively geared towards industrial firms for past 10+ years. Our partnership with technology leaders like Microsoft, Sun, IBM, Symantec, and Odoo assist us to thrive to the best of industry standards. Odoo ERP services being our core area of work, we are also into Source code sale, Custom software development, and Employee outsourcing. We always been the pioneer in embracing new technologies and now our latest developments are in technology of the time ‘Blockchain’   Contact: info@cybrosys.com, Ph: +91 (0) 4943015006/7. Cybrosys Limited 2, Sheen Road, Richmond, London England, Cybrosys Techno Solutions,The Estate, 8th Floor,Dickenson Road,Bangalore-560042,India,+91 (0) 8606827707,TW9 1AE. Cybrosys Technologies Pvt. Ltd.1st Floor, Thapasya Building, Infopark,Kakkanad,Kochi, Kerala,India-682030.+91 (0) 4843200080,+91 (0) 8606827707');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Daddara', 'IT Services', '', '8921062753', 'mail@daddara.in', 'daddara.in', 'Founded in 11th September 2012, Daddara E-Traders (India) Private Limited is set out itself to be a E-Commerce and ERP Company. The company is predominantly engaged in the field of developing custom web/mobile applications for businesses like Hospitals, Societies, Educational institutions  and industries like Industrial, manufactures and Construction. The company is classified as non-Govt and is registered as per Companies Act 1956.   OUR TEAM   We have a team of highly trained and skilled professionals, which take great care in ensuring that the final product is always delivered on time. Our team includes Multimedia Designers, IT Consultants, Graphic Designers, Marketing and Project Management staff. They all have extensive new media experience and know their industry inside out. We are a full-service agency, but retains the flexibility to ensure that it can work with clients in whichever way suits them best.   OUR PRODUCTS   Educational Institution Management Application Healthcare Management Application Hotel Management Application   OUR SERVICES  ERP Development & Implementation Web & Mobile App Development Ecommerce Development Corporate Website Development  INDUSTRY AREA  Construction Retail Manufacturing Resellers Health IT Education Hospitality Logistics');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Daskalos virtual Academy pvt Limited', 'EdTech', 'GA-2 , ground floor, Indeevaram. Infopark , Nalukettu Road , Koratty, Thrissur- 680 308', '+91- 9778968024', 'hiring1@90plus.in', 'mytuitionapp.com', 'Daskalos Virtual academy Pvt Ltd is a Bangalore based edu-tech Startup. The company carried out research on digital tuition concept in 2015 and launched its first phase classes in the play store in 2018 for Kerala state syllabus students. The company also launched classes for CBSE Syllabus, and other State Syllabi in 2021. Technology changes every second, minute, and day. With the fast lane-changing technology and discovery of new roads, we drive towards introducing digital tuition classrooms for state syllabus as well as CBSE Syllabus. “It’s not a lecture; it’s smartainment” - A smart way to teach and learn! Tuition classes will never be the same again! With a fevered team of educators, teachers, animators, and management we created material for the state syllabus aiming at the Indian market. What is 90+ Digital Tuition? Kids and Parents will love it all the same!90+ My Tuition app - It’s more than just a tuition class. It’s a class you can never forget, as it gets imprinted on your mind forever. Moreover, it’s an easily accessible digital tuition class that can be viewed multiple times at your own ease and convenience. Kids will want them and parents will be content to offer them to their children. They will find it fun to study and attaining high scores will finally become easy. It’s a stress-free method even for the parents as you can crosscheck how much the students have advanced through their lessons and how much scores they have attained in their mock tests. You can freely let them take their exams knowing beforehand that they will attain a 90+ score.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Dataequinox', 'IT Services', '', '919074083251', 'connect@dataequinox.com', 'www.dataequinox.com', 'Dataequinox Technology and Research Private Limited is a leading IT Products and Consulting Services company that provides innovative solutions in FinTech, Retail, Communications, Productivity, DeepTech, and AI domains. We were founded in 2020 with a vision to help businesses overcome their most pressing challenges through cutting-edge technologies and customized solutions. Our team comprises of experienced professionals who are experts in their respective fields and are committed to delivering high-quality solutions that meet the unique needs of our clients. Over the years, we have built a reputation for our innovation, reliability, and commitment to customer satisfaction. We work closely with our clients to understand their specific needs and develop solutions that are tailored to their requirements. Our solutions are designed to help businesses optimize their operations, improve efficiency, reduce costs, and drive growth. We are constantly exploring new technologies and trends to stay ahead of the curve and provide the most advanced solutions to our clients.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Datafloat Technologies India Pvt Ltd', 'Real Estate Tech', '', '0484 2975161', 'hrindia@idcglobal.com', 'www.idcglobal.com', 'Datafloat is a software development company specialized in Real Estate Industry, Headquartered in New York and focused on the needs of progressive real estate companies throughout the world.  Our goal is to provide a suit of products to help agents and brokerages, and understanding premium real estate brokers business with low execution risk and succeed through MLS web search, agent site delivery, and a comprehensive suit of data products showing deep market trends and analysis.  With a deep background and understanding big data, and what it takes to communicate and anaylize that data to consumers across different markets and knowledge. We are experienced in Full real estate company/brokerage web site and search solutions, including a compeltely responsive model encompasing universal MLS search and Agent and office web sites focused on brand persistence and lead generation.  The company prides itself in exceptional customer service and response times, and systems that work from the moment they launch.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('DATAMATRIX INFOTECH PVT LTD.', 'Industrial IoT', '', '+91 9527956959', 'thomas@datamatrixinfotech.com', 'www.datamatrixinfotech.com', 'Datamatrix is a technology company Established in the year 2000. The company offers a Technology Platform for Virtualisation & Continuous Performance Optimisation of Industrial & Building Utilities, Saving Energy & Water.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Datum Innovation', 'IT Services', '', '0478 2554009       Mob: 9961734403', 'jobs@datuminnovation.com', 'www.datuminnovation.com', 'Datum Innovation is a software & Web development company based in India and we employ highly qualified engineers to provide the end to end software / Web solutions for the business or service sectors. The company was founded by a team of enthusiastic IT specialists who wanted to overcome the routine and create a company that would act in the market not only for business success but for the sake of Technology itself. Thus the mission of the company was defined - to contribute to forward –looking transformation of the society through software / Web development. Over five years of work. we have developed a range of solutions and gained ample experience in the services we offer: Custom Software Development and Web Development. Our specialists have been providing Software / Web development services for multiple clients from KSA');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('DBiz AI Solutions Pvt. Ltd.', 'IT Services', '', '9995617998', 'ThePeopleDesk@dbizsolution.com', 'dbiz.ai', 'We’re a lucky few, who get to help organisations with their digital transformations.  Through collaboration and empathy, we uncover ways our combination of art and engineering can help companies tackle challenges, and find ways to innovate. It’s difficult to stress that first part enough - our bond with our clients is what allows us to contribute meaningfully.  An organisation built on an ever growing series of specialised communities, it’s our goal to elevate the people that make them tick.  Cloud engineering, Devops, Experience design, Data & analytics, Rapid application development - the list is long and continues to grow as our 600+ people strong team grows.  Our teams span the globe, and we aim to continue growing, so do reach out if you’re keen for a chat!  … and if you’re sitting on digital challenges or ideas yourself, let’s figure them out together!');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Dee and Lee Services', 'IT Services', '', '919293811572', 'hr_talent@deeandlee.com', 'www.deeandlee.com', 'Dee & Lee Limited is a dynamic digital solutions provider specializing in AI-driven technologies, custom web development, and scalable product applications. With development centers in the UK and India, the company empowers businesses with cutting-edge tools to drive digital transformation and maintain a competitive edge. By leveraging artificial intelligence, cloud computing, and mobile-first design, Dee &Lee Limited enables organizations to optimize operations, enhance decision-making, and improve efficiency through machine learning, predictive analytics, and automation. The company’s expertise spans Progressive Web Apps (PWAs), cloud integration, and enterprise-grade mobile solutions tailored to meet evolving business needs. Committed to innovation, Dee & Lee Limited stays ahead of industry trends by integrating emerging technologies such as IoT and advanced cloud computing. Businesses looking to future-proof their operations can rely on Dee & Lee Limited for strategic, high-impact digital solutions. For more information on how the company can support growth and transformation, interested parties are encouraged to get in touch.');
