INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Dimensions Cybertech India Pvt. Ltd.', 'IT Services', '', '080-61860333', 'info@dimensionslive.com', 'www.dimensionslive.com', 'Dimensions Cybertech (India) Pvt. Ltd. is the flagship company of the Dimensions group, a conglomerate providing quality IT and IT enabled solutions and services to the global clientele. Dimensions Cybertech (India) Pvt. Ltd. has a corporate office at Technopark, Trivandrum, and development office in Infopark, Cochin. Being located at the major IT hubs in Kerala (India) that are rapidly becoming major IT resource centers for multinational Information Technology business, give us a strategic advantage.  Dimensions has been empowering small and medium enterprises with IT solutions with highly motivated and extremely skilled people, we have bought the world of totally integrated and automated environment to such diverse fields. Working hand in hand with our clients to properly understand their business needs and having extensive technical expertise, we identify and implement major value-adding prospects. An understanding of available technologies and how to apply them, the ability to muster the resources to implement those technologies, and the project and program management skills to oversee the implementation is our core strength. Employing industry-standard cutting-edge technology Dimensions strives to bring operational efficiencies to new heights and expands our client’s business reach to new “dimensions.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Distinct Infotech Solutions', 'FinTech', '', '+91 9074508742', 'hradmin@distinctinfotech.com', 'www.distinctinfotech.com', 'Since 2005, Distinct Infotech Solutions has been delivering innovative software solutions for the money exchange and financial services industry. Headquartered in the UAE and serving clients across the Middle East, Asia, and Africa, we support over 50 clients in 13 countries. Our scalable, web-based technologies help businesses streamline operations, enhance customer experiences, and make smarter decisions. Alongside our software expertise, we provide strategic outsourcing with AI-powered recruitment to build high-performing teams. At DIS, we are more than a technology provider — we are a trusted partner driving growth and innovation in financial services.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('DOCGIANT SERVICES INDIA PVT.LTD.', 'Healthcare', '', '6282503130', 'hrd@docgiant.in', 'www.docgiant.com', 'DocGiant Services India Pvt Ltd is an innovative technology platform and services company that is focused on solving the medical record management for Workers compensation, auto, liability and legal domain.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Dooth Internet Service Pvt. Ltd.', 'IT Services', '', '+91 9249097368', 'hrindia@dooth.com', 'www.dooth.com', 'Dooth Inc., is a private internet that extends the public internet, but that safeguards the individual''s identity and data. To envision such an ''impossible'' platform, instead of looking for technologies and innovations, Dooth looks back into history to find an ethically staunched profession (''Dooth,'' a royal messenger) in the ancient Indian civilization that guaranteed the privacy and security of messages exchanged in a far superior way than what the modern technology guarantees. Dooth extends the technology era by offering a ‘Private Internet’ to extend the public Internet. It is built with the vision to offer unparalleled security and privacy to organizations that care to safeguard confidential or classified information. All activity on the Dooth platform is private, encrypted, and free from intrusion. Dooth does not snoop, mine, or sell client data. No tracking, no profiling, full end-to-end, person-to-person and device-to-device encryption? shielded, invisible and architected to scale on Android, iPhone and the web.');
