INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Edstem Technologies Pvt Ltd', 'IT Services', '', '+91 9048738807', 'info@edstem.com', 'www.edstem.com', 'Edstem Technologies is a complete software solutions partner you can trust in building challenging software projects. We are delivering projects from 2012 onwards for our clients across the globe, and has been instrumental in developing best in class solutions, in latest technologies. We are the experts who can bring in undiluted expertise, can keep you innovating and are easy to work with to solve your business problems. Our Specialization lies in: •  Custom Software Development for Web and Mobile apps •  User Experience (UI/UX) design for Web and Mobile apps •  Senior professionals engagement for remote teams •  Product and Project Management •  Business as Usual teams for Software Maintenance and Support •  Software Quality Assurance Why Us? Some of the reasons why our customers have been choosing us for all their technological needs - •  We are a team of highly skilled, committed and process oriented experts, capable of delivering high quality software •  We follow agile based software delivery model with proper collaboration and milestones •  We only engage senior consultants to solve your business problems who are willing to share the knowledge back to your team •  We believe in customer delight, our experts will always be available even after project delivery with extended warranty and support');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('EGC Global Services India Pvt Ltd', 'Industrial Distribution', '', '+91 9946567777', 'egcgshr@psmicorp.com', 'www.egcgs.theegc.com', 'EGC Global Services India Pvt Ltd is a 100% Subsidiary Ewie Group of Companies Inc (EGC), headquartered in Ann Arbor Michigan USA. EGC is the 27th largest industrial distribution firm in the world. We have presence in 16 countries supporting 250+ programs and are growing rapidly. EGC is considered to be a leader in adoption of new practices and technology solution which in turn provided value to customers leading to substantial cost savings. EGC specializes in procurement and integrated management of indirect material and related services. In addition, EGC provides value added services related to subtractive manufacturing engineering support, CMM program management. EGC comprises of the following brands - EWIE, PSMI, Sourcepro, EGC Supply, GSNS EGC Global Services India Pvt Ltd, as a Shared Service Center, provides captive services to the group companies across – Technology, Procure to Pay, Order to Cash and Master Data Management processes. This division was incorporated in 2021 at Kochi, Kerala India to provide support for the global business with primary focus on EMEA region.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Electrifex Technologies Pvt. Ltd', 'IT Services', '', '+91 8590137646', 'info@electrifex.com', 'www.electrifex.com', 'We deliver end-to-end automotive software products and services across embedded and cloud domains.  Our embedded team develop advanced Software-Defined Vehicle (SDV) platform for automotive ECUs, specializing in Linux and Android BSP, hypervisors, audio DSP, security, and Edge AI.  Our cloud team build AI-enabled solutions for the automotive industry. One of our key products is a Zuul-based CI/CD platform for Software-Defined Vehicle (SDV) development across complex multi-company and multi-geography programs while ensuring quality, safety, and security compliance. With deep expertise in React, Python, Kubernetes, SQL, and cloud-native technologies, we deliver end-to-end platforms for modern automotive development.  Trusted by leading OEMs and Tier-1 suppliers worldwide, our integrated capabilities shape the future of connected, intelligent, and software-defined mobility.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('ELEMMENT FAÇADE Pvt Ltd', 'Construction', '', '+91 8089894683', 'info@elemmentfacade.com', 'www.elemmentfacade.com', 'ELEMMENT FAÇADE Pvt Ltd (EFPL) is a leading provider of Building Envelope Modeling services, mainly serving clients in Canada and North America. Established on January 2, 2024,  EFPL specializes in Building Envelope Modeling, using state-of-the-art software like AutoCAD, Revit, and Inventor. Our services cater to the diverse needs of clients involved in construction and architectural projects. Focused on precision, innovation, and efficiency, EFPL ensures optimal solutions for complex building envelope requirements.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Empay Software Solutions Private Limited', 'FinTech', '', '0484-4865189', 'info@empaysoft.com', 'www.empaysoft.com', 'Established in 2008, Empay Software Solutions Private Limited is an Information Technology and Services Company focused on Banking and Financial Software Application Development and Support   Our feature rich solutions cater to business and operational needs of Banks, Non-Banking Financial Institutions and Third-Party Service Providers in   •  Transaction Management & Reconciliation  •  Merchant Management, Billing & Settlement  •  Card Schemes Clearing, Settlement & Dispute Management  With the core team background, vast experience and expertise in business, operations and technology nuances of these domains, our solutions and services are custom fit to the constantly changing business and operational needs of our clients.  DOMAIN EXPERTISE  Empay Software has proven experience in development and implementation of solutions in the Cards and Electronic Payments domains. We have a clear focus in engaging customers in these domains and our primary goal is to assist our customers to achieve their business goals with state of art solutions and services rendered by our team at effective rates.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Empress InfoTech', 'IT Services', '', '0484-4042440', 'hr@empressinfotech.com', 'empressinfotech.com', 'Empress Cybernetic Systems Pvt Ltd (dba Empress InfoTech) is a global provider of software solutions, products, and information technology consulting. Empress has built a team of software professionals with ample expertise and exposure to cutting edge tools and technologies in the IT industry. We pride ourselves on delivering smart, flexible, and reliable products and services to our customers and exceeding their expectations. Our services include Digital Asset Management Services, Web Development, E-commerce Solutions, Custom Software Development, Application Support and Maintenance, Database Development and Maintenance, Business Intelligence and Data Warehousing, and IT Staffing. eMAM™ is our flagship product, a web-accessible media asset management software system created to organize, share, archive, and repurpose your digitized content: videos, audios, images, and documents. This powerful platform is loaded with features and a range of options to meet the diverse needs of organizations small and large.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Emsyne Technologies Private Limited', 'IT Services', '', '0484-6677602 , 0484-6677604', 'jobs@emsyne.com', 'www.emsyne.com', 'Emsyne Technologies Pvt. Ltd. is a well-established software development firm based out in Kochi, Kerala, India. It is the Information Technology Subsidiary of the Muthoot Group.  We are a global customized product development and consulting company with broad-spectrum capabilities that enable us to offer services like banking and non-banking software solutions, ERP solutions, web and mobile apps development, e-commerce development, big data analytics, machine learning, AI, outsourcing, cloud, DevOps and testing.  Emsyne is certified ISO 9001:2015 for Architecture, Design, Development, Testing, Implementation and Support the Software Products and Solutions developed based on the requirements of customers.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Endeion Engineering Services Pvt.Ltd.', 'AEC Technology', '', '+91 88489 06400', 'info@endeion.com', 'www.endeion.com', 'ENDEION provides BIM services to clients worldwide in the AEC industry. Our core offerings include BIM solutions for Architecture, Structural, MEP, Civil/Infrastructure, and Mechanical services. We assist clients in integrating and maximizing the latest BIM strategies seamlessly into their commercial, industrial, residential, educational, and healthcare projects, while meeting predefined timelines, standards, and budget requirements, ensuring they achieve maximum returns on their investments.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('EnergyScape Renewables LLP', 'Renewable Energy', '', '+91 9207130069', 'info@energyscaperenewables.com', 'www.energyscaperenewables.com', 'Established in 2019, EnergyScape has succeeded as one of the dominant providers of full-fledged Solar CAD (Computer Aided Design) Designs and Engineering services to key US developers and EPCs across the global market. We leverage our profound knowledge towards AHJ and comprehensive understanding of regulatory compliance in the solar PV industry to draw concepts that receive rapid approval. EnergyScape can flawlessly head up with the whole aspects of solar engineering requirements that include stampings and seals, structural/roofing evaluations and letters, post-installation letters load/arc-fault calculations, load consumption reports, and so on throughout the 50 states We do also deliver energy-yielding estimations and other essential analytical support for the ventures that even include energy storage. Being a prominent vendor in retailing qualitative Solar PV designs, we are keen on building a long-term partnership with the leading co as a prominent vendor in retailing qualitative Solar PV designs, we are keen to build a long-term partnership with companies. Over the past two years, we have stuck to maintaining the time deadlines and happened to meet highly modified standards made through facilitated processes. OUR SERVICES SITE EVALUATION- Provide site-specific information and Energy Scape Renewables can provide customized Site Survey Documentation, Shade Analysis, Feasibility Studies, Power Purchase Agreement stats, Electrical and Interconnection review, Structural and Roofing review, and more! The right assistance to help you provide quality assessment and kickoff your projects   SALES PROPOSALS- We are fully capable of using clients’ sales proposal software of choice and providing detailed reports for your customers. Sales Proposals allow users to create designs that help customers and potential clients get a visual idea about what solar systems can do for any application. We are capable of providing load calculations and usage estimates or reviewing previou');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('EPI-USE India Pvt.Ltd.', 'IT Services', '', '+91 9778316023', 'hr_cochin@epiuse.com', 'www.epiuse.com', 'EPI-USE is part of groupelephant.com, which employs more than 3,000 people in 33 countries. We are known as the world’s largest and most experienced independent SAP HR/Payroll specialist, and designs, builds and implements Cloud-based, hybrid and on-premises HR/Payroll systems for large, complex multinationals. 1% of our revenue is applied to the protection and preservation of at-risk elephants and rhinos, through a strategy that is based on poverty alleviation. EPI-USE Services for AWS is an Advanced AWS Partner, providing managed cloud services, rapid migrations to AWS, and bespoke AWS-based systems for clients in need of reliable, scalable, and highly redundant managed cloud infrastructure. Website: https://www.epiuse.com/aws-services/');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Epixel Solutions Pvt Ltd', 'IT Services', '', '+91491 2970123', 'info@epixelsolutions.com', 'www.epixelsolutions.com', 'Epixel Solutions is a customer-centric digital transformation company anchoring its services in a diverse technological arena. We transform digital processes into incredible customer experiences with a human-centric approach. Our range of services include cybersecurity, data analytics, data migration, application services, cloud services, blockchain services, automation, and integration, promising an end-to-end digital transformation approach.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Eqsoft Business Solutions Pvt Ltd', 'IT Services', 'Vismaya, Infopark Kochi Phase 1, Kakkanad, Kochi', '9946017660', 'hr@eqsoftglobal.com', 'eqsoftonline.com', 'We Eqsoft Business Solutions Pvt Ltd,  are a leading name engaged in providing most reliable & effective Software Development, Mobile App Development, Web application development and website developing services to the clients.  Eqsoft is a software development company from Kerala, India since 1995. Our solutions takes your business beyond traditional accounting software by streamlining operations across your entire organization and providing you with the real-time visibility you need to make better, faster decisions.  We are a combination of domain expertise, exceptional engineering talent, rigorous practices and commitment to every project. Our professionals render a large range of technology services and solutions that address the IT needs of various verticals of businesses.  Currently we have operations at India, UAE and Malaysia.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('ESSBEE TECHSTRATEGIES PRIVATE LIMITED', 'IT Services', '', '4802082033', 'contact@essbee.ae', 'www.essbee.ae', 'Established in 2021, EssBee Techstrategies pvt. Itd emerged in Kochi, Kerala, as a visionary IT startup dedicated to crafting state-of-the-art technology solutions. Our journey has now transcended Indian borders, reaching into the heart of the GCC market with our strategic office location at Dubai Investment Park. Our Vision is to lead the way in the GCC region with innovative and transformative IT solutions that empower businesses in the digital age. We''re on a mission to customize top-tier IT strategies that fuel growth, efficiency, and digital evolution, leveraging the latest technologies to turn your strategic goals into reality. We specialize in providing tailored IT solutions that address the distinctive challenges faced by mid to large sized enterprises in the GCC region. Our aim is to equip businesses with transformative IT strategies that streamline operations and catalyze success in a competitive market landscape. | Excellence | Speed | Security | Business Optimization | Empowerment | Efficiency | Services offered: • Software Development • Ai development • Website and e- commerce development • Mobile application development • Internet of Things ( IoT) • Cloud storage Specialties:Custom software development, Internet of Things (loT), E-commerce solutions, Artificial Intelligence, Mobile application development, Web application development, Cloud-based solutions, Data analytics and visualization, Cybersecurity and network protection, Blockchain development, Augmented and virtual reality, Machine learning and deep learning, Natural language processing, Business intelligence and reporting, Ul/UX design and development, DevOps and cloud infrastructure management, Agile development methodology, Software testing and quality assurance, IT consulting and strategy, Emerging technologies research and development. Industry: IT Services and IT ConsultingCompany Size: 11 - 50 employees, iHeadquarters: Dubai, DubaiBranches: • ESSBEE IT INFRASTRUCTURE ESTP.O Box 2337739,');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Estro Tech Robotics and Innovations Pvt Ltd', 'Retail Technology', '', '+91 7306153206', 'contact@estrotech.in', 'www.estrotech.in', 'Estro Tech Robotics is a trailblazing Kerala-based startup that is revolutionizing the retail industry through advanced Robotics, AI, and IoT technologies. With an unwavering focus on innovation and a commitment to excellence, we are pioneers in delivering groundbreaking solutions that redefine the retail industry. Our flagship product, RobAd, is an in-store marketing device designed to revolutionize in-store promotions in supermarkets. Combining cutting-edge technology, customizable features, data acquisition capabilities, and an unparalleled experiential factor, RobAd is a true game-changer in the retail industry. We aim to transform the conventional shopping journey into an extraordinary and immersive experience. At Estro Tech Robotics, we are driven by relentless curiosity and a passion. Our team of experts is constantly pushing the boundaries, exploring new frontiers, and developing innovative products that will reshape how retailers operate and customers engage with brands.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('EXACORE IT SOLUTIONS PRIVATE LIMITED', 'IT Services', '', '918138916160', 'career@exacoreitsolutions.com', 'www.exacoreitsolutions.com', 'Are you an IT professional looking for an exciting and dynamic career opportunity? Look no further than Exacore IT Solutions!  Who We Are: At Exacore, we are a leading IT solutions company with a strong focus on ERP Consulting. We are experts in implementing top-tier ERP systems, particularly Oracle. Our commitment to excellence and innovation has led us to assemble an exceptional team of developers specializing in cutting-edge Web and Mobile Technologies. We offer comprehensive end-to-end Managed Services, encompassing ERP cloud hosting, DBA services, and ERP Support services.  Our Journey: Our journey began with a team of former Oracle Consulting experts, and we quickly made our mark by successfully implementing Oracle ERP solutions for major brands. Our deep consulting experience and domain expertise enabled us to expand our portfolio to include ERP deals in SAP. Not stopping there, we ventured into building bespoke bolt-on solutions for ERP systems using Web and Mobile Technologies. We have structured our delivery into specialized departments, including an Infrastructure Department designed to provide complete solutions to our customers when they close ERP deals.  Our Customer-Centric Approach: At Exacore, we pride ourselves on being a customer-centric organization. We believe in actively listening to our clients and responding swiftly to their needs. Our dedicated Customer Engagement Team acts as a vital link between our clients and our delivery team, ensuring that customer expectations align seamlessly with their investments. We keep our clients informed about the latest industry trends through our domain experts and provide valuable advice to help them gain a competitive edge in the market. Our client-facing teams are empowered to offer flexible solutions within budget constraints, and we remain product-agnostic, always prioritizing our clients'' ROI.  Innovation and Growth: Exacore is committed to innovation and staying at the forefront of technology. We inv');
