INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Exponential Digital Solutions Pvt.Ltd.', 'IT Services', '+91 471 254 4210', '', 'connect@10xds.com', 'www.10xds.com', 'About 10xDS: Exponential Digital Solutions (10xDS) is a new age organization where traditional consulting  converges with digital technologies and innovative solutions. We are committed towards partnering      with clients to help them realize their most important goals by harnessing a blend of automation,      analytics, AI and all that’s “New” in the emerging exponential technologies. 10xDS caters services      across the Globe with operations in Dubai (UAE), Manama (Bahrain), Trivandrum and Kochi (India).     We have a strong and multifaceted team of experts with extensive business consulting and      technology experience. 10xDS has witnessed exponential growth over a span of just three years with      employee count crossing 120, wide partner ecosystem, and massive scale institution building.      From Shared Services to Innovation, our team has gained broad exposure and experience in their      journey with a Big 4 company.  This includes setting up a Global Shared services team which is now a     huge 4000+ organization. Our team was instrumental in setting up an Innovation Hub for the      company. Teams for Analytics, RPA, Cognitive and Cyber security were established ahead of time      and institutionalized.      Leveraging our functional competencies, we were able to set up services for Assurance, Audit, Tax,      Advisory and Transaction advisory services where the functional experts along with technology teams     added value for the Big 4 firm. The team also successfully established connection with universities      and start-ups to ignite and instil the spirit of innovation.     Today, we are treading an exponential path of growth, delivering many successful and transformative      engagements, designing and creating new business models, business advisory partnerships and      Center-of-Excellences! More importantly, we are building an unassailable trust and confidence from      our customers, partners and employees.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Extravelmoney Technosol Private Limited', 'FinTech', '', '9072000850', 'join@extravelmoney.com', 'www.extravelmoney.com', 'ExTravelMoney is an online marketplace for foreign exchange and remittance services in India. We empower students and travellers going abroad to make the Right and the Best choice when it comes to booking foreign exchange services from RBI authorized banks and money changers near their locality.');
