INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('FDC Web Technologies Pvt Ltd', 'FinTech', '', '7025118844', 'recruitment.india@financial.com', 'https://financialcom.jobs.personio.de/', '“Our Employees Are Our Most Valuable Asset.”  financial.com, a leading German software company, has been at the forefront of innovation since 1999. Specializing in the development and operation of cutting-edge web-based information systems for internet, intranet, and wireless solutions, we serve over 350 financial institutions across 19 countries. Our clientele includes prominent banks, broker firms, exchanges, and authorities who rely on our bespoke e-finance solutions to streamline their daily operations.  In a strategic partnership with LSEG, we process over 5 million financial instruments from more than 10 million international exchanges and OTC sources in real-time. Our solutions cater to over 100,000 intranet seats and numerous internet users worldwide, ensuring seamless access to critical financial data and services. Join us and experience the future of financial technology with financial.com!  You can find more information about us at https://www.financial.com/');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Feathersoft Info Solutions Private Ltd', 'IT Services', '', '+91 7736028401', 'careers_kochi@feathersoft.com', 'www.feathersoft.com', 'Feathersoft Info Solutions Private Limited');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Fine Destination', 'Business Consulting', '1st  Floor| Lulu CyberTower-1 SEZ- Infopark PO, Kakkanad  Kochi, Kerala, India-682 042', '7012155322', 'Career@finedestination.co.in', 'www.finedestination.co.in', 'We are a consulting firm dedicated to helping small businesses and start-ups realize their full potential and succeed in today’s competitive market. Our mission is to provide guidance, support, and strategic solutions that enable these companies to overcome challenges and achieve sustainable growth. At present, our main area of expertise lies in assisting businesses with the outsourcing of their operational processes, particularly within the travel industry. We specialize in working with travel wholesalers and destination management companies, helping them streamline their day-to-day operations. By facilitating the outsourcing of core functions, we enable our clients to focus on their strengths, reduce overhead costs, and operate more efficiently in their chosen markets. Our consulting services are designed to provide tailored recommendations that address the unique needs of each business, ensuring they can respond effectively to industry changes and increasing competition. In summary, we empower small businesses and start-ups—especially in the travel sector—to optimize their operations through smart outsourcing strategies, setting them up for long-term success and growth.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Fingent Global Solutions', 'IT Services', '', '0484-4055006', 'careers@fingent.com', 'www.fingent.com', 'Fingent is a "Great Place to Work" - certified global IT company providing strategic IT business solutions and services for complex business problems in multiple industry sectors including retail, real estate, healthcare, finance, education, and more. We believe that the judicious use of technology, together with a good design can reduce complexity, connect individuals, and provide valuable insights, all of which ultimately help businesses succeed. Fingent delivers business solutions utilizing technologies such as end-to-end Microsoft Suite, Database Management, Business Intelligence, Reporting, Analytics, AI, AR, VR, Open Source, Cloud, and leading Web and Mobile Application Development technologies. Established in 2003, Fingent today is one of the leading custom software development companies with offices across the USA, the UAE, Australia, and India. Our offshore development centers are located in Kochi, Trivandrum and Banglore  To know more about us please visit:  www.fingent.comhttps://www.youtube.com/c/FingentCorp/videoshttps://www.linkedin.com/company/fingent-technologies/mycompany/https://www.instagram.com/fingentcorporation/https://www.facebook.com/Fingent');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('FIRMINIQ SYSTEMS', 'IT Services', '', '916284303739', 'hr@firminiq.com', 'www.firminiq.com', 'FIRMINIQ is positioned as a reliable technology partner for end-to-end software product development offering comprehensive services in UI/UX Design, Mobile Development, Web Development, Backend & Middleware, QE, Cloud & DevOps. With offices in USA (Texas & Chicago) & India (Chandigarh & Kochi), we are a globally distributed team specializing in connected healthcare. We work with start-ups, independent software vendors, and established companies across the globe.   Our people are central to our success. We encourage not just professional excellence but also the overall personal development of each member on our team. With regular meetups, interactive sessions, well-being talks, health & fitness initiatives; we focus on overall employee growth. Rewarding, fun, compassionate and packed with ample opportunities to learn and grow – is what life at FIRMINIQ feels like. We offer unlimited opportunities for learning, leadership, growth, and teamwork.    Every decision we make and every action we take is backed with this core understanding in mind – “We’re only as good as our employees.” Our collaborative and dynamic environment ensures employees understand their value and are equipped with the right resources, opportunities, and experiences to excel and grow. We offer not just perks but real benefits in the form of – Competitive Compensation & Bi-annual Appraisal, Quarterly & Annual Bonus, On-site Work Opportunities, Flexible Hours & Hybrid Work Model, Holidays & Paid Time Off, Paid Courses, Health Insurance for Family & a lot more!   For more details, you may visit: www.firminiq.com');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Flycatch Infotech Pvt. Ltd.', 'IT Services', '', '+91 7736830531', 'Opportunity@flycatchtech.com', 'www.flycatchtech.com', 'Flycatch is an IT services and digital solutions company headquartered in Riyadh.   The company has a strong focus on Data Management and Data Engineering services, helping organizations build robust, scalable, and well-governed data foundations as a prerequisite for successful AI and advanced analytics adoption.  Flycatch specializes in the design and implementation of data platforms, ETL/ELT pipelines, data warehouses, and cloud-native data architectures, enabling businesses to unlock value from their data and make informed, data-driven decisions. In addition, the company delivers custom software development, cloud-based applications, application maintenance, and digital transformation solutions.   Flycatch works with both Indian and international customers, with operations extending across regions such as the USA, Africa, and Saudi Arabia. The company’s core focus is to help organizations prepare their data ecosystems for AI-driven use cases by defining the right data architectures, governance models, and operating frameworks. Flycatch is committed to delivering practical, technology-driven solutions, with a strong emphasis on innovation, reliability, and long-term client partnerships.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Focal ME Design Solutions Pvt Ltd', 'Construction', '', '4802082974', 'me@focalpm.com', 'www.focalpm.com', 'Focal Project Managers business is to provide professional management services on construction programs and projects from conceptual design and planning through project close-out.  We function as the project owner’s technical advisor and manage design consultants and construction contractors on our client’s behalf, without conflicts of interest. Our job is to bring projects to completion on time, within budget and to the specified quality, with attention to the prevention of claims.  Our staff of construction professionals includes project, and construction managers, engineers, architects, schedulers, cost engineers, inspectors, sustainability specialists and permitting experts.  Since our founding in 1999 we have provided project management services and cost consulting to major building projects in Greece and other Southeastern European locations often under critical time pressures involving complicated decision making.  With extensive industry expertise, we take pride in delivering exceptional engineering services. Our offerings include MEP Engineering, Sustainability, Structural Engineering, BIM modeling, Value Engineering, AOR, Supervision.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Focaloid Technologies Private Limited', 'IT Services', '', '+91-484-7136778', 'careers@focaloid.com', 'www.focaloid.com', 'Focaloid was established in 2013 and since then has grown into a trusted technology partner for businesses worldwide. We work with the world''s top brands, leading enterprises, small & medium businesses and innovative startups, delivering end-to-end technology services. We provide cutting edge digital solutions to our clients, enabling them to adapt and thrive in the digital economy.  Focaloid''s specialists have extensive experience in delivering innovative and cutting-edge solutions across industry verticals. We focus on delivering secure & scalable software solutions that provide a simple yet compelling user experience. We pride ourselves on being a true partner and not just a vendor to our clients. Collaboration, continuous learning and a spirit of innovation are at the core of Focaloid''s culture. We are present in 4 cities around the globe, and our delivery center is based in India.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Founding Minds software Pvt.Ltd', 'IT Services', '', '0484-4042200, 4042202', 'hr@foundingminds.com', 'www.foundingminds.com', 'Founding Minds Software Pvt Ltd is an Intellectual Capital firm, which invest in and develops products in various industry verticals. Founding Minds Software works strictly to help building products for its US counter partner Founding Minds Inc (FMI) which is a private company located in Fremont, CA, USA. Domain expertise : .net, Java, Android, iOS   Who We Are? •A technology incubator and development partner started in 2008. •A strong and growing team of 90+ professionals in San Francisco (USA), Dubai(UAE) and Trivandrum and Cochin(India). •Expertise in SaaS, Enterprise Web and Mobile solutions. •Build, Operate and Support competencies. •Marketing, IT and Support Services. •Grown mainly through word of mouth referrals.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Fragomen Immigration Services  India Private Limited', 'Professional Services', '', '5th Floor, Lulu Cyber Tower 1,  Infopark, Kakkanad Kochi 682 042, India  T: +91 484 3989077', 'snikhil@fragomen.com', 'www.fragomen.com', 'At Fragomen Immigration Services India Private Limited, our  immigration team is highly experienced in working with multinational  companies and other organizations that have significant operations in  India. Many of our professionals have worked with prominent Indian and  multinational organizations, giving us the knowledge and experience  needed to make certain that immigration matters are handled from a  multicultural perspective.  On a daily basis, we assist clients with the preparation and  processing of business visa and work permit applications, local  registration and in-country extensions for short- and long-term  assignments. We also link seamlessly with Fragomen Worldwide offices to  assist clients departing from India for virtually any destination  worldwide. Our professionals are seasoned in guiding clients on  immigration policy and program design, strategic planning, benchmarking,  best practices, and comprehensive program management. We also review  existing domestic immigration procedures and policies in order to help  our clients comply with international obligations. Fragomen’s leading-edge technology allows us to seamlessly integrate  with Fragomen Worldwide partner offices and service providers around the  globe to support comprehensive, efficient and effective application  processing.  Our corporate clients come from a wide range of industries, including  financial services, information technology, manufacturing, energy,  professional services, advertising and communications, insurance,  retail, and management consulting. Given our size, extensive experience  and flexibility, our account management teams generally comprise  professionals experienced in the relevant industry of the client. This  allows us to proactively utilize targeted immigration strategies as a  business advantage.Fragomen India is Fragomen Immigration Services India Private Limited,  operating exclusively as an immigration consultancy and not as a law  firm in India.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('G10X INDIA PRIVATE LIMITED', 'IT Services', '', 'Unit No. 204, 2nd Floor,  Tower A, World Trade Centre Infopark Kochi Campus, Kakkanad,  Ernakulam  Kerala, 682042', 'Contact@g10x.com', 'www.g10x.com', 'A company born to give back by DELIGHTING its customers. _G10X is a digital services, digital solutions, and products company, offering clients a unique advantage in the era of digital transformation across strategy, consulting, and technology services. We are proud to be the partner of choice for global organisations who have embarked on a digital transformation journey. Following a philosophy of having a focused customer base and creating customised engagement models, we are delivering value across systems of efficiency and systems of innovation. While our clients focus on key customer and corporate strategy, we help them rapidly realise those strategies by reducing legacy debt and getting existing systems digital-ready. By putting digital at the core of their business, clients not only accelerate value creation but also create a more intimate and hyper- personalised engagement with their customers. The DNA of our services include design-led engineering, cloud-native development, microservices driven architecture, DevOps, and CICD-led processes. Our service portfolio include Digital Services, Cognitive Services, Technology Services, and Cyber, Infrastructure & Cloud Services. Also, we have in-depth expertise in global outsourcing and competency augmentation services across geographies. _G10X is rapidly expanding its global footprint to ensure a seamless delivery of value to its global clientele. We have presence across North America, Europe, Middle East and APAC.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Galactico Express Solutions Pvt. Ltd.', 'Logistics', '', '9446373443', 'info@gecs.me', 'www.gecs.me', 'Galactico Express Solutions Pvt. Ltd.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('GALTech Technologies Pvt Ltd', 'IT Services', '', '04802951674, +91 6282845368', 'hr@galtech.org', 'www.galtech.org', 'GALTech Technologies Pvt Ltd was founded in 2007 as a Startup by Young Entrepreneurs in India and started its operations in Dubai in the year 2013 and in London in the year 2021. We provide a Complete Range of Digital Services, including Website design, Web and mobile Application Development, and Digital Marketing. We have our in-house team who are passionate and well adapted to the latest technologies. Our client base includes Small and Medium establishments from the US, Canada, the UK, Denmark, Australia, and Singapore. We have a physical presence in Dubai - UAE and London - UK. We are led by a Management with years of Experience in Information Technology.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Gapblue Software Labs Pvt Ltd', 'IT Services', '', '0484-4010593', 'hr.support@gapblue.com', 'www.gapblue.com/about', 'Unlocking the Power of Digital Transformation: Pioneering Technology for Businesses and AI-Driven Future-proofing. With 15+ years of experience and an unwavering commitment to innovation, Gapblue empowers businesses to harness the full potential of the latest technologies. We specialize in ERP, delivering quick and quality results that cater to the unique needs of our clients. Embracing emerging technologies such as generative AI, we drive digital transformation (DX) and help organizations stay ahead in a rapidly evolving business computing landscape. Year of establishment: 2012 Services offered: Enterprise Software Applications Consulting, Implementation- ERP, AI, Integration, Analytics, RPA Branches: • AI Practice• ERP-Supply Chain Management• ERP- Customer Relationship Management• ERP- Finance• ERP- Human Capital Management• Quality Assurance• Sales• Infra & Cloud Enablement• Integration• Business Intelligence• Product / R&D• Human Resources/Admin');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('GEOJIT TECHNOLOGIES PVT LTD', 'FinTech', '', '4842901901', 'hr@geojittechnologies.com', 'geojit.tech', 'Geojit Technologies Pvt. Ltd. (GTL) is a software solutions provider engaged in conceptualizing, designing and implementing end-to-end business solutions. GTL, owned by Geojit BNP Paribas Financial Services (65%) and BNP Paribas (35%), headquartered in Cochin, Kerala, India is combining the talent of a passionate team with the strong background of BNP Paribas. Our main domain expertise is in Financial Markets, covering at the one hand innovative and cost efficient solutions for Emerging Markets as India and the Gulf region and at the other complex and high performance requirements of mature markets as Germany and France. The main focus is related to lifeline digitization and mobile computing, the current evolution on the smart phone and tablet market is evident. When people communicate, mobile devices offer the easiest medium. We have received multiple Innovation Awards illustrating our professional and innovative path of success. Our team developed the 1st application in India to place orders on the Bombay Stock Exchange and National Stock Exchange using mobile devices. We provide the mobile trading solution on iPhone, Android and iPad platform for the leading European Online broker, Cortal Consors, in Germany and France. The International development center in Kochi is source of innovation and resources for BNP Paribas Personal Investors. Specialized to manage diversity and infrastructure challenges we have developed reliable mobile applications, cost efficient and user friendly. Using adapted network protocols to optimize the connectivity, we have fast trading solutions, reliable operating even on GPRS and on low cost devices (we support more than 1500 types of smart phones), also all major mobile operating systems (iOS, Android, Blackberry, Windows Mobile) are supported.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Gewan Info Tech Solutions India Pvt Ltd.', 'IT Services', '', '+91 75109 53184, +91 75109 53185', 'info@gewaninfotech.com', 'www.gewaninfotech.com', 'Gewan Info Tech Solutions India Private Limited, based in Infopark, Koratty, Thrissur is a wholly owned subsidiary company of Gewan Info-Tech Solutions LLC, headquartered in Abu Dhabi, UAE. The company delivers IT Services with a focus on the development and drive of innovative IT solutions for the hospitality, travel & tourism industries, starting with complex online booking engines and ranging to business process management tools and ending with business analytics and travel finance software while foreseeing tomorrow''s competitive needs. The pace of digitalization has grown exponentially over just the last few years, and this has upended carefully crafted business strategies of companies, forcing executives to future-proof their businesses while under the pressure of running their existing businesses. Gewan Info-Tech Solutions India Private Limited understands this uncertainty and helps customers enable their business strategy by prioritizing digital investments and transforming their businesses to leverage digital technologies. Gewan Infotech Solutions India Private Limited foresees tomorrow’s leisure needs for individuals and institutions and develops the tools for hospitality and travel & tourism businesses and enables them to deliver futuristic standards now.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('GIS AXIOM Pvt. Ltd.', 'IT Services', '', '+91 81380 17386, 9995917386', 'sales@gisaxiom.com', 'www.gisaxiom.com', 'GIS AXIOM Pvt. Ltd.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Gizmeon Technologies Private Limited', 'IT Services', 'Ground Floor, Phase II, Carnival Infopark, Infopark SEZ, Kakkanad, Kochi-682 042', '+91 9645833111', 'sunil@gizmeon.com', 'www.gizmeon.com', 'Gizmeon Technologies, established in 2013, is an IT Consulting & Services company founded by a small team of experienced IT professionals in Bangalore, India. Our professional team of programmers, project managers, and technology consultants provide customized digital transformation services. Gizmeon has pioneered the art of project delivery using Agile methodology to ensure high customer satisfaction by delivering the applications faster, cheaper, and with high quality. We engage customers throughout the project lifecycle allowing them to test and feel the product much before the actual delivery and incorporate feedback and changes to the application to ensure it matches their expectations. Our technical team has profound experience in building applications for Apple iOS, Android, Windows, and Smart TVs. Our consultants consider these applications an integral part of your business growth strategy and architect the application to give momentum to your business by utilizing the immense potential of the digital media world. Gizmeon can identify the best solution for your IT challenges and provide a quick and reliable service based on a customized delivery and flexible pricing model.  We explore all possibilities of IT technologies to recommend the best solution for you. We have mastered all the nine yards of digital transformation initiatives such as Enterprise Application, Analytics, Data warehouse & Integration, OTT, Live Commerce, Cloud, Full Stack Application Development, DevOps, and Automation.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Glitz IT Solutions', 'IT Services', '+91 480 2734 544', '''Rajamalli'', Infopark Thrissur Nalukettu Road, Koratty - 680308 Ph: +91 480 2734 544', 'care@glitzitsolutions.com', 'https://glitzitsolutions.com', 'Glitz IT Solutions is a global software solutions provider with over a decade of industry experience, delivering offshore outsourcing and product engineering services to IT solution integrators worldwide.  Our AI-enabled products include Bizcare, a comprehensive Care ERP, and Solace, an advanced Hospital Management System. Alongside product development, we offer mobile application development and consulting, with a strong focus on AI-driven implementations.  We have deep expertise in cloud computing, and all our solutions are SaaS-ready and designed to run seamlessly on cloud platforms. Our offerings are aligned with key industry verticals such as Healthcare, Transportation, and Financial Services.  Using the SCRUM methodology and a highly skilled engineering team based in South India, we deliver scalable, intelligent, and reliable solutions. We focus on long-term partnerships by providing consistent value, strong support, and AI-powered technology that helps our clients stay competitive in a fast-evolving digital landscape.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Global Infonet Inc', 'IT Services', '2nd floor, Carnival Infopark, Infopark PO, Kochi, Kerala, India-682 042', '9633138880', 'hr@global-infonet.com', 'www.global-infonet.com', 'Global Infonet is a Jacksonville, Florida based company that serves a  multitude of organizations nationally. We are a full-service IT firm  specializing in custom software application development, SharePoint  consulting, Software application Support, Strategic cloud  consulting/Windows Azure and Content Management Solutions. Our team is  customer focused and consists of dedicated professionals who understand  your business. We value the needs and goals of our clients and  consistently exceed their expectations. We are able to leverage experience, creativity and excellence to help  you achieve your goals. Whether it is through our status as prestigious  Microsoft Managed Partner Program, Microsoft Gold Certified Software  Development Company or our years of on the ground experience, we can  tailor a solution that is right for you. Global was named one of  Jacksonville Business Journal''s fastest growing companies and is an ISO  9001 certified company.  We''re not a big lumbering army of people who try to make your problem  fit a one-size-fits-all solution. Rather, we are like a Special Forces  Strike Team. We respond and deliver quickly, efficiently and accurately.  We are one of the best at what we do. Our customer-satisfaction record  proves this.  Global''s engagement model is unique in the industry. We are focused on  developing a long-term relationship with our clients and becoming  trusted advisors rather than just consultants.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Global Surf IT Pvt Ltd', 'IT Services', '', '8075490551', 'hr@globalsurf.ae', 'https://www.globalsurf.ae/ & https://www.gs-it.ae/', 'We are a Dubai-based IT company renowned for our technology-driven innovation and the delivery of comprehensive IT solutions and digital services through two specialized business units. With a growing client presence across the UAE, our operations are supported by a dedicated support and development team in Cochin, India  Digital Marketing Services. Visit us: https://www.globalsurf.ae/ Our digital marketing unit is a full-service digital marketing agency based in Dubai, dedicated to elevating brands through performance-driven creativity and data-backed strategies. With a focus on sharp design and intelligent planning, we craft digital experiences where every pixel and every campaign serves a clear purpose. Our comprehensive services include performance marketing, SEO, socialmedia management, web design and development, branding and creative solutions, and marketing intelligence - empowering businesses to grow, engage, and convert effectively in the digital space.  IT Consulting & Managed Services Visit us: https://www.gs-it.ae/ Our IT Solutions unit deliver cutting-edge and customized technology services across IT infrastructure, AV & ELV systems, cloud solutions, cybersecurity, and managed services. With a strong commitment to innovation and customer satisfaction, we help businesses leverage technology for growth, scalability, and security.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('GRAMPRO BUSINESS SERVICES PVT. LTD', 'Business Services', '', '+91 8714621795', 'contactus@gramproindia.com', 'www.gramproindia.com', 'GramPro Business Services (GBS) is a business solution provider, based in Thrissur, the banking capital of Kerala. Established on 2017, the objective of the organization is to facilitate the growth of Micro, Small, Medium and Emerging business enterprises by helping them redefine their business goals.   GBS focuses on delivering excellence, thereby ensuring customer delight. By adopting cutting-edge digital solutions and by providing creative solutions to business challenges, we outpace our competition and relentlessly sharpen our competitive edge. In other words, GBS is a centre for excellence for aspiring businesses. The no-compromise approach to quality speaks for the high standards we set for ourselves.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Grapelime Innovations Private Limited.', 'IT Services', '+91 484 401 1758', '1G, Carnival Infopark  Phase 2, Infopark Campus, Kakkanad, Kochi, Kerala, Pin - 682042', 'hr@grapelime.in', 'www.grapelime.in', 'Grapelime Innovations is an end to end technology solution provider for its clients across North America, Canada, Europe, Australia and India. With a highly skilled team and an agile implementation methodology which is carefully crafted to work on both onshore and offshore scenarios we provide product design and development consulting, application reengineering, data analysis and cloud computing services. With the rich experience in domains such as Health Care Solutions, Financial Technology Solutions, Ecommerce, Travel, Insurance and Business Automation Solutions we take pride in delivering web and mobile solutions in cutting edge technologies. We believe in creating value in relationships be it with clients or employees. More than the Quantity we value the Quality of delivery.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Greenworld International Enterprise  Private Limited', 'IT Services', '', '+91 9947407002', 'mail.greenworldin@gmail.com', 'www.greenworldin.in', 'GREENWORLD International Business Enterprise Private Limited is a socially responsible corporation established in 2019 by Dr. Vinodkumar T A (MBA, DMS, D.Litt-USA). We specialize in providing innovative solutions aimed at creating a sustainable future. Our team comprises technical professionals with extensive hands-on experience, specializing in partner login solutions, educational apps, business CRM, and backend support services.We offer India’s premier advisory services tailored for entrepreneurs, focusing on B2B partnerships. Our platform integrates virtual and physical resources, offering a wide range of products and services to support entrepreneurial visionaries. In today''s dynamic digital landscape, where innovation and technology converge, we stand as a beacon of excellence.As a leading force in Information Technology, we blend expertise, innovation, and client-centric solutions. Our commitment lies in delivering cutting-edge IT solutions that empower businesses to thrive in the evolving technological ecosystem. We extend our services globally, sharing our ideals with budding entrepreneurs, and providing them with top-tier technical and operational resources to realize their dreams with a commitment to GREEN core principles.Locations: • Technology Center: Thapasya Building, Infopark Phase 1, Kakkand, Kochi • Registered Office: Poomattam Complex, Kattappana, Idukki • International Offices: Uzbekistan, Canada, Australia, UK, Dubai, Singapore');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Grehasoft', 'IT Services', '', '+91 8921540183', 'info@grehasoft.com', 'grehasoft.com', 'Grehasoft is a top IT and digital services company located at Infopark, Kochi. We provide a wide range of IT services like website design and development, online shop (e-commerce) development, mobile apps, custom software, branding, graphic design, SEO, and digital marketing.  We focus on understanding our clients'' needs and offer smart, easy-to-use solutions to help their businesses grow online and work more efficiently.  At Grehasoft, you get everything in one place — from logo design, website creation, and branding to digital marketing and office software. We mix creativity with the latest technology to build strong brand identities and powerful digital platforms. We aim to help businesses grow steadily with practical, future-ready solutions that improve customer engagement, simplify daily work, and support long-term success in the fast-changing digital world.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('HashRoot Technologies Pvt Ltd', 'IT Services', '+91 484 404 1616', '', 'info@hashroot.com', 'www.hashroot.com', 'HashRoot is an ISO 9001:2015 and 27001:2015 certified Managed Service Provider specialized in providing Infrastructure Management Service, Software & Product Engineering, Network operations center, Data Analytics, Cloud Managed Services/Deployments, Containerization, IOT Engineering, IT Automation/DevOps and State of Art Security Operations Center around the globe. With over 16+ years of experience in working with major Data Centers, Banking sectors and ISPs, HashRoot continues to expand its expertise in managing, monitoring and delivering cutting-edge solutions to more than 55,000 servers/network nodes with 1000+ customers from 85 countries.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Hatio Innovations Private Limited', 'FinTech', '', '+91 8606434912', 'sonia@hatio.in', 'hatio.in', 'Hatio Innovations Private Limited is a fully owned subsidiary of IndiaIdeas.com Limited (“BillDesk”), India’s largest payment processor. Founded in 2017, we are an Engineering-First company with specializations in merchant solutions, digital wallets, neobanking and accounting. We build Highly Scalable, Real-Time software solutions capable of handling large volumes of fund flows and time-critical, sensitive information that help our partners to grow and scale their business.');
