INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('HH Back Office Services Pvt Ltd', 'Business Process Outsourcing', '', '0484-6715400', 'admin@hhbos.com', 'www.hhbos.com', 'HH BACK OFFICE SERVICES PVT LTD is promoted by a Team of professionals having expertise 20+ years in the field of Business Process Outsourcing. We are providing highly professional services in Finance & Accounting related jobs, end to end Revenue Cycle Management (RCM), Medical Coding, Data Base Administration (DBA) etc. We are a performance and results-driven organization that uses proven strategies to find the best solution that helps the client resolve an issue while enhancing our capability as a service provide');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Hotpack Global', 'Manufacturing', '', '9895677424', 'cochin@hotpackglobal.com', 'www.hotpackglobal.com', 'Founded in 1995, Hotpack Global is a recognized leader in both the manufacturing and distribution of foodpackaging products. Today, the company has operations in 13 countries which includes UAE, Saudi Arabia, Bahrain, Qatar, Kuwait, Oman, India, the UK, the USA, Morocco, Ivory Coast, Nigeria, and Australia. Within a limited span of time, the company has grown to become one of the leading players in the packaging sector because of its reputation for supplying quality products, its reasonable price structure, and outstanding service. Hotpack is seen as a one-stop shop that offers a complete range of packaging products for the HORECA, Retail, and Industrial Packaging sectors. It represents other major manufacturing companies worldwide and products are packed hygienically in modern and attractive designs and marketed under “Hotpack” (Disposable Range) and “Soft n Cool” (Tissue Range) brands. As a food packaging company, Hotpack has been certified with BRCGS, SEDEX, ESMA, PEFC, FSC, ISO 9001: 2015, ISO 22000: 2018, ISO 14001: 2015, ISO 45001: 2018 which ensures the top quality of its products. Hotpack was adjudged winner of the coveted Dubai Quality Award under the category of Dubai Smart Industry Award 2020 for the manufacturing sector. Hotpack today has 47 standalone Retail centers across the World offering 3500 plus Specialty range products. Also, www.hotpackwebstore.com is the region''s largest online store for food packaging products. Over the years, Hotpack has become a trusted brand with its excellent products, services, and continuous brand communication. Currently, Hotpack is Manufacturing 3500+ Products in its 14 Manufacturing Plants and we are employing 3450 people from 31 Nationalities.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('HTIC Global', 'IT Services', '#14, Tower II, Trans Asia Cyber Park, Infopark Kochi Phase II, Brahmapuram P.O., Kochi – 682 303', '0484 4042400', 'hr@hticglobal.com', 'www.hticglobal.com', 'At HTIC Global, our primary focus has been to deliver our customers’ with unparalleled experiences and we make sure to go the extra mile to achieve it. With time, our passion to create great customer experiences has only grown stronger and so did our growth.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Hubbell Burndy India', 'Manufacturing', '', '''Athulya'', First Floor, Infopark Kusumagiri P.O, Kakkanad Kochi - 682030', '', '', 'COMPANY PROFILE    Incorporated in India in May 2011, BURNDY Technology and Global Business Private Limited also known as Hubbell BURNDY India is a subsidiary of parent company Hubbell Incorporated.    Hubbell is a US based international manufacturer of quality electrical and electronic products for a broad range of non-residential and residential construction, industrial and utility applications. With 2012 revenues of $3.0 billion, Hubbell Incorporated operates manufacturing facilities in the United States, Canada, Switzerland, Puerto Rico, Mexico, the People''s Republic of China, Italy, the United Kingdom, Brazil and Australia. Hubbell also participates in joint ventures in Taiwan and Hong Kong, and maintains sales offices in Singapore, China, India, Mexico, South Korea, and countries in the Middle East. The corporate headquarters is located in Shelton, CT. The three Key Business Segments are Electrical Systems, Lighting Products and Power Systems.     Hubbell BURNDY India operates out of two locations : Hubbell BURNDY Business Solutions HBBS at Infopark, Kochi and Hubbell BURNDY Engineering Solutions HBES at International Tech Park, Taramani, Chennai.     Our Services    Hubbell BURNDY India has been founded with the objective of providing quality shared services to Hubbell and its affiliates.     Our pillars of support are               HBBS, Kochi   :      ·           Management   Information system   ·           Competitive   Intelligence & Market Research   ·           Product   Cross Reference Solutions   ·           Environmental   Compliance Engineering (ECE) Support   ·           Product   Information Management Systems Support   ·           Transactional   Solutions – Procurement & Finance   ·           Embedded   Services   ·           Website   & Mobile Application Development    ·           Infrastructure   Services   ·           ERP   Practices (SAP, BI, BO, MFG/Pro)                  HBES,   Chennai :      ·           Reverse   Engineering    ·      ');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('IBS Software', 'IT Services', '', '4847193700', 'receptiondesk@ibsplc.com', 'www.ibsplc.com', 'IBS Software''s mission is to transform how travel companies operate in a digital world by delivering next-generation products to accelerate growth, drive efficiency, and create differentiated customer experiences.We have achieved our leadership position by combining over 25 years of deep domain expertise with a comprehensive portfolio of modular SaaS solutions that facilitate and automate travel companies’ most mission-critical functions. We accelerate innovation and enable smarter, data-driven decisions at many of the world’s largest and most renowned airlines, airports, ground handlers, hotels, cruise lines, and energy companies. Our customers consistently recognize our customer-centric and partnership approach, along with our implementation track record, as additional value enablers that differentiate IBS Software from our competitors.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('iCodeBees Private Limited', 'IT Services', '', 'ph. - 98477 32355', 'info@icodebees.com', 'www.icodebees.com', 'iCodeBees Private Limited, a startup software company where our employees come first. We are a passionate team dedicated to creating innovative software solutions while fostering a supportive, inclusive, and employee-friendly culture. Founded in 2024, iCodeBees Private Limited is a collective of forward-thinking technologists, visionary leaders, and creative problem-solvers. Our mission is to revolutionize the software industry through groundbreaking solutions, all while ensuring our employees thrive both personally and professionally.');
