INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('IdeaGCS Private Limited', 'IT Services', '', '+91 9746126217', 'hello@ideagcs.com', 'ideagcs.com', 'At IDEAGCS, we bridge the gap between innovation and efficiency. Our expertise in MuleSoft integration and AI business intelligence allows businesses to harness the power of data-driven insights and seamless application connectivity. From MuleSoft API management to real-time data processing, we offer future-ready integration services tailored to meet the unique needs of enterprises.  We believe in transforming businesses through intelligent automation and advanced enterprise AI solutions, helping companies stay ahead in an increasingly digital world. Whether you are looking to optimize workflows, integrate cloud applications, or leverage AI-powered business intelligence, IDEAGCS is your trusted partner for end-to-end integration solutions.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('iLeaf Solutions Pvt Ltd.', 'IT Services', '', '+91-9746226403', 'careers@ileafsolutions.com', 'www.ileafsolutions.com', 'iLeaf Solutions is a leading software development company that specializes in cutting-edge MobileApplication Development by leveraging its innate off-shore value advantage. Our mobile applicationdevelopment and mobile platform expertise have provided exemplary solutions to our global client basefor over the few years delivering500+ mobile projects. We are committed to providing leading-edgemobile and smart-phone device technology at affordable costs to our global customers.iLeaf Solutions has expertise in mobile apps development on all popular mobile platforms; Android,iPhone and Windows Mobile. We are pushing the envelope of mobile platformcapabilities with the development of the most cutting-edge mobile applications for our customers. Weare assembled as a team of highly qualified mobile application developers, designers, creators and QAtesters who work on all existing and emerging mobile platforms for mobile apps development.We believe in providing our customer''s with Best Price, Best Quality, Best Reliability and BestSupport. Our strength is our customer base, their support, business relationship and advices which have helped us to get better by the day.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Impaqtive Technologies India Pvt Ltd', 'IT Services', 'Part F, 15th floor, Tower-2, Trans Asia Cyber Park, Infopark Kochi Phase 2, Ambalamedu P.O., Puthencruz, Kochi', '+91-9895633744', 'careers@Impaqtive.com', 'www.impaqtive.com', 'Impaqtive is a Salesforce Boutique which commenced operations in Feb 2021. From initial assessment of needs, to creating the experience design and roadmap planning, to system implementation while driving continuous innovation, Impaqtive partners with organizations at every stage of their Salesforce journey. Impaqtive has a 100+ employees, also known as Impaqters working across different geographies (India, US and Cayman) and continues to add to its salesforce practice. Its India office is located Transasia Cyber Park, Infopark Phase II, Kochi.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('In-Tech Group India Private Limited', 'Engineering Services', '', '+91 7907673191', 'india.talent@in-tech.com', 'www.in-tech.com', 'In-tech develops innovative engineering solutions for the automotive, rail, aerospace, and industrial sectors. in-tech GmbH was founded in Germany in 2002, while its India subsidiary, in-tech Group India Pvt Ltd., was established in Kochi, Kerala in 2022. In-tech has grown steadily since its inception and currently employs around 2300 people in more than 20 locations across 8 countries.   Our India location - Kochi is our first location specializing in Automotive Electronics, focusing on the development of autonomous, electric, and connected vehicles for the future. As a strategic development partner, we support our customers throughout the entire product development process: from development to system integration to after-sales. In addition, we offer innovative tooling solutions ranging from HIL systems to cloud-based test infrastructures.   Powered by Infosys: In 2024, in-tech became a subsidiary of Infosys Ltd. Now, as part of the Infosys family, we’re expanding our engineering services across multiple new delivery sectors and locations, working in close collaboration with Infosys teams on the engineering projects of the future.   Our Values - Our colour orange stands for liveliness, warmth, and dynamism. These are the values we live by! We are all about strong team spirit, fresh ideas, and a friendly, open working atmosphere. We call it the “Orange spirit”! At in-tech, we imbibe the best European and Indian work cultures by offering flexible hours and work-life balance. If you’re seeking a flexible and open working environment and wish to develop the technology of the future, we would love to hear from you.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('InApp Information Technologies India Pvt Ltd', 'IT Services', '+91 471 277 1800', '', 'hr@inapp.com', 'www.inapp.com', 'InApp is a software services company operating since 2000. Founded by a group of IT experts with several years of Big 5 consulting experience, InApp presently has offices in USA, India, Japan, a 400 plus strong team of software engineers and a solid client base ranging from Fortune 500 companies, Startups to SMBs.   We offer an integrated portfolio of software engineering services which include application services, product engineering, mobility solutions, programming services, testing service, Ul design services, games & infotainment.   We have a broad range of technical expertise across most major development environments, technologies and platforms. With 6 core technology expert teams, .NET, Java, PHP, testing, mobility, & UI design, we offer our best services in IT to our customers.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Incede Technologies Pvt Ltd', 'FinTech', '0484 2981 655', '17C, Tower-1, Trans Asia Cyber Park, Infopark Kochi Phase-II, Kochi Kerala-682030', 'careers@incedetech.ai', 'www.incedetech.ai', 'Incede, is a software product based company established by experienced banking technology professionals. With decades of expertise in product engineering for the BFSI sector, we are committed to transforming the financial services industry. Our focus is on delivering innovative, scalable, and high-quality software products and solutions. We aim to provide affordable, cutting-edge technology that enables our partners to excel in a constantly evolving market.');
