INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('IndustryApps Technologies Pvt Ltd', 'IT Services', '', '+91 99462 60111', 'director-india@industryapps.net', 'www.industryapps.net', 'We''re a team of industry veterans and Industry 4.0 thought leaders who have completed over 200 digitalisation projects. Our passion is helping businesses unlock the full potential offered by digital transformation and our mission is making these opportunities accessible to every organisation, regardless of size or industry. IndustryApps is built using open Industry 4.0 standards, ensuring universal compatibility. We deploy the latest technologies to create DataSpaces, Digital-Twins and Smart Factories to achieve holistic connectivity, visibility, traceability, control, and interoperability throughout a business and its supply-chain. This allows our customers to enhance their performance in all areas, from planning and purchasing to operations, sales, finance and strategic management.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('InerG Software Innovations Pvt.Ltd.', 'IT Services', '', 'World Trade Centre Block -1,  6th Floor, Unit no. 601, Infopark Kochi Phase 1, Infopark Kochi P.O., Kochi - 682042', 'hr@inerg.com', 'www.inerg.com', 'InerG Software Innovations Pvt.Ltd.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Infintor Solutions LLP', 'IT Services', '', '+91 99950 58321', 'info@infintor.com', 'www.infintor.com', 'Infintor – Your Trusted Partner for Digital Transformation Since 2014. As a globally recognized digital transformation consulting firm, Infintor has been delivering innovative solutions to enterprises and SMEs since 2014. With a proven track record and certification as an Odoo partner, we specialize in consulting, implementation, and customization of Odoo ERP, offering unmatched expertise to drive business growth. Our offices in India, Germany, Japan, Qatar, and the UAE enable us to provide tailored services to clients worldwide.  Our Core Expertise:  ERP Implementation: Seamless integration and customization of Odoo ERP systems.  Digital Engineering: Cutting-edge solutions to modernize your business processes.  Mobile App Development: Custom mobile applications for iOS and Android.  E-Commerce & Web Development: Scalable and user-friendly platforms to boost online presence.  AI & IoT Solutions: Intelligent automation and connected systems for smarter operations.  Digital Process Automation: Streamlining workflows to enhance efficiency and productivity.  Custom Software Development: Tailored solutions to meet unique business needs.  Global IT Solutions: Infintor offers offshore development services, employee augmentation, and Employer of Record (EOR) solutions, enabling international businesses to establish and scale their IT teams in India. Our end-to-end services ensure cost-effective, high-quality solutions for your digital transformation journey.  Partner with Infintor to unlock the full potential of technology and achieve sustainable growth.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('INFOCYLANZ PVT. LTD.', 'IT Services', '', '8921032682', 'info@infocylanz.com', 'www.infocylanz.com', 'INFOCYLANZ is a software development company and services include mobile development, website development, Cloud management, digital marketing, Artificial Intelligence and machine learning.Infocylanz have been paving the way for leading public and private organization with dynamic IT solution.Infocylanz provides customized and generic IT solutions to customers who require software to enhance their business practices. We provide solutions that will help to build a robust IT infrastructure by cultivating a Legitimate work culture. Infocylanz helps business to make smart decisions in adopting mobility solutions and take advantage of consumerization of IT. Infocylanz is a fast growing vibrant community of design and development experts. We are working in the business of finding ways to help our customers succeed. Infocylanz is a global product development and software company offering software development services.');
