INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Innovature Software Labs (P) Ltd', 'IT Services', '', '0484 - 4038120', 'hr@innovaturelabs.com', 'innovature.ai', 'Innovature is a global business consulting and technology services provider of high-quality IT solutions with ISO 27001:2013 certification. Over the last 15+ years, Innovature’s custom solutions and software products have served over 500 customers across the United States, Australia, Europe, and Asia. We focus on delivering digital and technology transformations that meet the strategic and business objectives of our customers. As an integrated software services company, our custom software development and consulting services spread across a diverse spectrum of technology verticals that include web, enterprise, convergence platforms, mobile applications, and emerging technologies. Our value-added services also span offshore software development services, business process consulting, and IT resourcing. Our digital software solutions and services have been delivered to clients in Retail, Advertising and Media, Education, Telecommunication, Healthcare, Utilities, Financial Service, and E-commerce. Some of the solutions given to our major clients in these industries are: "Social shopping solutions, Location tracking and recommendation, User counter & heat-map, B2B, B2C, and C2C solutions for E-commerce applications, Business intelligence, Data analytics, Web forms & questionnaires/online surveys & exams, Advertising and marketing solutions, Chat-bots, Cryptocurrency, and B2B solutions".');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Inntot Technologies Private Limited', 'IT Services', '+91- 484 298 5898', '', 'info@inntot.com', 'www.inntot.com', 'Inntot has SDR IP Solutions for Digital Radio Mondiale (DRM in AM and FM bands) Receivers, DAB/DAB+ Receivers, HD-Radio, CDR, ISDB-T and is all set to play a pivotal role in the Analog Sunset of AM and FM broadcast radio transmission paving way to Digital Radio Transmission.  Inntot Technologies is the winner of several prestigious awards including National Technology Awards 2021 of TDB, Government of India,  NXP Tech Startup Challenge 2022, Industrial Innovation Awards 2017 of Confederation of Indian Industries (CII) - for the Best Service Startup and Top 10 Promising Startups of India., ASSOCHAM 4th ICT Awards 2020, DRM Enterprise Award 2019 instituted by Digital Radio Mondiale Consortium.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Inspired Software Development (India) LLP', 'Gaming', '', '+91-9995229371', 'india.careers@inseinc.com', 'www.inseinc.com', 'Inspired Software Development (INDIA) LLP offers an expanding portfolio of technology services for regulated gaming, betting, lottery, social and leisure operators across land-based and mobile channels around the world. Inspired’ s gaming, virtual sports, interactive and leisure products appeal to a wide variety of players, creating new opportunities for operators to grow their revenue. Inspired is headquartered in New York.');
