INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Inspite Technologies Pvt.Ltd', 'IT Services', '#14 TBC, Thapasya, 4th floor, Infopark Phase1, Kakkanad', '9995543735', 'inspitetechnologies@gmail.com', 'www.inspitetech.com', 'Established in 2020, Inspite Technologies Pvt Ltd is a dynamic and innovative company headquartered in the Infopark Campus, Kakkanad, Kochi, with additional branches in the Government Cyberpark, Kozhikode, and Al Karama, Dubai. Our expertise spans a broad spectrum of digital solutions, including web development, web design, e-commerce development, mobile app development, custom software development, and branding. With a strong focus on integrating Artificial Intelligence into our services, we are dedicated to delivering cutting-edge, customized solutions that meet the evolving needs of businesses. Our team is committed to excellence, ensuring high-quality service delivery and customer satisfaction across all our projects.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Intbrains Private Limited', 'IT Services', '', '9th Floor, Phase 4, Carnival Infopark, Kochi, Kerala, India - 682042', 'hr@intbrains.com', 'www.intbrains.com', 'COMPANY PROFILE   INTBRAINS is a Technology Solutions & Product Company that offers a wide range of cutting edge Technology Services & Solutions to clients helping them manage, scale and grow business seamlessly.  Intbrains works with global companies to help them achieve their business goals as part of their digital transformation journey leveraging cutting edge custom technology solutions and services.Over the years, Intbrains has successfully delivered multiple, complex and critical projects for clients in the US, internationally and in India.   OUR TEAM  We are a young company, nimble in the way we work, with a value creation driven mindset. We are structured in our approach, transparent in our work and deliver complex projects that exceed client expectations. Our Technology, Product, Sales and Leadership teams come with years of world class experience. Our strength comes from our people who are aligned to work with the objective of delivering value through knowledge, expertise and keeping the client’s interest at the heart of every project we work on  OUR VALUES   Our culture and work ethics are guided by a philosophy engrained in each of us at Intbrains. This guiding principle is based on: 1. Transparency at work  2. A Client Centric Approach  3. Building Partnerships & Relationships based on Trust   SERVICES   Intbrains offers world class technology solutions to business challenges using cutting edge solutions. Services we offer include :  1. Remote Infrastructure Management  2. 24x7 Network Operations Centre (NOC) Services  3. Cyber Security Solutions  4.  Data & AI  5. Offshore Development  6.  Quality Engineering  7.  Cloud Solutions');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Intelliflo Software India Pvt Ltd', 'FinTech', '', '919605623900', 'infokochi@intelliflo.com', 'www.intelliflo.com', 'Intelliflo is a leading provider of software solutions to financial advisors, wealth managers, and financial institutions. Founded in 2004, Intelliflo has established itself as a trusted partner in the financial services industry, offering innovative technology solutions designed to streamline processes, enhance client engagement, and drive business growth.intelliflo?remains independent in operations to Invesco but draws from its strengths.After bringing together Invesco’s digital advisory solutions under our global intelliflo brand, intelliflo remains dedicated to powering the entire advisory lifecycle. We achieve this through our range of open architecture solutions as the global leader in financial advice technology. Key aspects of Intelliflo''s company profile include:Founded: 2004Industry: Financial Services TechnologyHeadquarters: United KingdomFounders: Nick Eatock, Rob WaltonOffices: London, UK , Atlanta USA, Bedford USA , Sydney Australia, Kochi India, Hyderabad India Products and Services: Intelligent Office (iO): Intelliflo''s flagship product, iO, is a comprehensive practice management system that integrates various tools and functionalities to help financial advisors manage their businesses efficiently. It offers features such as client management, financial planning, portfolio management, and compliance tools. Engagement Suite: Intelliflo provides a suite of client engagement tools to help financial advisors enhance their interactions with clients, including client portals, mobile apps, and communication tools. Business Management Tools: Intelliflo offers a range of business management tools to support operational efficiency, including reporting and analytics, workflow automation, and integrations with third-party applications. Client Base: Intelliflo serves a diverse client base, including independent financial advisors, wealth management firms, and financial institutions across the United Kingdom and internationally. Mission: Intelliflo is dedicated ');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Internland Technology Services Private Limited', 'IT Services', '', '7012460522', 'hr@interlandtech.com', 'www.interlandtech.com', 'Interland Technology Services (ITS), is one of the largest provider of banking, Education and Health care Solutions in Middle East and USA. We develop innovative and creative products and services that provide total communication and information solutions. Among the services, web design and development, tailor made applications, ERPS, CRMS, e-commerce solutions, business-to business applications, business-to-client applications, managed hosting and internet portal management are few that we offer. Satisfied clients around the globe bear testimony to the quality of our work. As a global solution provider, consulting and outsourcing company with global presence in 5 different countries, Interland offers the best in industry solutions and services to customers across different continents. As a leader in technology exploring, Interland is committed to exporting quality software services in the following verticals: Government Financial Services (insurance, banking and clearing house) Telecommunications Energy and Utilities Health Care Education Our emphasis is on offering a high degree of product user friendliness through a positive, creative and focused company staff. Domain expertise: Banking & Finance, Education, Health care, Oil & Gas, Tele Communication');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('iWEX Infomatics', 'IT Services', '', '919744783338', 'emails@iwex.in', 'iwex.in', 'iWEX Infomatics – Where Global Excellence Meets Local Innovation  iWEX Infomatics, proudly headquartered at Infopark Kochi, is a trailblazing women-led technology consulting firm making waves in the global ERP landscape. We hold the prestigious distinction of being the World''s First Frappe Certified Consultant for ERPNext Manufacturing, HR & Payroll – a testament to our exceptional expertise and commitment to excellence.  With over 150 thriving clients worldwide, we transform businesses across Manufacturing, Distribution, Retail, Services, and Non-profit sectors through intelligent ERP solutions powered by cutting-edge AI and automation. We''re pioneering the future by seamlessly integrating artificial intelligence into business workflows – from smart document processing and predictive analytics to automated data entry and intelligent decision support systems.  From comprehensive ERPNext implementation and customization to AI-driven automation, strategic consultation, and hands-on training, we deliver tomorrow''s solutions today. We don''t just deploy systems – we empower teams, eliminate repetitive tasks, and unlock unprecedented efficiency through technology that truly thinks.  Whether you''re an ambitious tech professional ready to master AI-powered enterprise solutions or a visionary organization eager to lead your industry, iWEX Infomatics is where innovation thrives and extraordinary careers begin.  Join us in shaping the AI-powered future of business.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Jachoos Technologies Private Limited', 'Digital Marketing', '', '+9181290 05574', 'info@jachoos.com', 'www.jachoos.com', 'jachoos Technologies Private Limited is a full-service Interactive Digital Transformation Agency founded 10 May 2018.It is an established IT and Media Company with an enviable and proven track-record engaged in providing Business Web Hosting, application development services, e-commerce technology, technology consulting, IT infrastructure solutions, digital and internet marketing services, video and animation making, music and audio solutions, content writings for various aspects, and various other IT and media services to clients worldwide. We are a fully in-house digital company focusing on branding, marketing, web design and development with clients ranging from start-ups to Fortune 100 companies. We pride ourselves on partnering with clients in order to give the most transparent and educational experience from scoping to deployment. Various branches of jachoos are:INDIA JachOOs Technologies Pvt Ltd? SBC 3, 3rd floor, Thapasya Building, Infopark Kochi - 682030? Manorama Memorial Building,2nd Floor, Aysha Rd, Ponnurunni, Vyttila, Kochi, Kerala 682019 Tel: +91 484 405 3219? Suite No: 3/411C, 1st floor, Munsif Court Junction, Kanjirappally, Kottayam, Kerala- 686506 UK71-75, Shelton Street, Covent Garden, London, WC2H 9JQ, England. Tel: +44 2032909011 UAEDataWave Technologies L.L.C, #1006, Warsan towers, Barsha Heights, Tecom, Dubai, United Arab Emirates, #1650, 16th Floor, Al Manara Tower, Business Bay, Dubai, UAE.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('JK Lucent Pvt Ltd', 'IT Services', '+91 480 208 1883', '3A-3, 3rd Floor, Indeevaram Building, KSITIL SEZ, Infopark Thrissur, Koratty, Thrissur 680308', 'careers@jklucent.com.au', 'www.jklucent.com.au', 'Headquartered in the innovation rich city of Melbourne, Australia, with an operations centre nestled within Infopark''s Special Economic Zone (SEZ) in Thrissur, Kerala, JK Lucent stands at the forefront of the IT services industry. As a dedicated provider of cutting-edge IT solutions, we specialize in a comprehensive suite of services designed to propel businesses into the future.   At JK Lucent, our philosophy is rooted in the integration of cutting-edge technology with personalised service to create dynamic solutions that drive our clients'' success. Our Australian roots grant us an understanding of western business cultures, while our presence in Kerala taps into a rich vein of tech talent, allowing us to offer a unique blend of innovation, efficiency, and competitive pricing.  Our Vision: To be a leading IT services provider, recognised for innovation, customer-centric solutions, and transformative outcomes.Our Mission: To empower businesses worldwide through high-quality IT services and solutions that drive efficiency, innovation, and growth.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Jobin & Jismi Pvt. Ltd.', 'IT Services', '', '7034499822', 'contactus@jobinandjismi.com', 'www.jobinandjismi.com', 'Jobin and Jismi was founded in 2012, we are one of the global providers of Business Solutions with cloud-based ERP Oracle NetSuite. We serve clients from multiple industries across the globe. Fueled by passionate professionals, we are committed to delivering client-specific solutions and premium services. We are the official partners of Oracle NetSuite, BigCommerce and Celigo. Our core services include NetSuite Implementation, Customization, Integration, Administration, Optimization and Consultation. We also offer E-Commerce services ranging from Adobe Commerce (Magento), Shopify, WooCommerce, SuiteCommerce and BigCommerce. We have a sizable team and a very well-functioning lab facility for industrial automation, IoT, and AI initiatives. We promise the best experience to our clients and ensure our working hours overlap with major global time zones.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('JohnTuringWatson Software Solutions Pvt Ltd', 'Artificial Intelligence', '', '9188933408', 'johnturingwatson.ai@gmail.com', 'johnturingwatson.ai', 'We empower businesses of all sizes to harness the transformative potential of AI, Machine Learning, Data Science, and the modernization of legacy systems, without the burden of upfront costs.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('JTSi Technologies India Private Limited', 'IT Services', '', '0484 - 4070368', 'hr@jtsiindia.com', 'www.jtsiindia.com', 'JTSi Technologies is a leading Software Development Business, IT Offshore Development Services and Professional Consulting Services company that provides cutting-edge business IT solutions and related services to clients around the world focusing on helping them to capitalize on the digital revolution by delivering innovative products to global markets. On an ongoing journey of continuous innovation, we deliver quality software, excellent services, and form meaningful partnerships.  Our development services are guided by our passionate and dedicated team, who combine expertise in technology and business domain knowledge to help you transform your business. Additionally, JTSi provides reliable staffing solutions across a variety of industries, providing industry-specific expertise.  With a relentless focus on efficiency and constant communication with our clients, we make sure that all projects are completed on schedule and on budgets. Whether you need temporary assistance or ongoing management of your technology operations, we can support your business.   SERVICES  SOFTWARE ENGINEERING SERVICES •	Custom & Enterprise Software Development •	Product Development Services •	Web & Mobile Application Development •	Cloud Application Development •	SAP Support Services  IT CONSULTING SERVICES •	Migration & Implementation Services •	IT Maintenance Services •	Software Testing Services  PROFESSIONAL SERVICES •	Recruitment & HR Services •	Accounting Services  SOLUTIONS •	OfficeGaps •	SurveyShield •	MRO for Aviation  Other industries/domains we serve include:  ·	Logistics ·	Automotive/Aerospace/Marine/Rail ·	Banking, Financial and Insurance ·	Power Energy, Utilities & Government ·	Healthcare ·	Design & Manufacturing  For more information, please contact info@jtsiindia.com or www.jtsiindia.com');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Kakapo Systems India Private Limited', 'IT Services', '', '+91 9946864488', 'talkindia@kakaposystems.com', 'www.kakaposystems.com/contact-us', 'Kakapo Systems is a software development firm specializing in user applications for the BroadSoft BroadWorks platform since 2006. The Unity applications for Call Center, Hosted PBX, Reception and Mobile provide easy access to the features of BroadWorks. Featuring an elegant user interface, the Unity applications enhance the call handling experience, optimizing customer service and workgroup collaboration.> The Unity applications for BroadSoft include Agent, Supervisor and Dashboard interfaces for the BroadSoft ACD solution and Desktop, Reception and Unity Mobile to supplement the BroadSoft Hosted PBX offering and in this way to sit across the spectrum of customer use cases. By providing deep integration to the features of the BroadSoft system in a rich and intuitive interface, Unity adds value to BroadSoft providers go to market offerings and their customer workflows. Corporate Office Locations 24 Holborn Viaduct, London, UK, EC1A 2BN9');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Katzion Technology Solutions LLP', 'IT Services', '', '0484 4858680', 'hr@katzion.com', 'www.katzion.com', 'We are a fast growing start-up, with some of the largest auto manufacturers in the world as valued  clients. As a Salesforce premium partner we are trusted to deliver innovative and creative solutions  using the power of Salesforce. We are quite humbled by the amazing journey we have been on since we started in 2017. Fast forward to 2021, we now have 6 offices around the globe, employing over 160 phenomenal  people who are creating amazing customer experiences for 14 large partners.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('KL Koncepts Lab Media and IT Park', 'IT Services', '', '8606119333', 'hr@konceptslab.com', 'www.konceptslab.com', 'Koncepts Lab is an IT and media company focusing on IT solutions, IT products, Branding, and Advertising. We are redefining possibilities to handle IT. This is done by providing business solutions and technology services beyond the level of expectations of our clients. We are well structured so as to bring in better results for a wide range of business needs and provide effective solutions for the problems you face in the Information and Technology sector. The success of our company is measured by how people share, enjoy, and obtain advantages from the efficacy we possess. We offer customised solutions based on the clients'' expectations. The products will be delivered with high quality at cost-effective rates within a specified timeline. We have built Koncepts Lab on strong foundations of commitment, competitiveness, and growth. Areas of focus 1.Digital Marketing 2.Website Development 3.SEO 4.Branding 5.Video & Visuals Productions 6.E-Commerce 7.ERP 8.IT Products & Projects');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('KnowBe4 India Private Limited', 'IT Services', '+1-727-748-4221', 'Unit No. 601A, 6th Floor, Tower A, World Trade Centre Kochi, Infopark Kochi Phase 1, Kakkanad, Kerala, India 682030.', 'info@knowbe4.com', 'www.knowbe4.com', 'KnowBe4, the provider of the world''s largest security awareness training and simulated phishing platform, is used by tens of thousands of organizations around the globe. KnowBe4 enables organizations to manage the ongoing problem of social engineering by helping them train employees to make smarter security decisions, every day. We are a Certified Great Place To Work in India and have earned numerous other prestigious awards, including Glassdoor''s Best Places To Work and Fortune’s Best Workplaces for women, millennials, and in technology.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('KOTT SOFTWARE PRIVATE LIMITED', 'IT Services', '', '0484- 2362860 / 2979898 / 2371741', 'info@kottsoftware.com', 'https://www.kottsoftware.com', 'KOTT Software is a global provider of enterprise business solutions with a dedicated clientele across USA, United Kingdom, South East Asia and India. Kott Software is a well-established since 1997 and ISO 9001:2015 certified. The company provides Offshore Software Development services and products in niche business verticals.  KOTT Software offers an exciting work place environment and have been delivering highly innovative and breakthrough solutions to our clients in Web technologies, Product Development, Mobile applications, Cloud based applications and Enterprise Resource Planning in select business domains.   KOTT Software has set up a new state of the art software centre of excellence in Infopark SEZ Phase II apart from our corporate office & development centre on M.G.Road, Kochi to expand our reach in the global markets.    KOTT Software has been a leading Information Technology solutions provider with a successful track record of providing business and technology consulting services to its global clients in various domain verticals including Fortune 100 clients in the USA and UK over the past decade and has clientele spread across USA, UK, Mauritius, Malaysia, Indonesia, Middle East and India. Viz; industries include:  *Travel and Logistics  *Warehouse Management   *In-flight Airline Catering Management  *Human Resource Compliance systems   *Trade & Export Compliance   *Retail & smart payment solutions        At KOTT, we value each team member and give each member the ability to Explore, Learn and Grow and reach his/her full potential. With individual empowerment, open communications, flexible processes focused on high performance client delivery, client engagement role, KOTT Software has a fun filled, exciting work environment. KOTT Software is a 100% Export Oriented Unit registered with the Software Technology Parks of India (STPI), a member of the Indo-American Chamber of Commerce (IACC) is and based in Kochi. Please visit www.kottsoftware.com for more inf');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Krythium Solutions Private Limited', 'Healthcare', '', '91 7511101166', 'info@krythium.com', 'www.krythium.com', 'Krythium is a provider of healthcare business intelligence, data science, and operational solutions operating from Kochi for over fifteen years. We offer payers, employers, health systems, providers, and care management companies in the United States of America, high-quality, effective solutions specific to their needs in the evolving healthcare market. Our innovation gives healthcare organizations the tools and information needed to positively impact clinical and business outcomes.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Lanware Solutions', 'IT Services', '', '+91- 9778423737', 'hr@lanwaresolutions.com', 'www.lanwaresolutions.com', 'Lanware Solutions (LWS) is a leading provider of information technology solutions and consulting services, dedicated to helping the world''s leading companies build stronger businesses.  Lanware Solutions designs, develops and deploys powerful integrated solutions for web, embedded, power, touchscreen and desktop applications. LWS provide hardware and software services to high technology industries with proven expertise in Embedded, Cloud, IOT solutions. LWS supports with a wide spectrum of strategic and tactical product and software development services.     We can help to drive some or all of your Product deliverable — whether developing a new product, migrating to new platform from a legacy framework, adding new functionality, testing or troubleshooting existing applications, we have the experience throughout the development lifecycle to solve a wide range of product development challenges. We provide complete teams of developers to tackle your entire project, single experts to augment your existing staff and everything in between.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Lektik Consulting', 'IT Services', '', '+91 8590316206', 'hr@lektik.com', 'www.lektik.com', 'Lektik Consulting is a premier venture studio that builds and co-builds innovative products, providing cutting-edge technology solutions tailored for enterprises—including many Fortune 500 companies. Our mission is to empower businesses to thrive in the digital era through state-of-the-art strategies and transformative solutions.   With a team of seasoned product developers, technologists, and AI experts, we deliver end-to-end solutions that drive growth, streamline operations, and elevate customer experiences. At Lektik, we focus on three core pillars:   Building Products We design and develop market-ready, scalable products that solve critical business challenges and unlock new opportunities. From ideation to deployment, we manage the entire product lifecycle with precision and expertise.   Co-Building Products By collaborating with enterprises and startups, we combine our technical expertise with their domain knowledge to co-develop innovative solutions. This partnership approach ensures shared success, accelerated growth, and seamless product integration.   Technology Partnership As a trusted partner, we offer comprehensive support—including strategy, development, implementation, and scaling. Our solutions are deployed across diverse industries such as finance, healthcare, government projects (including political campaigns and omni-channel advertising), insurance, real estate, and programmatic advertising. We have a strong footprint among Fortune 500 clients, helping them leverage the latest technologies to maintain a competitive edge.   Our customized approach ensures that every solution aligns perfectly with our clients’ objectives and unique challenges. By staying at the forefront of technological advancements, we provide our partners with the latest tools, strategies, and innovations to keep them ahead in rapidly evolving markets.   At Lektik Consulting, we believe in the transformative power of technology and collaboration. Contact us today to discover how ');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Linnk Outsource Solutions India Pvt Ltd', 'IT Services', '', '+91 9778418989', 'shibu.melath@linnk.com', 'www.linnk.com', 'Linnk Group operates in the field of software development, IT consulting and services. As a global IT solutions provider specializing in software development and digital transformation, our Infopark facility will primarily focus on software engineering, R&D, and client delivery services.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('LINXAS IT CONSULTING PRIVATE LIMITED', 'IT Services', '', '+91-8301076022', 'rvijayan@linxas.com', 'www.linxas.com', 'Linx-AS has core consulting practices in product lifecycle management (PLM), environment, health & safety (EHS), and enterprise user experience (UEx). We help large companies implement more profitable product development processes, make sure operations are within regulated environment, health & safety standards, and, overall, make SAP easier for people to access and use.  Additionally, our Innovations Division focuses on designing SAP-certified solutions and accelerators that provide faster time to value for our customers.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Loyal IT Solutions Pvt Ltd', 'IT Services', '', 'Devadaram,   Infopark Thrissur,   Koratty -   Nalukettu Rd Kerala 680308', 'info@loyalitsolutions.com', 'www.loyalitsolutions.com', 'Loyal IT Solutions Pvt Ltd, an Odoo Gold partner, is a company specialized in ERP Solutions, ERP Consultancy service and Managed cloud services. We started our operations in 2012 based in Kochi and has been successfully present in the market for almost 10 years, and since then we have grown to become a well-regarded player in the industry and has proven to be reliable, efficient and trustworthy service provider to the business from all over the world. We have been awarded with The Best Starter in India-2020 and Nominated for Best Odoo Partner in India-2021 award. Since our inception, we have released numerous projects for diverse business spheres, ranging from basic websites to highly sophisticated business automation solutions. Our proficiency in a wide range of modern technologies ensures the delivery of tailor made solutions to any requirements put forth by our client. We have a skilled team dedicated for our customers’ assistance and support.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('LucidPlus IT Solutions', 'IT Services', '', '0480 2731677', 'career@lucidplus.com', 'www.lucidplus.com', 'LucidPlus IT Solutions, a technology company with operations in Kerala, Bangalore and Pune, delivering custom digital solutions, services, and proprietary products. We build modern, secure, and scalable applications powered by cloud-native architectures, microservices, DevOps, and AI/ML. Our expertise spans modern tech stacks, intelligent document processing (OCR), multi-channel messaging (WhatsApp, SMS, Email, RCS, Viber), AI-driven chatbots, and smart enterprise applications. Our products, LP Ensemble and LP Converse, enable businesses to achieve greater efficiency, accelerate digital transformation, enhance agility, and unlock long-term value.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Luure.ai LLP', 'Artificial Intelligence', '', '0484-4867768', 'info@luure.ai', 'www.luure.ai', 'Luure.ai LLP');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Mantle Solutions Private Limited', 'IT Services', '', '0484-6633333', 'careers@mantlesolutions.in', 'https://mantlesolutions.in', 'Mantle Solutions is the registered offshore technology and professional services firm for LuLu Group International, a highly diversified conglomerate with business entities worldwide. Combining our digitally driven innovation and expertise in end-to-end operations, we connect every dot, reimagine the processes and reinvent the way LuLu Group works. From accelerating digital transformation, streamlining accounting services, structuring business processes, and managing HR services, we help LuLu Group carve the path of sustainable and lasting business outcomes.  Mantle Solutions began its operations in 2018 as an offshore IT service and BPO centre with its office in LuLu Cyber Tower- 2, Kochi. The company encompasses a staff strength of more than 1000 professionals, delivering services across a broad range of needs, creating a sustainable competitive advantage for LuLu Group International.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Mantra IT Solutions', 'Digital Marketing', '', '6282113506', 'info@mantraitsolutions.in', 'https://mantraitsolutions.in/', 'Mantra IT Solutions was founded in 2012 with the objective of providing top-quality, one-of-a- kind 360° branding and digital marketing solutions to customers so as to add value to their services, products, and offerings. We help businesses across the globe connect with their target audiences through high-quality, innovative, and creative web design and development services. We help businesses grow their online visibility and sales through our SEO, Google AdWords, social media marketing, and web design services. The quality of our services defines the skills and experience of our team of marketers.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('MapleTech Space Pvt Ltd', 'IT Services', '3rd Floor Indeevaram, Infopark Thrissur, Koratty PO, Kerala - 680 308', '7559923436', 'info@mapletechspace.com', 'mapletechspace.com', 'MAPLE TECH SPACE PVT LTD is formed by Mr. Rohith Mohandas and Mr. Jithin Parakka in 2021 who are also the co-founders of MAPLE TECH SPACE INC (MTS) which is an MNC with its headquarters in Canada (1325 Eglinton Ave E, Mississauga, ON L4W 4L9, Canada).  Mr. Jithin who is an IT professional for more than 10 years was earlier worked as the HOD of Computer Science Dept. of St. Thomas College of Engineering and Technology, Kannur. Mr. Rohith was the product manager of various technology products in Kodak Mahindra & ICICI bank before settling in Canada. While Rohith manages the business development and marketing of the organization in Canada, Jithin takes care of the technical solutions from Kerala. MAPLE TECH SPACE PVT LTD will be executing the projects taken by MAPLE TECH SPACE INC Canada. 200+ Canadian clients have signed up with MTS in the last 2 years. While MTS has clients from different verticals, we have concentrated more on the real estate segment and the majority of our clients are from this vertical.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('MarketBytes WebWorks Private Limited', 'Digital Marketing', '', '+91 88918 27272', 'hr@marketbyteswebworks.com', 'www.marketbytes.in', 'About Us  MarketBytes WebWorks Private Limited serves as your digital architect, specializing in website development, digital marketing, creative design, and search engine optimization. Our journey, which began on September 27th, 2023, is characterized by innovation and unwavering dedication. We excel at translating ideas into digital masterpieces, prioritizing a client-centric approach. With a team of seasoned experts, we collaborate to deliver bespoke strategies that drive tangible results. Our portfolio is a testament to our commitment to creating digital experiences that captivate and inspire.  Purpose  We exist to bridge the gap between the digital landscape and our clients'' aspirations. Our dedication lies in relentlessly pursuing excellence in the digital domain, with the ultimate goal of propelling brands forward in a world where technology, creativity, and purpose converge.  Vision  At the core of our vision lies a commitment to redefine success. We aspire to be pioneers of change, crafting a future where technology, creativity, and purpose converge to elevate brands and empower global communities.  Mission  Our mission is to be the driving force behind our clients'' digital success. We are passionate about empowering businesses to thrive in an ever-evolving world by providing them with comprehensive website development, creative designing, and digital marketing solutions.  Values  1. Transparency: No deception or illusions here. We believe in genuine interactions with all our clients. We communicate clearly about our intentions and follow through on our promises. 2. Integrity: We prioritize honesty and integrity, always aiming to cultivate relationships built on trust. We recognize that trust is earned through consistently upholding our unwavering standards. 3. Simplicity: We believe that expertise shouldn’t translate to complexity. We adopt a straightforward approach, always striving to simplify what may seem intricate. 4. Performance: In the world of di');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('MARLABS SOFTWARE', 'IT Services', '', '91 0484 6062885, 6062886', 'harsha.pramod@marlabs.com', 'www.marlabs.com', 'Marlabs  helps drive digital agility for our clients. We deliver innovative  business solutions using digital technologies such as cloud, mobile,  analytics, Internet of Things, and social. With a dedicated team of over  2,100 associates, a network of delivery centers in USA, Canada, Mexico,  and India, and strong partnerships with industry leaders, Marlabs  offers a wide range of IT services across industries. Through our  emphasis on quality driven by CMMi, PCMM, ISO 9001-2000, ISO 27001, and  SSAE 16 Type II best practices and a customer- centric client engagement  model, Marlabs has achieved a dependable track record of meeting high  standards of excellence in every customer engagement. This has resulted  in several awards and recognitions, including being consistently ranked  as one of the best places to work in New Jersey. Marlabs is  headquartered in New Jersey, United States.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Mashuptech', 'IT Services', '', '+91 4843514093, +91 8089612448, +91 6282589058', 'info@mashuptech.in', 'mashuptech.in', 'MashupTech, a leading software development and digital marketing company that envisioned and instigated the adoption of the flexible business practices that today enable our client companies to operate more efficiently and produce more value.With a rare mix of domain, technology & project management experts, we bring the most complete team to bear on every project we take on. Business & technology experts, from some of the best universities in the country, bring invaluable insights and expertise into their areas of expertise. MashupTech was established on 16-11-2021 with branches in Infopark TBC, Geo Infopark Kakkanadu and Kottayam.Mashuptech is dedicated to helping organizations everywhere digitally transform how they do business. And that starts with identifying the kind of IT support and services you need to be successful.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Maxxion Systems Private Limited', 'IT Services', '', '918547906576', 'mail@maxxion.com', 'www.maxxion.com', 'Started in 1996, Maxxion Systems Private Limited is a software development firm. Over the years we have built up a strong project portfolio of enterprise applications satisfying several clients across the globe, continuously re-investing in our services.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('McFadyen Digital', 'E-Commerce', '', '9495662507', 'djanardhanan@mcfadyen.com', 'www.mcfadyen.com', 'McFadyen Digital is powering the platform revolution, one marketplace at a time. Our customers are top brands and B2B organizations looking to take the next step in their digital commerce journey. We the provide strategic, technical, tactical, and operational expertise to evolve their online buying experience in a meaningful, scalable way. McFadyen Digital has a long history of delivering award-winning online marketplace and ecommerce shopping experiences, with over 250 successful projects involving platforms like Adobe Commerce (Magento), Mirakl, Shopify Plus, Oracle Commerce Cloud, Unirgy, and more. Through our close partnerships with top-tier technology vendors such as Adobe, Mirakl, and Oracle, McFadyen and our clients have received frequent recognition for the shopping experiences we help produce. As proud members of the MACH Alliance, we believe that composable commerce architecture is the path forward for marketplace and ecommerce sites.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Media Systems India', 'IT Services', '', 'INFOPARK SEZ PHASE II CAMPUS,  BRAHMAPURAM P O, PUTHENCRUZ, KUNNATHUNADU  PIN: 682303', 'prasanth.j@msisoft.in', 'www.msisoft.in', 'www.msisoft.in');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Merabt Technologies Private Limited', 'IT Services', '', '+91-7907092564', 'hr@merabt.com', 'www.merabt.com', 'Merabt Technologies Pvt Ltd, established in 2017, having known as a website development company in the initial stages have now blossomed into a global IT solution provider. Today, we create custom made web and mobile applications and dynamic digital marketing strategies for our customers. With a team of talented developers, designers, and managers, we’ve been able to make ourselves known to some of the big names in the industry and to help them redesign and power up their digital marketplace.We provide a host of services including Web Development, Mobile Development, Web Hosting, Web Designing, Graphic Designing, Social Media Management, Messaging Services, Internet Marketing and much more. Today, we have emerged as a complete global web solution provider catering to clients from across the world.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('MERP Systems Private Limited', 'IT Services', '', '918547117240', 'smadhav@merpsystems.com', 'www.merpsystems.com', 'MERP Systems is a new generation digital transformation services organization. MERP focuses on creating enterprise-grade software applications that supports case management and citizen-engagement processes using the Microsoft Power Apps platform. One such application is Freedom of Information Act (FOIA) or Public Record Access (PRA). Often described as the law that keeps citizens in the know, the Freedom of Information Act helps to provide the public the right to access records from any federal agency, and to promote the principles of openness and accountability in government. MERP specializes in creating such applications that promotes communications and collaboration for government agencies and private enterprises.   Creating a center of excellence in India is done with utmost social responsibility – uplift the youth in rural areas and empower them with access to world-class systems and processes. Leveraging cloud-based systems to support our operations, we are carefully contributing to a green ecosystem. We comply with paper reduction act by eliminating the need for any paperwork for onboarding and other business continuity operations tasks.   MERP is committed to creating exceptional growth opportunities for the resource base in India by successfully supporting the mission of our global customers and by adhere to the evolving standards of environmental sustenance.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Metclouds Technologies Pvt Ltd', 'IT Services', '', '0484-4030103', 'careers@metclouds.com', 'metclouds.com', 'Metclouds Technologies is an ISO 27001-certified IT services company providing Data-center Support, Cloud Consulting, DevOps, Remote Infrastructure Management, Web Application Development, and IT support in the USA, Europe, and the Middle-East. We have been at the forefront of technological innovation and customer satisfaction since its inception in 2010. At Metclouds Technologies, customer satisfaction is our top priority. We take pride in our ability to deliver 100% customer satisfaction consistently. Our team of skilled professionals is dedicated to exceeding client expectations by providing high-quality, reliable, and innovative IT solutions. With a strong commitment to quality and security, Metclouds Technologies holds the prestigious ISO 27001 certification, reflecting our dedication to maintaining the highest standards in information security management.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Milestone Technologies', 'IT Services', '', '91-484-4060800', 'recruiters-apac@milestone.tech', 'milestone.tech', 'Milestone Technologies (earlier Suyati) is a digital-first and CX focused company striving to engineer great experiences for digital customers. We collaborate with businesses to strategize and implement impactful digital initiatives that position our clients ahead of the competition. With our niche and rich expertise in CMS, CRM, e-commerce, and Marketing Automation, we help companies across the globe leverage their best on web and cloud through our platform integration, data analytics, and customer engagement services. To know more , visit our website : www.milestone.tech');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Millennium InfoLogic', 'IT Services', '', '+91 484 4856688', 'hr@millinfo.net', 'www.millinfo.net', 'Millennium infoLogic started it''s operations in 2009 as an offshore destination for streamlined order fulfillment services, mainly catering to M/s Millennium Mats, one of the largest manufacturers of Mats and Rugs in the world. Notwithstanding global slowdown and the inclement economic climate MIL has not slacked off from the growth path. From a single vertical in 2009, we have rapidly expanded our core areas of business to 7 verticals, each an independent service by itself. • Production Support (www.getmpower.net)  • Software Development • Graphics Design & Development • Business Processing • Market Research • Remote desktop support • Accounting Services');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Mindcurv Technology Solutions Pvt. Ltd.', 'IT Services', '', '0484 2100164', 'hr@mindcurv.com', 'www.mindcurv.com', 'Mindcurv is a pan-European IT services provider, headquartered in Germany, specialized in the implementation and management of enterprise e-commerce platforms. We are expanding our operations in India and we are looking for highly-motivated professionals to join our distributed team to deliver high-value services to our clients. Many Go Live. Few Thrive. We Know Why. We believe that the most important aspect of a job is being excited about it, having growth opportunities and working in a team you really like. Aside from all this you will find: A strong, relaxed company culture and exposure to partners both domestic and international, an international team with more than 200 passionate people from multiple countries that always challenges to find the best possible solution, a competitive remuneration package and a fun place to work! Our employees have delivered e-commerce enterprise applications across Europe in multiple verticals using the Agile Development methodology. We bring in cross-vertical domain knowledge, which helps our clients refine their e-commerce business strategies and thus gain a competitive advantage. We understand technology, but we also understand business and people. Simplicity is our driver and efficiency our way of working.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('MindLabs Consultancy Services LLP', 'IT Services', 'Tower 1, 16th Floor, Office A-1, Trans Asia Cyber Park, Infopark Kochi Phase II, Brahmapuram P.O., Kochi', '0484 4046900', 'hr@mindlabssolutions.com', 'www.mindlabssolutions.com', 'Mind Labs is an Indian multinational company that provides business consulting, information technology and outsourcing services. It has its headquarters in Kochi, India and offices in UAE and Africa. Our mission from the very first day has been to cultivate professional relationships with our clients to provide effective and reliable information technology solutions for their needs.Started in 2006 Mind Labs has implemented several prestigious projects, for global clients including Fortune 500 companies and some of the world''s largest institutions, and has won many accolades and client appreciation.The team consists of experienced senior resources with Skills and Domain knowledge across the following domains. Software Development, Usability Engineering, Server Side Management, Business Strategy, Coding, Programming, Branding, Interaction Designing, Information Architecture, and Quality Analysis.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('MindLabs Systems Pvt Ltd', 'IT Services', '', '9656056789', 'hrteam@mindlabssys.com', 'mindlabssys.com', 'Founded in 2007, Mindlabs has been a trusted partner for businesses worldwide, offering innovative and customer-centric technology solutions. Our expertise spans across web design, development, mobile app development, digital marketing and server support, with a commitment to delivering top-tier results that meet the diverse needs of our clients.   At Mindlabs, we prioritize understanding your unique business requirements and provide tailored solutions that are both practical and functional. We guide you through every step of the process - from selecting the right technology to crafting engaging, user centric designs that drive success.   Our team is dedicated to delivering high-quality, seamless solutions that empower businesses to thrive in the digital world. With Mindlabs, you can count on cutting-edge technologies, exceptional support, and a focus on ensuring your business achieves its goals.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Mitsogo', 'IT Services', '', '8921244876', 'hr@mitsogo.com', 'www.mitsogo.com', 'Mitsogo Technologies Pvt Ltd. is a trusted provider of Enterprise Mobility Solution under the brand Hexnode. The MDM offers application management, security management, email management, kiosk management etc along with device management. Hexnode MDM has found its way to all kinds of business sectors such as education, healthcare, transportation and even in high-security government fields  all over the world. The clutter-less UI and simplified workflow are what makes the solution more efficient and preferable.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('mitz AI Minds Pvt Ltd', 'IT Services', '', '9656730556', 'contactus@mitz.ai', 'www.mitz.ai', 'We’re a data company - Data Engineering Services Partner. Founded in 2020, with a vision to help businesses generate actionable insights from Data, be their partner of choice in Data & Analytics Projects, and deliver the values and insights gathered via world-class AI- powered Products.We add tremendous value to our clients by combining our deep expertise in Data & Product Engineering with high quality delivery capabilities and flexible engagement models.We are a 35+ member company based out of Infopark Kochi, with clients in India and the USA, along with a strong partner network to fuel our growth.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Mozilor Technologies Pvt. Ltd.', 'IT Services', '0', '8H, Tower 2, Trans Asia Cyber Park Infopark SEZ Phase II, Kakkanad, Kochi, Kerala, India – 682030', 'careers@mozilor.com', 'www.mozilor.com', 'Mozilor is a technology company that builds products to simplify work. Founded in 2017, Mozilor has developed two innovative product lines with a global presence - CookieYes and WebToffee. From Toyota, Reuters, KFC, Dominos, CNBC, Hilton and Renault to small businesses and startups, over 1.5 million websites rely on Mozilor to develop transformative customer experiences. Mozilor is a leader in the global privacy space with the highest market share in cookie compliance technology. Mozilor has built industry-leading products ranging from e-commerce add-ons, plugins and SaaS applications. Mozilor started as a one-person endeavor by Anvar TK and has grown to a team of 100+ people working from multiple time zones in over 10+ cities including London, Bangalore, Mumbai and Calicut. From recent graduates to professionals who’ve worked with the biggest names in tech, Mozilor’s team includes a diverse bunch of people who have found a place to build meaningful products. Domain expertise: Consent Management Platform, Cookie Compliance Technology, WooCommerce Plugins, WordPress Plugins.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('NAS Infosolutions Pvt Ltd', 'IT Services', '', '4802998676', 'Operations@nasinfosolutions.com', 'www.nasinfosolutions.com', 'NAS Infosolutions is a leading provider of SAP Business One implementation services, empowering small and medium-sized enterprises (SMEs) to streamline their operations, enhance productivity, and accelerate growth. With a focus on delivering tailored solutions and exceptional customer service, we specialize in helping businesses harness the power of SAP Business One to achieve their strategic objectives.  Our mission at NAS Infosolutions is to empower SMEs with affordable, scalable, and innovative SAP Business One solutions that drive operational efficiency, enable informed decision-making, and fuel business success. We are committed to delivering value through our expertise, integrity, and dedication to exceeding customer expectations.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Navicater Solutions India Pvt Ltd', 'Maritime Technology', '+91 9446 88 33 77, +91 8289 88 33 77', 'Navicater Solutions India Pvt. Ltd., First Floor, Carnival Infopark Phase 1, Kakkanad, Kochi, Kerala- 682030, India', 'admin@navicater.com', 'www.navicater.com', 'NAVICATER SOLUTIONS INDIA PRIVATE LIMITED is a subsidiary of NAVICATER SOLUTIONS INC. At NAVICATER, we harness innovative technology to transform maritime operations—making the industry better for both people and the planet. We are driven by purpose, with a team enriched by maritime experience, technological expertise, and entrepreneurial spirit. Incorporated in Vancouver, Canada, in January 2024 and expanded into India in May 2024, our first year was dedicated to building a capable team and developing prototypes that validated our ideas while earning our stakeholders’ trust. Our journey is already off to a strong start, evidenced by our successful pre-seed funding from the industry.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('NDimensionZ Solutions Pvt.Ltd.', 'IT Services', '', '0484 - 6689999', 'hr@ndimensionz.com', 'www.ndimensionz.com', 'NDZ is a fast-growing and global leader aspirant in technology and digital, services as well as consulting. We enable clients across the globe to navigate their digital transformation.  NDimensionZ employs 300+ resources with diverse technology and domain experience, which makes us a 360-degree partner. Since our inception in 2007, drawing 13 plus years of experience, we are a results-driven intelligent solutions provider that uses the power of emerging technologies to advance and drive competitive advantage for our clients.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Neem Info Solutions Pvt. Ltd.', 'IT Services', '', '8281155932', 'admin@neemsoftware.com', 'www.neemsoftware.com', 'Neem Info Solutions Pvt. Ltd.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Neork Technologies', 'IT Services', '', '+91 99958 03233', 'info@neork.com', 'www.neork.com', 'Neork Technologies is a full-fledged software and web development company based in Kochi, offering innovative digital solutions tailored to modern business needs. Focused on helping businesses succeed through innovative, scalable, and secure digital solutions. With deep expertise in web and mobile app development, Artificial Intelligence (AI), Machine Learning (ML), Internet of Things (IoT), digital marketing, and SEO, we empower our clients to build a strong digital presence and stay ahead in a competitive market.    With a strong focus on innovation and performance, Neork Technologies helps businesses modernize digital infrastructure and operate with greater efficiency. AI and ML are at the core of intelligent automation, enabling smarter decision-making, personalized user experiences, and actionable insights from complex data. IoT integration adds real-time connectivity, enhancing system responsiveness and enabling seamless communication between devices and platforms. Along with these smart technologies, our digital marketing and SEO strategies help businesses grow their online presence, reach more people, and boost results. Every solution we deliver is built to create real, measurable impact.     With Neork Technologies, you''re not just adopting digital tools—you’re gaining a dedicated partner who’s invested in your growth. Together, we build smarter systems, stronger brands, and better experiences for the future.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Nesa Software Pvt Ltd', 'IT Services', '', '+91 7593 833663', 'info@nesasoftware.com', 'www.nesasoftware.com', 'NESA Software Pvt. Ltd. is a technology-driven company focused on delivering innovative digital solutions and advanced engineering services to global clients. The company specializes in software development, Internet of Things (IoT), embedded systems, data analytics, artificial intelligence (AI) engineering, and Software-as-a-Service (SaaS) product development. NESA Software aims to help organizations improve operational efficiency, enhance decision-making, and accelerate digital transformation through scalable and secure technology solutions.  The company proposes to establish its development and innovation operations at Infopark Kochi, one of the leading IT hubs in Kerala known for its strong technology ecosystem and global connectivity. From this location, NESA Software will focus on designing and developing advanced software platforms, smart IoT solutions, and AI-powered applications for clients across industries such as logistics, manufacturing, finance, retail, and smart infrastructure.  The Infopark facility will serve as a center for research, development, and project delivery, enabling the company to collaborate with international clients while leveraging the region’s skilled talent pool. Through its operations at Infopark, NESA Software aims to build innovative technology products, expand its global presence, and contribute to the growth of Kerala’s IT and digital innovation ecosystem.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Nesote Technologies Pvt Ltd', 'IT Services', '', '4842987111', 'hr@nesote.com', 'www.nesote.com', 'Nesote Technologies Private Limited is a leading software developing company in the world. Established in 2008 by  Shri. Jacob Baby considering the high potentialities of establishing a software manufacturing firm to steer customers through the next generation of business innovation powered by technology with the futuristic software.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Nestsoft TechnoMaster PVT LTD', 'IT Services', '', '+91 9895490866', 'join@nestsoft.com', 'www.nestsoft.com', 'Established in 2007, Nestsoft has emerged as a leader in the IT industry, offering innovative solutions across a diverse range of services. Specializing in e-commerce solutions, mobile app development, ERP/CRM systems, and website design and development, we also excel in SEO, digital marketing, social media marketing, Google AdWords, email marketing, and WhatsApp marketing. Our expertise extends to developing software packages tailored for study abroad consultants, placement agencies, chit funds, construction companies, marketing firms, matrimonial bureaus, real estate agencies, and departmental stores. Under the leadership of Mr. Jilo Jose, a distinguished IT professional renowned for his innovative ideas and dynamic approach, our team of highly skilled IT experts is dedicated to delivering exceptional and cost-effective solutions to clients worldwide. For more information, please visit our website nestsoft.com');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Netlyft Technologies Pvt Ltd', 'IT Services', '', '+91 9207325275', 'contact@netlyft.com', 'www.netlyft.com', 'Netlyft Technologies, founded in 2022, is an innovative digital solutions company specializing in website development, Web Applications, and Mobile Applications. We believe that technology should be both powerful and easy to use, hence we create digital experiences that help businesses thrive in our ever connected world.  Based in Infopark, Kochi, our team combines creativity, innovation, and precision to craft solutions that are fast, secure, and scalable. Whether it’s responsive websites, custom web apps, or user-friendly mobile applications, we turn ideas into smooth digital realities that streamline operations, boost brand visibility, and drive real growth.  Our journey started with a simple idea, a vision to create impactful technology. Over time, that idea has blossomed into a brand that businesses across various sectors trust, including corporate, education, event management, travel, fashion, healthcare, IT, and more. With over 100 clients served globally, we continue to break new ground through late-night brainstorming, user-focused design, and an unwavering commitment to excellence.  At Netlyft, we don’t just create technology; we weave stories of progress, connection, and success. As we grow, our mission stays the same: to empower businesses with dependable, future ready digital solutions crafted with intention.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Netsentries Infosec Solutions Pvt.Ltd.', 'Cybersecurity', '', '+91-484-4148299', 'careers@netsentries.com', 'www.netsentries.com', 'We provide smart cybersecurity solutions and services to protect Governments, Enterprise and Individuals from threats through a comprehensive range of protocols, products and services. We provide security consulting and strategy; perform intrusion detection and testing; offer security assessment, remediation, resolution and product selection, turnkey implementation and ongoing operational management. We provide solutions that address all aspects of IT-GRCM (Governance, Risk Management and Compliance Management). We carry out extensive research and development on future-ready solutions for IoT Security and Unified Threat Management across all domains of any business.  Started up in Bangalore, India with offices in Dubai and associations worldwide, NetSentries is a team of cybersecurity specialists dedicated to providing secure, trusted and integrated protection services. We are engaged in multifaceted research to roll out future-ready solutions in the Information Security, Internet of Things and Industrial Control Systems protection.  Ultra connected world has changed our lives beyond measure. Digital progress has made lives easier and businesses more efficient. However, with technological progress comes many new threats and challenges. We are transforming the cybersecurity landscape through a complete range of state of the art services and solutions for governments, businesses and individuals.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('NewAgeSys Solutions (P) Ltd.', 'IT Services', '', '0484-2983032 / 2983033', 'career@newagesysindia.com', 'www.newagesysindia.com', 'NewAgeSys Solutions (P) Ltd, is a growing company and has been in business since 1994. Currently we have two functional offices - Info Park Cochin, Kerala, India and at Princeton Junction, New Jersey, USA. For over 22 years we have been constantly focused on providing Excellent Client Services, providing Consulting and Software Development Services to companies in USA. Our expertise are spread wide across the fields of Software Development and Recruitment Process Outsourcing. Our Clients include major players from the United States of America, especially the Fortune 1000 Companies. Please see www.newagesysindia.com,  www.newagesys.com, and www.newagesmb.com for more info.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Next Apps', 'IT Services', '', '9916940449', 'support@nextapps.in', 'www.nextapps.in', 'Founded in 2016, NextApps is a small web design and development company based in Kochi, India. Over the last few years we’ve made a reputation for building websites and mobile apps that look great and are easy-to-use. We’re truly a one-stop solution provider offering a full range of solutions for anyone looking to succeed in their online endeavors. We are backed with a development team with over 20 years of experience on a wide range of platforms. In addition to experience, another key to our success is our commitment and dedication to providing the best possible customer service to our clients. While other companies claim to provide top-notch customer service, NextApps actually delivers customer service that is unparalleled in the industry. We can help you define your needs and fulfill those needs. Working with us, you will experience the best software development services.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Niaway Technologies Pvt Ltd', 'IT Services', '', '+91 6238833983', 'info@niaway.com', 'www.niaway.com', 'Niaway Technologies Pvt Ltd. is an IT services company that specializes in crafting software for desktops, phones, and devices using Qt/QML, C++, and more. We excel in creating monitoring and control programs for factory machinery, backed by our deep expertise in SCADA/HMI app development.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Niche Techies', 'IT Services', '', '9995333078', 'info@nichetechies.com', 'www.nichetechies.com', 'Niche Techies is a U.S.-headquartered software development company delivering custom-built digital solutions for global clients across industries. Our core focus is on end-to-end software engineering, including product design, application development, cloud-based platforms, AI-enabled systems, and enterprise-grade integrations.  As part of our global expansion strategy, we have recently established our India operations at Infopark, Kochi, to strengthen our engineering capabilities and support growing client demand. The Kochi center functions as a full-fledged delivery hub, working closely with our U.S. leadership and client teams to execute real-world projects following industry-standard development practices.  Our teams operate within structured SDLC frameworks, collaborating across roles such as product management, architecture, engineering, quality assurance, and DevOps. We emphasize code quality, scalability, security, and performance, ensuring that every solution meets enterprise expectations.  With a strong presence in both the U.S. and India, we aim to combine global business insight with high-quality engineering talent, positioning Kochi as a key pillar in our long-term growth and innovation roadmap.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Noa Infosolutions LLP', 'IT Services', '', '9846002792', 'hr@noainfosolutions.com', 'www.noainfosolutions.com', 'Noa Infosolutions LLP');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('NOMD Technologies', 'IoT', '', '85907 17735', 'info@nomdindia.com', 'www.nomdindia.com', 'In a changing world that is driven by data, IoT platforms and services have become the focus of effective operations management. As a trusted provider of IoT solutions, we felt a responsibility to develop the best tools and applications that can drive the future of smart Technologies. Our Vision: Vision to become the spine of the IoT global market and the reliable partner for players interested in becoming a part of it Our Mission: Mission to provide our customers a cutting-edge diversified solutions that will give them the essential insight to run exceptionally efficient operations');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Nuvento Systems Private Limited', 'IT Services', '', '0484 4066070', 'mohan@nuvento.com', 'www.nuvento.com', 'Nuvento is synonymous with innovative technology services. We kicked off our specialized solutions & services in 2007 and have rapidly grown in the areas of Business Intelligence, Data Analytics, Software Quality Assurance and Software Architecture. This has helped us forge partnerships with Oracle Platinum, Microsoft Silver and IBM Technologies in the business intelligence (BI) area. Head quartered in Kansas USA, we serve across various verticals such as financial services, insurance (BFSI), telecom, retail, construction and hi-tech. Our operations also extend to India (Thrichur) with sophisticated R&D center to cope with the growing list of customers from across the globe.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Nymbl', 'FinTech', '', '91 77366 98555', 'krishnapriya@benymbl.co', 'www.benymbl.co', 'Nymbl, as a subsidiary of WayPoint Systems, complements your business efforts with our Smart Complete Business Solutions. We provide FinTech solutions for small and medium businesses. Checkout Point created customized apps for POYNT, the world''s first Smart POS Terminal, provides SaaS-based ERPs for your business and fulfills all other IT requirements including Van Sales solution, CRM for your business.   Specialties:   Finance, ERP, Business Solutions, Sales, Payment Systems, Digital Payments, Retail Business, FinTech, Business Analytics, Customer Management, Enterprise Solutions, Inventory Management, Financial Accounting, Business Intelligence, Data Analytics, Accounting, Sales and Trading, Operation Accounting, Enterprise Solution, Sales and Distribution, and Van Sales  Headquarters:  Dubai Silicon Oasis, Dubai  Founded: 2013');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Obidos Technologies (P) Ltd', 'IT Services', '', '0478 2553300', 'hr@obidostech.com', 'www.obidostech.com', 'Obidos Technologies (P) Ltd was established on 2011 primarily as an off-shore development and maintenance centre for ColdFusion applications. We are now working with projects on React, NodeJS along with PHP and ColdFusion. We are experts in integrating applications using OAuth and provide end-to-end solution for new and existing applications.  We help you to develop your idea to reality by providing support for the complete software development lifecycle.  We have a well established process for testing and release management process to make sure the app development and delivery is completed in stipulated time with zero bugs.  We will be able to help you to quickly bring your ideas to life with our domain knowledge in Education, Scheduling and Accounting');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Obvious AI Technology Pvt Ltd', 'Artificial Intelligence', '', 'Obvious AI Technology Pvt Ltd, Office No. C1-03, C Wing, First Floor Chaithanya Building Infopark Cherthala, Pallipuram, K R Puram P O, Cherthala 688541', 'hr@obvsai.com', 'www.obvs.ai', 'At Obvious AI, we are pioneers in transforming complex, unstructured data into structured formats that drive actionable insights. Our cutting-edge software solutions are engineered to optimize workflows, increase accuracy, and improve overall operational efficiency across a wide range of industries. While healthcare remains a cornerstone of our business, our versatile solutions are also being embraced in sectors such as finance, logistics, and manufacturing, wherever automation can provide a competitive edge.  Our flagship automation platform, AIBlock, is a proprietary tool that seamlessly integrates data across disparate systems, whether in Electronic Medical Records (EMR) in healthcare or other sophisticated data management environments in non-healthcare sectors. The power of AIBlock lies in its adaptability, enabling it to automate processes, reduce manual input, and eliminate errors across industries.  What truly sets Obvious AI apart is our hybrid approach, blending proprietary AI-driven solutions with the expertise of skilled human resources. This fusion allows us to deliver unparalleled accuracy, flexibility, and cost-efficiency. By strategically combining automation with human oversight, we ensure that our clients receive tailored, high-quality services, regardless of industry or complexity. Our solutions are designed to evolve with our clients'' needs, offering scalability without compromising performance.  With over five years of expertise in healthcare automation, we have earned a reputation as innovators in the industry. However, our leadership team brings over two decades of experience across diverse fields, ensuring that our solutions are not only forward-thinking but also grounded in a deep understanding of automation technology and its real-world applications. This wealth of experience ensures that our clients, whether in healthcare or beyond, can trust us to deliver solutions that are robust, reliable, and customized to their unique operational requ');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Offline Human Studios', 'Game Development', '', '+91 9995479222', 'sharath.ravi@offlinehumanstudios.com', 'www.offlinehumanstudios.com', 'Offline Human Studios was established in 2023 as a game development company dedicated to crafting immersive gaming experiences inspired by Indian culture, mythology, history, sports and Indian space explorations. We focus on blending innovative narratives with cutting-edge technology to create games that resonate with players worldwide. Our Pillars: • Immersive Games: We specialize in creating captivating gaming experiences that keep players engaged and entertained. • Latest Technology Achievements: We integrate cutting-edge tools like AI, VR, and advanced game engines to deliver seamless and innovative gameplay. • Inspirations from Indian Heritage: Drawing from the rich culture, mythology, and history of India, we craft stories that resonate globally.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Onesoft Technologies LLP', 'IT Services', '', '+91-96567 07783', 'admin@onesoftapps.com', 'www.onesoftapps.com', 'OneSoft Technologies LLP, founded in 2019 is situated in Info park, Kakkanad, Kochi. Our core mission is to provide proven IT solutions that enable our clients to concentrate on their core business and develop a competitive advantage. We offer a diverse range of services, including software product development, application and mobile app development, and e-commerce website development, all delivered in a timely and cost-efficient manner.  At OneSoft Technologies, we are committed to being genuinely client-focused, continuously seeking improvements in our products, and drawing inspiration from challenges to ensure our clients receive the highest quality standards at competitive prices. We view our business as a partnership between our suppliers, customers, our people, and the community we serve.  Mission: Our mission is to build a team of highly innovative individuals capable of providing unique solutions that inspire curiosity and delight our customers with excellence.  Vision: We envision providing all our customers with a wide assortment of services while establishing long-term associations with our clients.  Our Strategy: Our approach focuses on creating long-term reliability in our services and sustaining quality in our products. Guided by our corporate culture, we prioritize how we work with our customers, how our employees interact with our markets, foster company growth, and meet our financial targets..');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Opshore Talent Solutions Pvt.Ltd.', 'Business Process Outsourcing', '', '0484 4017565', 'hr@opshoretalentsolutions.com', 'www.opshoretalentsolutions.com', 'Opshore Talent Solutions, is a business processing outsourcing company. Having in-depth knowledge and expertise in healthcare recruitment industry in UK, OTS mainly focus on providing a one stop solution for all offshore recruitment and administrative operations requirement of healthcare companies. We also assist firms across United Kingdom with their service based operations by understanding the nature of their business and providing innovative and strategic approach to ensure smooth running of their operations. By managing the end to end business processes, we enable our clients to stay focused on the core operations, while we undertake the non core activities. With our commitment to quality and perform consistently, we have been able to create great value for our clients and become an integral part of their business process. With a 24/7 support team, we aim to deliver maximum flexibility and timebound delivery for all our clients.   Having our operations in India, and head office in the United Kingdom, has enabled us to cater to specific needs of clients by customization of their requirements.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Orestes Technologies Pvt Ltd', 'IT Services', '', '918078206146', 'info@orestestech.com', 'www.orestestech.com', 'Orestes Technologies Pvt. Ltd. successfully Started in June, 2015 and later registered to private limited on 28th January, 2019 to service global customers in the field of web design & development, Mobile App development, Web Application, Software Development, branding. We aim to meet and exceed customer satisfaction in every way possible. We have built a team of exceptionally talented professionals whom perfection is a habit.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Origent Technologies', 'IT Services', '', '8891113129', 'careers@origent.in', 'https://www.origent.in', 'Origent Technologies has been developing web-based SaaS solutions in the social services and education domains for clients throughout North America for 25+ years. Our products are enabled for the digital age, operating on mobile devices, entirely online, with robust security protocols. We specialize in comprehensive data management and tracking, offering extensive reporting capabilities through established and secure technology to reduce operational costs and enhance productivity.');
