INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Ormeon IT Consulting Pvt Ltd', 'Digital Marketing', '', '+91 94472 14688', 'info@ormeon.com', 'ormeon.com', 'Ormeon is led by a team of dedicated professionals each of whom brings years of intense experience and high level of expertise in their respective field. We have created a special collaborative environment which enables to deliver all aspects of website and digital – design, development, hosting, commercial launch, online marketing and promotion. Delighting you with creativity and technology is central to what we do. We work with you to uncover the most cost effective solution for your unique business. Our well-recognized approach which is both practical and analytical, ensure that we have on your site the right content that gets crawled, indexed and helps your site achieve better ranking.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('ORTHOFX PRIVATE LIMITED', 'Healthcare', '', '+91 8848317153', 'hr-india@orthofx.com', 'www.orthofx.com', 'OrthoFX brings a modern approach to straightening teeth that will revolutionize the Orthodontic industry. OrthoFX reimagines the end-to-end customer experience. Software supports and acts as a catalyst in the core business of OrthoFX. It has multiple dimensions. Different sites for patient/end consumers, doctors and other entities in the workflow are the major parts. In addition to these, we have the core processing piece which analyses the teeth scans and provides various simulations and 3D views. OrthoFX believes patient''s smiles deserve face-to-face professional supervision every step of the way.');
