INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Pagematics India Pvt. Ltd.', 'IT Services', '', '+91 8848178114', 'hr@pagematics.in', 'https://www.pagematics.com', 'Pagematics designs, develops, and delivers high-tech software solutions that enhance business functionality. We offer customizable and maintainable web content and portal management solutions suitable for different business sizes. Our transparent software development processes ensure direct communication, short feedback loops, and rapid issue resolution. Our core services include web design and marketing, quality assurance, cloud computing services, and mobile app development services. We leverage the best technology to help businesses create a significant online presence.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('PanashiFZCO Technology Solution Private Limited', 'IT Services', '', '4842915045', 'hr@panashi.ae', 'panashi.ae', 'Panashi is a one-of-a-kind self-service solutions company dedicated to transforming how businesses and individuals engage with self-service technology. We specialize in delivering highly customizable, innovation-driven platforms that redefine user experience standards. Our solutions empower you to design and control your own self-service environment—perfectly aligned with your brand identity and operational needs—offering an unmatched level of personalization and flexibility in the industry. With our head office located in Dubai and our overseas office in Infopark, Kochi, India, Panashi combines global vision with strong technological expertise to serve clients across diverse markets with excellence and innovation.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Paoyaila Animation Studios LLP', 'IT Services', '', '+91 9495463841, +919400197544', 'hrpaoyaila@gmail.com', 'www.paoyaila.com', 'We are Paoyaila Animation Studios LLP, a Tech company specializing in Animations and Games. Paoyaila was founded in 2015 to promote the animation and gaming industry in India. We specialize in animation, games, virtual reality/augmented reality (VR/AR), motion graphics, infographics, explainer videos, marketing videos, training videos, digital marketing, UI/UX design and mobile application development. We also provide IT consulting and implementation services, which include ERP and CRM solutions, among other offerings. Our team of designers, animators and developers both internationally and domestically collaborate to meet the project expectations of our clients.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Paradigm IT Private Limited', 'Engineering Services', '', '+91 8086257998', 'hr@paradigm.in', 'https://paradigm-structural.com/', 'Paradigm is a company owned and managed by qualified civil/structural engineers from India and Europe who possess extensive on-site and backend experience in a wide range of projects worldwide. Currently based in Kochi, Kerala, we employ over 250+ professionals.  Our highly committed, experienced, and knowledgeable team anticipates potential challenges at the construction site and suggests feasible and cost-effective solutions during the design and detailing phase. This proactive approach enables smooth operations during critical planning and construction stages.  Our detailed engineering division offers services across the value chain, including structural design, geotechnical design, BIM services, reinforcement steel detailing, structural steel detailing, preconstruction CAD services, and as-built services.  We deliver our services across key global markets, including Europe, the UK, Canada, the USA, India, and the Middle East.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('PaulCart E Commerce Pvt. Ltd.', 'IT Services', '', '9995434111', 'admin@paulcart.com', 'www.wibserp.com', 'PAULCART E COMMERCE Pvt Ltd located in the heart of Kerala was incorporated in 2015 as a private limited company with the primary aim to undertake ERP software development. This Company deals with web development, Android development along with its initial focal point on the development of ERP (Enterprise Resource Planning) Solution.  PaulCart is working on all platforms and with up to date technologies. PaulCart delivers technology driven business solutions that meet the strategic objectives of its clients. PaulCart E Commerce Pvt. Ltd. delivers unmatched business value to customers through a combination of process excellence, quality frameworks and service delivery innovation. PaulCart has a team of technology experts having several years of experience in the software field and excellent designing team creating easily operated and striking business solutions.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('PCS India Private Limited', 'FinTech', '', '+91 474-2970074', 'info@pcsindia.email', 'pcsindia.online', 'Pellippuram Consultancy Service India Private Limited (PCS India Pvt Ltd) is a technology, service and product company operating from Infopark, Kerala, delivering innovative digital solutions to businesses across the Middle East. The company specializes in developing core software platforms that support financial institutions, exchange houses, trading organizations etc. With a strong focus on automation and security, PCS India helps organizations simplify complex business processes and achieve higher operational efficiency.  At its Infopark development center, PCS India designs and maintains solutions for core banking support, remittance management, accounting, inventory control, human resource management,  and customer relationship management. The team comprises experienced software engineers, domain consultants, and support professionals who follow agile methodologies and global quality standards. By combining industry expertise with modern technologies such as cloud computing, API integrations, and data analytics, the company delivers scalable and future-ready applications.  PCS India is committed to long-term partnerships with clients, offering implementation support, system integration, and continuous enhancements.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Pearlsoft Technologies LLP', 'IT Services', '', '2A-3, Second Floor, A Wing, Athulya IT Building, Infopark Kochi Phase 1,  Infopark Kochi PO, Kakkanad, Kochi, Ernakulam, Kerala, 682042', 'joinus@pearlsofttechnologies.com', 'pearlsofttechnologies.com', 'PearlSoft Technologies is a multi-faceted software development company with deep-rooted domain expertise across industries that provide end-to-end solutions. We have expertise in serving a range of SMEs as well as giant enterprises and corporations spread across the globe by providing path-breaking solutions for custom application development, enterprise solutions, business intelligence and analytics. Compliant with international standards, we follow industry best practices with a zero-tolerance policy against sub-standard productivity.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Penguin Data Centre Pvt.Ltd.', 'IT Services', '', '+91-6238309752', 'careers@penguininc.com', 'www.penguininc.com', 'Penguin is the market leader in enterprise application software for Travel industry , helping companies of all sizes and in different travel domain to run at their best. Our Automation  and advanced analytics technologies help turn customers’ businesses into intelligent enterprises. Our end-to-end suite of applications and services enables our customers to operate profitably, adapt continuously, and make a difference.  Penguin is headquartered in UK , servicing it clients across the world.  25 years in this industry and work as backend engine for most of the travel software in in the industry.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Phases India Technology Solutions Pvt Ltd.', 'IT Services', '', 'Unit VIIA,7th Floor, Carnival Infopark Phase 3, Infopark Kochi Phase 1, Infopark Road, Kakkanad, Kochi, Kerala, India, 682042', '_@c.c', 'www.phases.io', 'Phases is a Danish-based Web development company developing solutions together with the web and marketing agencies, enterprises and public organizations. We deliver web development of high standards, on time. We have competencies within Umbraco, Sitecore, Drupal, WordPress and Typo3.With a long list of successful projects, we have delivered over 700 web projects based on the most popular technologies. We are always looking out for new platforms and technologies which we can use in our projects. We have integrated a long list of systems, built our own integration products and delivered APIs to other businesses, such as Citrix Podio. We are committed to providing our clients with the best possible services and solutions to their needs. Our team consists of highly skilled and experienced professionals who are dedicated to delivering quality services to our clients.');
