INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('PiServe Solutions Pvt Ltd', 'IT Services', '', '+91-9895229562', 'info@piserve.com', 'www.piserve.com', 'PiServe is a leading digital transformation company focused on helping businesses reach innovative heights with innovative technologies, expertise, and a comprehensive service portfolio.We are a pro-business and efficient organization providing clients with end-to-end consultation and solutions. We focus on generating new revenue streams and perfecting customer satisfaction. 10 years of excellence and delivery of over 100 successful projects is the testimony of our quality and expertise.A client-oriented company, we believe in the time, value, and quality of our solutions and services as the pillar stones of digital transformation. We focus on discussing and planning every touchpoint of the products or services a client requires. Our customer-centric approach has resulted in successful partnerships with various Fortune 500 companies.Our strength is our team of talented and passionate employees who go the extra mile. PiServe provides the perfect platform with a suitable environment for our employees to grow professionally and personally.Our relationship with our clients is more than buying a product or a service but building everlasting trust. We don''t just expand our clientele. We add members to our family.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('PIT Solutions Private Limited', 'IT Services', '', '4712700915', 'enquiries@pitsolutions.com', 'www.pitsolutions.com/de-ch', 'PIT Solutions has been an established IT service provider since 2000, with primary offices in Switzerland and India as well as new subsidiaries in the USA, UAE, and Germany. We are specialized in developing individual software as well as web and mobile applications based on customer needs. Today, we employ a strong pool of 700+ in-house skilled resources that possess the right mix of technical competence and experience to understand client needs and provide them with the right solutions. We have a proven history of successfully completingover 4,000 projects to date. PIT Solutions has been placed on the ‘Amazing Workplaces'' certification list. Our talent pool is comprised of SAP Commerce cloud certified developers, Microsoft MVPs, Oracle certified Java programmers, TYPO3 certified integrators, Magento- certified developers, and ISTQB certified testers. PIT Solutions is a Microsoft Gold Certified Partner, Adobe Solution Partner, TYPO3 Agency Solution Partner, ISTQB Gold Partner, AT&T Cybersecurity Partner, Odoo Partner, and SAP Commerce Silver Partner. We are an ISO 9001:2015 and ISO 27001:2013-certified organization.We utilize Microsoft.NET and the Oracle Java framework for building complex web applications for our large clients. For enterprise-level CMS, we use Adobe AEM and Magnolia, and for large e-commerce implementations, we go with SAP Commerce Cloud. For collaboration portals, our choices are Microsoft Sharepoint and Odoo. For SMEs, our preference is the Symfony PHP framework for web application projects. Our open-source team uses TYPO3 CMS when it comes to CMS-driven projects and Magento Commerce for internet shop solutions. We have a strong know-how in building extensions for SAP Commerce Cloud, TYPO3, Odoo, and Magento. Our fast-growing mobile app team is well versed in developing native apps as well as hybrid apps using frameworks like Ionic, React Native, etc. We always strive to constantly update the PITS team with new tools and technologies to serve ou');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Pixdynamics', 'Artificial Intelligence', '', '+91 79944 31750', 'hr@pixdynamics.com', 'www.pixdynamics.com', 'Pix Dynamics Pvt LtdEstablished in 2018, PixDynamics is a unique combination of informed AI, computer vision,and machine learning solution providers, which enables reliable and secure verification of remote users while streamlining the onboarding process. Services Offered:- Aadhar Masking Solution- With our Aadhaar card masking solution, BFSI companies can now automate Aadhaar card classification, extraction, and mask the first eight-digit of an Aadhaar card in minimal time.- Face Recognition Solution- Our Face Recognition Solution provides a real-time service to obtain the latest actionable insights. There is no physical interaction required by the end-user. Face detection and facial identification or verification are not any time-consuming tasks for our product. - Invoice Reader- To scan, process, and extract data, use the invoice OCR Software API. Combining information extraction and deep learning can fully automate the invoice process.- OCR Solution- Optical Character Recognition (OCR) Software- Video KYC Solution- Our Video KYC Solution for banks to onboard customers and partners remotely for several fintech companies and NBFCs by using our AI Solutions Our experienced team of professionals is dedicated to delivering tailored solutions that meet the unique needs of each client. We leverage the latest technologies and industry best practices to ensure high-quality outcomes and client satisfaction.Branches in Kochi and Our extensive network enables us to serve clients efficiently and effectively, regardless of their location.At Pix Dynamics, we believe in fostering long-term relationships with our clients, built on trust, integrity, and mutual respect. We are committed to continuous improvement and strive to exceed client expectations in every project we undertake.For more information about our services and how we can assist your business, please visitour website or contact us directly.3rd Floor, Carnival Infopark Phase II,Infopark Campus, Infopark, Kochi,Kakkana');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Planet Media India ( PMIN Agency Pvt.Ltd.)', 'Digital Marketing', '', '9778149518', 'info@planetmedia.in', 'www.planetmedia.com.au', 'Planet Media India ( PMIN Agency Pvt.Ltd.)');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Policy4us Insurance Web Aggregator Pvt Ltd', 'FinTech', '', '+91- 9061718180', 'info@policy4us.com', 'www.insurancepolicy4us.com', 'Who is insurancepolicy4us.com? We’re an insurance comparison web application dedicated to find the right insurance policy for you. We search prices from some of the India’s leading insurance providers to make sure you can find the cover you need at a budget to suit you. As experts in insurance comparison, we’re dedicated to compare quotes online quickly and easily; our aim is to take the hassle out of endless searching around for different insurance quotes and deals because we know you have better things to do with your time! We don’t stop there though; we also offer the option to get quotes over the phone if you would prefer to talk to someone directly. Unlike most comparison websites we’re 100% independent which means the results we display are completely impartial. We are regulated and Certified by Insurance Regulatory and development authority (IRDAI Registered Number IRDAI/INT/WBA/64/2022).  Insurance is the business of solicitation.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Portrave Solutions Pvt Ltd', 'IT Services', '', '+91484 4070667', 'info@portrave.com', 'www.portrave.com', 'Founded in 2007, Portrave Solutions is a web design & development company based in India. Over the last many years, we''ve built a reputation for building websites and applications that look great and are easy-to-use. We have a wide range of solutions globally, but more often we are going with Web Development services for USA, UK, Germany, Australia and India.  Our offshore web development services include IT Consultancy, Business Process Outsourcing, Web App Development, Mobile App Development, IOT Solutions, Professional Design and UI Engineering, DevOps, Automation, Cloud Computing, Big Data, Search Engine Optimization, iOS and Android App development and other IT services etc. Our team operates with enthusiasm and flexibility. All our work is done in-house by a team of 30+ professional Website developers, Designers, Business analysts and Testers that have the skills and experience to tackle any challenge, large or small. We are focused on our customers, being their reliable partner for IT services and solutions, working together on a partnership basis, helping them face the challenges of the modern times. Furthermore, we offer reasonable Service Level Agreements (SLA) covering most of the additional maintenance services. With our excellent throughout support, we are making troubleshooting as easy as possible.');
