INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('PrimeCrown Technologies (P) Limited', 'IT Services', '', '+91-8547859999', 'info@primecrown.com', 'www.primecrown.com', 'PrimeCrown Technologies Pvt. Ltd. is a global cloud computing and product engineering company. We offer a wide variety of hybrid IT services, including private cloud, public cloud, metal servers, storage, security and network. Our expanding portfolio of ''as-a-service'' solutions is powered by proprietary CloudSmart.One platform and a decade of industry expertise, ensure that all our cloud solutions are resilient, agile, optimized and accelerate for delivering growth. Our IaaS offerings are available in the Americas, EMEA, and APAC. Our Cloud Enablement platform is an AI-based solution that helps SMEs and enterprises to analyze their existing landscape, then architect, deploy and operate a portion or its entire IT infrastructure to either a private, a major public cloud, or a hybrid cloud environment. We are a Global BGP network operator and an Accredited Domain Registrar. PrimeCrown is also a provider of IT consulting and software development services. Our IT services division helps transform businesses with powerful, future-ready, and adaptable digital solutions. We work on diverse technologies and platforms to help our customers navigate a rapidly changing environment, enabling a sharper definition of their goals and measures to achieve them. Founded in 2010 and headquartered in Kerala, India, PrimeCrown has successfully catered to over 1,000s of clients in over 15 countries.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Privo TechCorp Private Limited', 'FinTech', '0', 'Unit No 602, 6th Floor, Tower A, World Trade Center, Infopark Kochi Phase 1, Kerala, 682030.', 'hr@privocorp.com', 'privocorp.com', 'PrivoCorp offers support services in mortgage processing, servicing, and title insurance. We provide significant value in terms of reduced costs and improved turnaround time to banks, mortgage companies, large brokers, credit unions, and title insurance companies. We are on a mission to provide measurable value to our customers by delivering experienced resources and proven technology at the right cost. Our team is driven by innovation, collaboration, and a commitment to delivering cutting-edge solutions in the mortgage industry.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Pueblo Shades Pvt.Ltd', 'IT Services', '', '80752 45591', 'info@puebloshades.com', 'www.puebloshades.com', 'Pueblo Shades  as an intuitive web design company provide you with an entirely redesigned digital interface for your business through our web design services. We can take your brand to the next level with our dedicated team! Being the most reliable app developers in downtown, our projects have wide-ranging standards and robust solutions for your business. A well-designed website is critical for the long-term.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Pumex InfoTech Pvt Ltd', 'IT Services', '', '0484-4016369', 'hr@pumexinfotech.com', 'www.pumexinfotech.com', 'Pumex, a global IT solutions company, specializes in transformative services such as software development and cloud solutions. With a focus on diversity, innovation, and evolution, our teams strive to simplify complex problems through inventive ideas, ensuring clients can modernize seamlessly without disrupting user experiences.  Boasting 15 years in the industry, Pumex operates from offices in the USA and India. We maintain a mature delivery practice for timely solutions and follow agile processes for swift launches. Our commitment to quality, integrity, and client satisfaction is evident in the testimonials from delighted clients. As we embrace new technologies, including cloud solutions, we continuously raise our service standards to deliver cutting-edge systems and applications.');
