INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('QC Verify Private Limited', 'IT Services', '', '0484 4020024', 'hr@qcverify.com', 'www.qcverify.com', 'QC VERIFY Private Limited (Previously known as QMIS SYSTEMS PVT LTD) is the captive unit of Tennessee based QC Verify, LLC. QC Verify USA was previously known as Quality Mortgage Services and was established in the year 1992. QC Verify started its operations in India in the year 2013.  We provides software development and BPO process workflow support in order to help companies maintain work-flow efficiencies with cost-effective solutions.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Quantum Acumen', 'Artificial Intelligence', '', '8089427555', 'careers@quantumacumen.com', 'www.quanhack.com', 'QuAnHack Solutions is a technology innovation company specializing in AI-driven software development, big data engineering, and enterprise platform solutions. The company helps organizations modernize their technology ecosystems by building scalable applications, intelligent analytics platforms, and automation systems, enabling faster digital transformation and data-driven decision-making.  QuAnHack also focuses on learning, upskilling, and professional training in Artificial Intelligence, Generative AI, data engineering, and other emerging technologies, empowering students, professionals, and organizations with future-ready skills.  QuAnHack Solutions is part of the Quantum Acumen ecosystem, dedicated to advancing innovation through technology, knowledge, and human-centered digital transformation.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Qubeslab Technologies Private Limited', 'IT Services', '', '9383401029', 'info@qubeslab.com', 'qubeslab.com', 'Qubeslab is a software company based in Infopark, focusing on engineering software development. We are a group of passionate techies with urge in innovation. We believe that a well build plan and expertise can give you the best results. Our domain knowledge in engineering technology makes us lead among our rivals. We began our journey with a mission to provide innovative engineering solutions through ethical and customer-oriented approach. Our core strength is providing comprehensive end-to-end solutions and exceptional service to our clients to elevate their value through custom software development, product design, quality analysis and consultancy services. Our customer base spread across US, Europe and Israel.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Qubiqon Consulting India Private Limited', 'IT Services', '', '91 9995222141', 'contactus@qubiqon.io', 'www.qubiqon.io', 'At Qubiqon, we partner with forward-looking businesses to drive digital transformation through the Microsoft ecosystem. From streamlining operations with Power Platform to modernizing infrastructure on Azure, we deliver intelligent, future-ready solutions that boost efficiency, enhance customer engagement, and accelerate growth.  IT Services & IT Enabled Services (ITeS), Managed Services Providers (MSP)  Agriculture, Hospitality & Travel, Transportation & Logistics, Telecommunications, Retail & E-Commerce, Finance & Banking');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Quest Global Engineering Services Pvt Ltd', 'Engineering Services', '', '7593823160', 'info@quest-global.com', 'www.quest-global.com', 'We are Quest Global. We’re in the business of engineering, but what we’re really building is a brighter future. It’s not just what we do, but why we do it that makes us different. We believe engineering has the unique opportunity to solve the problems of today that stand in the way of tomorrow. For 25 years, we have strived to be the most trusted partner for the world’s hardest engineering problems. As a global organization headquartered in Singapore, we live and work in 17 countries, with 56 global delivery centers, driven by 13,000+ extraordinary employees who make the impossible possible every day.   Quest Global brings deep industry knowledge and digital expertise to deliver E2E global product engineering services.  We bring together technologies and industries alongside the contributions of diverse individuals and their areas of expertise to solve problems better, faster. This multi-dimensional approach enables us to solve the most important and large-scale challenges across the Aerospace & Defense, Automotive, Energy, Hi-Tech, Healthcare, Medical Devices, Rail and Semiconductor industries.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Raintech Software Ltd', 'IT Services', 'Office No. i9C-7, 9th Floor, i by Infopark, Kochi , Kerala-682 016', '+918078311945,  +91 8606093110', 'info@raintechpos.com', 'raintechsoftware.com', 'Raintech Software Limited is a public limited company with its Corporate office at Infopark, Kochi, India.  Our aim to build secure, AI-driven, hardware-integrated software solutions for mission-critical industries where precision, safety, and security matter most. Multiple Hardware Connected Drivers – Software that can communicate with and control various machines, sensors, and devices. Heavy Mechanism Operation AI Software – AI systems to monitor, control, and automate heavy industrial machinery. Medical Equipment Software – Programs that run, monitor, or integrate hospital/diagnostic equipment. Airline Software – Systems for aviation operations, monitoring, scheduling, or safety. Marine Engineering Software – Software for ships, ports, and marine equipment management. Banking Accounts / High Security Banking Software – Secure financial systems with strong protection and compliance. Defence Software – Mission-critical, secure systems for defence applications.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Rainybits Technology Pvt Ltd', 'IT Services', 'Ground Floor, Jyothirmaya SEZ, Infopark Kochi Phase 2, Ernakulam, Kerala', '0484-4047033', 'info@rainybits.com', 'www.rainybits.com', 'Rainybits Technology Pvt Ltd');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Redux (Network Redux)', 'IT Services', '', '0484 2972794', 'india.hr@redux.co', 'www.redux.co', 'Redux delivers managed cloud and recruiting services from our locations in the U.S., Latin America, and India.   With two decades of experience, we provide our clients frictionless access to a global talent pool, from DevOps Engineers to Certified Public Accountants. Our customer-first, founder-led operations ensure each client receives unmatched white-glove treatment. We adapt our processes and services to meet individual client needs, from shared Slack/Teams workspaces to working in our client''s project management systems, we’ve raised the bar in managed service delivery.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Regent Global Services (India) Pvt.Ltd.', 'IT Services', '', '0484 2982150', 'hello@rgsin.com', 'www.rgsin.com', 'Regent Global Services is a specialist technology services company with deep expertise in higher education systems, enterprise web applications, and data driven platforms. A significant part of our work centres on the implementation, development, integration, and long term support of SITS Vision for universities and education providers in the UK.  Our teams work across the full SITS lifecycle, including core configuration, automation, assessments and grading, timetabling, online application and registration processes, reporting, and complex system upgrades. We also design and deliver integrations between SITS and external platforms such as Moodle, Blackboard, and other API enabled systems, enabling reliable data exchange and improved operational efficiency.  Alongside higher education systems, we build custom web applications and portals using modern technologies such as PHP, Next.js, and headless CMS platforms. These solutions are designed around real business processes, with a strong focus on usability, performance, and maintainability rather than short term delivery alone.  We place particular importance on documentation, structured training, and knowledge transfer. Our approach ensures that client teams understand and can confidently operate the systems we deliver. This has made us a trusted long term partner for institutions that require stable systems, responsive support, and engineers who understand both the technical and operational realities of their platforms.  Based in Infopark Kochi, Regent Global Services works with clients across geographies, combining domain expertise with disciplined engineering to deliver systems that continue to perform well beyond initial go live.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Retyn Business Solution Pvt. Ltd.', 'Artificial Intelligence', '10H, Tower 2, Trans Asia Cyber Park, Infopark Kochi Phase 2, Kochi', '+91 9037964001', 'info@retyn.ai', 'www.retyn.ai', 'Retyn is an AI-driven ecosystem designed to enable sustainable business growth through cutting-edge technology and innovative strategies. By leveraging advanced artificial intelligence, digital transformation solutions, and data-driven insights, Retyn empowers organizations to optimize their operations, enhance customer engagement, and retain top talent. Our platform seamlessly integrates AI-driven automation, branding, sales enablement, and business process optimization, ensuring that enterprises remain competitive in an ever-evolving marketplace. With a strong focus on innovation, we help businesses unlock new opportunities, improve efficiency, and drive long-term success.   At Retyn, we understand that sustainable growth is built on a foundation of customer loyalty and workforce retention. Our solutions are designed to create value-driven experiences that foster strong relationships between businesses, employees, and customers. Through personalized engagement strategies, intelligent commission processing, and AI-enhanced retention models, we enable organizations to build a loyal customer base while keeping their workforce motivated and productive. By redefining business strategies with the latest technological advancements, Retyn is committed to driving transformation and ensuring long-term success for businesses worldwide.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('REXAV LLP', 'IT Services', '', '+91 7994480220', 'info@rexav.in', 'www.rexavllp.com', 'Rexav LLP, based in Kochi, India, stands at the forefront of technology innovation providing comprehensive services such as web and mobile app development, e-commerce solutions, web design, digital marketing, SEO, and more. Our team serves a global clientele, providing dedicated developers and offshore teams for diverse partners. Founded in 2016, we''ve empowered businesses to achieve their goals and optimize operations. Our portfolio boasts award-winning websites and cutting-edge apps crafted for top agencies, making us more than just a tech company—we''re your growth partner.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Rextech Studios', 'Game Development', '', '9562965493', 'info@rextechstudios.com', 'www.rextechstudios.com', 'Rextech Studios is a game development–focused company based at Infopark, Kerala, primarily engaged in building games and interactive digital solutions. The company also works with Augmented Reality (AR), Virtual Reality (VR), and metaverse platforms to develop immersive applications, simulations, and virtual environments for education, training, entertainment, and enterprise use.  Rextech Studios provides end-to-end development services, including design, development, testing, and deployment of interactive digital products. The company focuses on building scalable, reliable solutions using modern development tools and platforms.  Operating from Infopark, Rextech Studios contributes to Kerala’s growing technology ecosystem through its work in game-based and immersive digital technologies.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('RIOD LOGIC PRIVATE LIMITED', 'IT Services', '', '+91 8589874131', 'join@riodlogic.com', 'www.riod.in', 'RIOD Software Delivery Center (SDC), located at Infopark Koratty, serves as the dedicated software development and technology operations hub for RIOD. As a growing provider of IoT and automation solutions, RIOD SDC is focused on delivering high-quality, scalable software services across diverse industries.  Our center at Infopark plays a vital role in driving R&D, software product development, and client project execution. With a strong foundation in emerging technologies such as the Internet of Things (IoT), AI/ML, and cloud-integrated systems, RIOD SDC supports businesses in their digital transformation journeys. We specialize in developing innovative applications for smart infrastructure, EV solutions, and enterprise automation.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Roberts Design Services', 'Construction Engineering', '91 81 380 40 843', 'Office 1A7, Level-1 , Wing A , Indeevaram, Infopark Thrissur, Koratty, Kerala, India – 680308', 'contact@rdsind.co', 'www.rdsind.co', 'RDS team is a group of seasoned Design, BIM, Engineering professionals, whose depth of experience in producing fully coordinated Design through multi-disciplinary BIM projects and implementing innovative solutions to every aspect of their coordination and ensure capability of service delivery that is first in class. The RDS team is highly experienced, managing virtual design with deep, tier one technical expertise. We have significant global industry knowledge and believe in the legacy created by delivering great work. Our senior team includes early adopters of innovative technologies such as BIM, digital construction management in the segments of construction engineering and is in a continuous process of growth and development. RDS pairs the latest technology with disciplined, buildable design to provide certainty and simplicity in the onsite delivery of projects. Functional technology improves coordination, reduces lost time, eliminates miscommunication and provides a virtual built environment for our clients before projects even break ground. Our global presence and use of world class communication and collaboration tools means RDS can deliver to any project, wherever you are in the world. Our ‘begin with the end in mind’ approach provides invaluable data for asset management of our built product through fully coordinated multi-disciplinary BIM management.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('ROGERSOFT', 'IT Services', '', '9995207676', 'careers@rogersoft.com', 'www.rogersoft.com', 'ROGERSOFT Technologies Pvt Ltd is a value-based technology consulting firm providing end-to-end IT solutions for its clients across Middle east and India. We have a highly skilled team in the areas of Ecommerce software development, Cloud Computing, Product Design & Development, Software Testing, Framework Development and Technology advancements. Since our inception, we have delivered over 50+ projects on the web platforms using different technologies. Our dedicated teams seamlessly integrate with the onsite development teams of our clients and add value to the client business by providing technical knowledge and flexibility.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('RUBY SEVEN STUDIOS', 'Gaming', '', '4844059440', 'careersindia@rubyseven.com', 'www.rubyseven.in', 'Company Profile:  Ruby Seven Studios is an award-winning, top-ranking social casino gaming company based in North America and India. Our team’s mission is to surprise and delight online players by creating the world’s best gaming experiences. We focus on bringing dynamic and compelling casino game content to land-based and online casinos through engaging, free-to-play casino gaming apps and websites. Ruby Seven Studios  bridges the gap between land-based casinos, online casinos and social casino gaming apps through key partnerships including,  Foxwoods Resort Casino, Mystic Lake Casino Hotel, Pechanga Resort & Casino, Delaware North Gaming, Affinity Interactive, Fantasy Springs, Chumash Casino Resort, Prairie Band, Lake of the Torches Casino, and Choctaw Casinos & Resorts. With more than 170 employees worldwide, Ruby Seven Studios has created more than 20 titles for the Apple, GooglePlay, Amazon Kindle, Facebook, and web platforms. To learn more about Ruby Seven Studios, please visit www.rubyseven.in.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('SaNDS Lab', 'IT Services', 'Chandanam Block, Infopark , Trichur KorattyPO, Koratty', '+91 9895765626', 'hr@sandslab.com', 'www.sandslab.com', 'As a diverse end-to-end IT solutions provider, SaNDS (Software and Network Development Solutions ) Lab offers a range of expertise aimed at helping customers re-engineer and re-invent their businesses to compete successfully in an ever-changing business community, with the final objective of giving clients the competitive edge in the marketplace.  Our consulting and IT solutions have resulted in technology-intensive transformations that have met the most stringent of international quality standards. The company’s sophisticated technology centers—powerhouses of specific expertise—provide solutions to customers across the country. Backed up by a qualified professional team, with an Agile approach in software development, has reaped our presence in the present software market.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('SayOne Technologies Pvt.Ltd.', 'IT Services', '', 'Unit No.503, 5th Floor World Trade Centre, Infopark Kochi P.O., Kochi – 682042 phone: 0484-4037171', 'hr@sayonetech.com', 'www.sayonetech.com', 'SayOne is a fast growing Information Technology and Digital services company headquartered in India. We help our clients to become future ready by harnessing the power of new and emerging technologies. SayOne has delivered over 400+ projects to 100+ Start-ups and SMEs from North America, Latin America, UK, EU, Australia and the Middle East. We have over 70 dedicated employees committed to solving our clients'' greatest challenges through innovative technology and digital solutions.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('SBL Knowledge Services Pvt Ltd', 'IT Services', '', '98957 64867', 'hr@sblcorp.com', 'www.sblcorp.com', 'Founded in 2005 by Mr. Gopakumar Pillai, SBL Knowledge Services Limited is one the fastest growing and most sought-after knowledge organizations in India. Our dedicated workforce of over 1000 people caters to customers in 10 industry verticals.   Our expertise lies in Geospatial Science, Smart Technology Solutions, Virtual Reality, and Business Transformation Services. Over the years, we have provided cost-effective and ingenious solutions to over 200 customers, from startups to Fortune 500 companies, and have successfully executed more than 800 projects globally. With 99.1% projects delivered within the budget and deadline, we have been able to make a distinct mark for ourselves in the evolving and booming IT ecosystem. Today, we enjoy 98% customer retention and execute 70 projects annually, on an average. Our smart solutions have helped us expand our footprint in the US, UK, and the Middle East. Our offerings help enterprises in the private and Government sectors optimize technology, enhance productivity, mitigate business risks, and maximize ROI.     Join Us!       At SBL we believe in building careers not simply offering job roles. We strive to create an environment where you have unquestioned freedom to be at your creative best, express your ideas without fear, aim for perfection through learning, and innovate to the maximum. Career progression is actively encouraged and supported as part of our commitment to our collective vision and goals. Whatever our direction of travel, we want to get to our destination together as a team. We are always on the lookout for talented individuals who want to make an impact, change lives, and build a sustainable tomorrow. If you are one of those people, then you’ll discover that each day at SBL challenges your intellect and creativity, and encourages you to explore new things.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('SE-Mentor Solutions', 'IT Services', '', '7306021783', 'careers@se-mentor.com', 'www.sementor.com', 'A team of dynamic QA professionals with extensive expertise and experience in providing high quality, yet affordable software testing services. SE-Mentor pioneers to provide precise and top notch QA consulting and software testing services in a cost-effective manner for its clients across the globe. Every SE-Mentorian is committed to ideate, innovate and implement the most apt technology, tools, and solutions that will enrich our clients and give them that leading edge to surpass competition. Our stature as a testing pioneer is built on the value our team has added to some of the leaders in the IT industry. SE-Mentor’s collective business agenda is to be driven by shared and mutual growth , where we see the success of our clients and the end user experience of their customers as the prime focus area.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Seeroo IT Solutions', 'IT Services', '+91 484 298 5660', '', 'info@seeroo.com', 'www.seeroo.com', 'SEEROO IT SOLUTIONS (SEEROO) commenced its operations in 2007. Our corporate office is located in a serene campus in Kochi, an IT hub and emerging cosmopolitan city in Kerala, the southern state of India. Our global office is located in Abu Dhabi, the capital of U.A.E. Our associate office is located in the state of New Jersey, United States. At SEEROO, we are committed to providing top-notch IT solutions conforming to international standards and still keeping them affordable. We work as technology partners to our clients. We have served clients from Australia, Bahrain, China, India, Iraq, Ireland, Kuwait, Malaysia, Qatar, Saudi Arabia, United Arab Emirates, UK, and the USA. The core solutions offered by Seeroo include:  Custom Applications /Web portal Development and Maintenance Mobile Application Development (Android and IOS) Odoo-based ERP Solutions  Digital Marketing Solutions (SEO and SMO Projects) Infrastructure Management and Services Branding solutions (Design, Logo, 2D/3D animation, etc.)');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Seguro Technologies', 'IT Services', '', '8078791340', 'hr@segurotechnologies.com', 'www.segurotechnologies.com', 'Seguro Technologies is one of the leading web and mobile application development companies, with its presence all around the globe. We aim at providing high quality software development solutions and services at affordable prices to our clients.  From our inception in 2010, we have served small, medium and large scale clients from different industries by providing them with the best feasible web, mobile application solutions and services. With more than 20 long term regular offshore outsourcing partners, consisting of medium to large size enterprises, our client list keeps on increasing every year. Our services are oriented towards providing clients with the best feasible solutions tailor-made for their business. Our services include Web Development, UI/UX Design, CMS & Ecommerce, Mobile App Development, Graphic Design, Digital Marketing and Web Hosting.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('SEIDOR Opentrends', 'IT Services', '', '+91 480 2735022', 'careers@opentrends.net', 'www.opentrends.net', 'SEIDOR Opentrends, The digital transformation division of SEIDOR is headquartered in Barcelona with expertise in technology consulting, and offering a wide range of innovation solutions and services. Our services includes customer experience, ERP, analytics, employee experience, cloud computing, workplace, and cybersecurity solutions. We have 40 years of experience, over 8,000 clients across 44 countries, and a global workforce of more than 5,400 professionals. Through our work, we create exceptional technological experiences centered around people, ensuring technology is humanized and user-friendly.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Senscript Technologies Pvt Ltd', 'IT Services', '', '+91-9037122872', 'careers@senscript.ai', 'www.senscript.ai', 'We are a leading IT company that employs the latest technologies and tools, nurturing a top-notch development culture and outputs that speaks for its steadfast growth and success milestones. We offer a wide spectrum of web & mobile application development and software solutions across AI/ML, ERP, CRM, IoT, blockchain, Oracle Cloud, and premium 3D Web development. We are powered by our parent company Cloud Vice Technologies, based in USA, a partner of Oracle Inc. in cloudification across the US public and private sectors.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Servsys Technology Services India Pvt Ltd', 'IT Services', '+91 80 8638 8637', 'Office No. 2, Wing 1, 2nd Floor, Jyothirmaya, Infopark Phase II, Kakkanad, Kochi. Pin: 682303   Mobile: +91 8078878871', 'anjana@servsys.com', 'www.servsys.com', 'Servsys Corporation. is a Cisco Premier Partner with Specializations in Cloud, Advanced Data Center, Enterprise Networks & Security Architectures. Servsys Offers IT Professional & Integration Services and Managed IT Services & Solutions. Servsys'' IT Staffing & Augmentation services perfectly compliment its multiple business units. Servesys has been recognized by Inc Magazine as one of the fastest growing private companies in America 7 years in a row out of 10 years in Business with stupendous growth. Headquartered in Dallas, TX with consultants spread throughout the continental US, Canada & Mexico also has a strong offshore presence in India, Servsys is strategically positioned for supporting our clients nationally & internationally.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Silverbloom Technologies', 'Unknown', '', '1st floor,''Mandaram'' Infopark Thrissur Nalukettu Road Koratty-680308', '', 'www.silverbloom.com', '');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Simelabs Pvt Ltd', 'IT Services', 'Unit No 305 & 306, Tower A, World Trade Centre, Infopark Phase 1 SEZ, Kochi', '', 'hr@simelabs.com', 'www.simelabs.com', 'Simelabs was founded in 2014 by Prakash Bare, Derrick Sebastian and Tom Antony. Started as a small agency focused on application development for small and medium - sized firms, since then Simelabs has grown into a global digital transformation solutions provider specializing in end-to- end product development, IP enabled service, with strong client relation and focus on leading - edge technologies. AI/ML, Datascience, Robotics, Metaverse, Blockchain, Healthcare solutions are some of the key expertise within the DNA of our company. They offer creative customized solutions empowering startup and emerging organizations to deliver unique client experiences and meet corporate objectives.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Skybertech IT Innovation Pvt Ltd', 'IT Services', '+91 7592 888 111', '34, 4th Floor, Thapasya, Infopark Kochi Phase 1, Kakkanad- 682042', 'mail@skybertech.com', 'www.skybertech.com', 'Skybertech started Since 2016 and today serves the needs of many medium to large organizations with its consultancy services. Within a few years, Skybertech has grown to become the leader in the field in Kerala offering CIO/CTO consultancy services to over 400 clients - and growing. Skybertech IT Innovations Pvt. Ltd., is peopled by an experienced team comprising of a CIO (Chief Information Officer) or CTO (Chief Technical Officer) who acts as your virtual consultative professional who has divers and exhaustive technical expertise and experience in the IT sector. He is amply supported by a group of techno-functional experts who will guide your organization or business in your technology related areas - thereby improving your business functionality multifold. They assistance will prove vital in dealing with the most complex IT projects - big or small. SERVICES • IT AUDITING • ITCONSULTING • IT STRATEGY • IT BUDGETING • IT POLICIES • IT PLANNING • BUSINESS • IT PROJECT IMPLEMENTATION • E-COMMERCE IMPLEMENTATION • VIRTUAL STAFFING SERVICES World Wide 4 Offices : INDIA & DUBAI');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('SmartFox Technologies', 'IT Services', '2nd FLOOR, SBC -1, THAPASYA, INFOPARK PHASE-I, KAKKANAD, KOCHI', '+91 9778477300', 'info@smartfox.co.in', 'www.smartfox.ltd', 'Founded in 2022, SmartFox Technologies is a digital transformation specialist. We enable organisations to become more agile, innovative, and customer-centric, ultimately driving growth and profitability. We specialise in developing cutting-edge software applications and offering technology consulting. We are specialists in technology upgrades and platform revamping of legacy applications. We are the regional distributor and implementation partner for the innovative solution IPM+ a patented product of Vigyanlabs for Windows and other platforms to help businesses reduce their IT energy consumption non-intrusively without degrading user experience. The savings directly add to the bottom line. The IPM+ product suite also has innovative products for real-time asset tracking, performance management, printer monitoring, and power management of airport flight information displays.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('SMEC Automation Pvt Ltd', 'IT Services', 'Athulya, Ground floor, Infopark Campus, Kochi', '9656227714', 'connect@smectechnologies.com', 'www.smeclabs.com', 'SMEClabs is a global End-to-End IT/ITES services and solutions provider that helps customers do business better with our industry-wide experience, deep technology expertise, and comprehensive portfolio of services.  It has a team of 1000+ qualified and experienced engineering professionals from different engineering streams, working in a cognitive framework, involving extensive research into the technologies involved in the control engineering arena. The team plays a key role in the development of cutting-edge technologies and products that the company applies in its marine and industrial projects and is the driving force that keeps the company ahead of its competitors in terms of quality, reliability, and efficiency and helps it maintain the status as the leader in the automation sector in Asia.  SMEC, one of India’s first worldwide EPC contractor companies, is globally recognized for its distinctive services, specifically in Marine & Industrial Automation, Instrumentation, Electrical, Pneumatics, Hydraulics, and Mechanical sectors started its journey in 2001. SMEClabs is the dedicated R&D and Training wing of SMEC, that takes utmost care in molding an efficient and skilled team. Updating the latest technologies of all engineering verticals and training the existing as well as young recruits have improved the quality of service throughout the voyage.  It has over 2 decades of service history. It serves various organizations of different verticals such as Oil and Gas, Marine, Defence, and Industries and is fortunate to be recognized for its unique solutions and time-bound services.  Currently, the company has its base for major operations in Marine and industrial automation, predominantly in India, Sri Lanka, UAE, and Singapore.  In our research and training division, we provide training in Data Science Course Kochi, Python course in Kochi, Cyber Security Course in Kochi, Flutter Course Kochi   For Training & Internship Click Here');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('SnippetCommerce360 Pvt Ltd', 'E-Commerce', 'Carnival Infopark, Phase1, Infopark Kochi', '+91 9061234445', 'collab@snippetcommerce360.com', 'snippetcommerce360.com', 'Snippet Commerce 360° is a global digital commerce solutions company headquartered in Orange, California, with a growing presence in India. Our state-of-the-art development center at Carnival Infopark, Kochi, serves as a strategic offshore hub, enabling us to deliver scalable, innovative, and secure technology solutions across industries. We specialize in e-commerce development, CRM implementation, product engineering, web and mobile app development, and offshore IT consulting. With a strong focus on customer-centric design, performance optimization, and data-driven outcomes, we have empowered leading international brands like JLo Beauty, Meaningful Beauty, and Skin at Work through custom campaigns, seamless platform integrations, and advanced UI/UX development. Our Infopark team operates within a secure, high-performance environment adhering to strict information security protocols, including PCI compliance, biometric access, and role-based restrictions. We utilize modern collaboration and project management tools like JIRA, Confluence, and Slack to ensure transparency, agility, and effective project execution. Technology Stack: Platforms: Shopify, Salesforce Commerce Cloud, Oracle ATG, Eneda Frontend & UI/UX: Figma, React.js, HTML5, CSS3 Backend & Full Stack: Node.js, Express.js, MongoDB – MERN Stack Search & Indexing: Apache Lucene, Algolia Domains: Retail, CRM, Subscription-based eCommerce At Snippet Commerce 360°, we are dedicated to helping our clients stay ahead of the digital curve by delivering cutting-edge commerce and CRM solutions that drive measurable business impact.  Syntra 360 CRM – A next-generation customer relationship management platform built to streamline sales, marketing, and customer service with AI intelligent automation.  Snippet Commerce – A feature-rich, scalable digital commerce platform designed to empower B2C and B2B brands with powerful merchandising, personalization, and analytics tools.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Softop Solutions Pvt Ltd', 'EdTech', '', '+971 529822133', 'careers@softopsolutions.com', 'www.softopsolutions.com', 'Softop Solutions Pvt Ltd is a Private Limited Company registered under Companies Act 2013 by Registrar of Companies; Government of India vide its Company Identification No. U72900KL2020PTC061059. Softop Solutions is a startup venture primarily focusing on development of specialized ERP solutions for the service sectors such as educational institutions, hospitals, etc., and accounting and costing tools for small and medium scale industries.edu?gate A web-based school management application that enables schools to manage and grow their educational institution in an efficient and intellectual manner. The application provides a centralized platform for parents, students, and teachers. The seamless user interface and task management boost the performance of teachers and students, and help them execute their routine tasks in the most efficient way in real-time to the school management at all timesA cloud-based ERP solution for Schools.Eduegate.erp platformEduegate.onlineExam platformEduegate.parent platformEduegate.student platformEduegate.signup platform');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Softspace Infotech Pvt Ltd', 'IT Services', '', '+91 9847811647', 'info@softspace.ae', 'www.softspace.ae', 'Softspace Infotech Pvt Ltd was started in 2022 with the idea to create world class solutions which satisfy the demand of digital transformation by providing our Expertization and skilled services that foster competitiveness and innovation. We are passionate about creating technologies with the new paces of Artificial Intelligence and Internet of Things. Our company achieves the goals under the leadership and spectacular visions of our chairman Mr. Ahmed Al Suwaidi. Our sister concern company Softspace Technologies LLC is in Dubai, UAE.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Soulxes Technologies Pvt Ltd', 'IT Services', '', '914842916448', 'info@soulxes.com', 'www.soulxes.com', 'Founded in 2021 in Dubai, Soulxes Technologies Pvt Ltd is a dynamic product and service company revolutionizing the information technology sector. Our young, vibrant team delivers a broad spectrum of IT solutions and services. At Soulxes, we prioritize teamwork and continuous learning, ensuring every employee feels integral to our mission. As the IT landscape rapidly evolves, Soulxes provides professional support to help you navigate these changes. When customers demand flawless experiences, Soulxes leverages process automation and case management to deliver exceptional services.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('SparkSupport Infotech Pvt Ltd', 'IT Services', '', '8129270421', 'careers@sparksupport.com', 'www.sparksupport.com', 'SparkSupport Infotech Pvt Ltd is one of the leading IT solution providers in India. We manage the most complex and mission critical infrastructure for organizations across the globe. Furthermore we develop scalable, micro-service based web applications using the back-end technologies like Python, PHP, Perl node.js and front-end technologies like angular, vue.js, react.js etc. Additionally we develop native apps in iOS and Android. On top of it, we also develop apps using PowerApps and visualization using PowerBI. Our skills cater to the end to end IT requirements of every customer. At spark you will enjoy an empathetic, cordial, dynamic, passionate attitude from every employee.    * Cloud Computing  We design, build and deploy complex, mission critical cloud architecture in AWS, GCP and Azure and manage it. We make use of tools like Ansible, Terraform, docker, kubernetes for it on a regular basis.   * Software Consulting and Development  We provide agile software development services for e-commerce,  Live Video Streaming applications, shopping services. Medical Insurance, Fintech services etc. We also have expertise in developing applications using cloud APIs.  * Live Steaming technologies Implements scalable streaming technologies like webrtc for live interaction and streaming using wowza. We can build end-to-end solutions for on-demand or live video streaming.  * PowerTools Development  Design and build custom apps for organisations using PowerApps. The data gathered from it is made accessible as reports, charts and visualizations using PowerBI.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Spawoz Technologies Pvt. Ltd.', 'IT Services', 'Contact:', '', 'info@spawoz.com', 'www.spawoz.com', 'Spawoz Technologies Pvt Ltd founded in 09th May 2016 and flourishing with pool of qualified engineers, international clients and a considerable measure from claiming clients across the globe. Spawoz is a one stop shop for digital destination. We provide world-class digital services to our customers. Spawoz is progressively functioning for universal clients everywhere throughout the globe, particularly, in central European countries. Spawoz has a tight-knit team for designers, developers furthermore strategists particular to web built administration and customized digital products and services. We have phenomenal track record for best client fulfillment.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Speridian Technologies Pvt Ltd', 'IT Services', '+91 484 401 7951', '', 'smitha.sankarankutty@speridian.com', 'www.speridian.com', 'Speridian is an innovative, thought-leading digital modernization company that leverages modern software engineering and proprietary platform solutions to streamline and enhance interactions between clients and constituents within commercial and public sector markets. As a global business and technology solutions provider, Speridian''s business and technology experts help clients modernize their businesses through Digital Transformation. Headquartered in Albuquerque, NM, with regional offices across the globe, Speridian has been at the forefront of CRM, ERP, HR, CX Innovation since 2003. Our Next-Gen Solutions Practice combined with our partnerships with leading innovators such as Oracle, Microsoft, Salesforce, Google, Amazon, UiPath, Adobe, SAP etc has led to our proven track record of solving the most pressing business problems with our unique, industry-based 3-pillar approach: (1) business focus, 2) technology-fuelled innovation, and 3) delivery excellence. Speridian’s services include consulting, testing and quality assurance, custom development, cloud computing, IT support and managed services, AI and machine learning, system integration, big data and analytics, customer experience solutions, application modernization, and staffing professional services. Leveraging our domain expertise, Speridian has developed several advanced platforms:  CaseXellence: A low-code automation platform for public sector enterprises Beacon: A suite of banking solutions O360: An enterprise management platform for HR and project management');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Spiderline Technologies', 'IT Services', '', '+91 97453 66367', 'info@spiderline.in', 'www.spiderline.in', 'Spiderline Technologies is a Google Five Star-rated Digital Transformation company that offers creative, strategic, and technical development of a wide range of products and services, including Technology Consulting, Web Designing, Web/Mobile Application Development, Software Development, Corporate Training etc. A leading Information technology company delivering quality, vibrant, cost-effective web design and technology-driven solutions. Our expertise has expanded to cover all the most secure and advanced technologies and major styles, is aesthetically appealing, user-friendly comply with international standards, and uses the most secure and advanced technologies.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Spiralcode Innovates LLP', 'IT Services', '', '8590041414', 'info@spiralcode.in', 'www.spiralcode.in', 'Spiralcode Innovates LLP is a technology-driven company based at Infopark, Kochi, specializing in business automation and ERP implementation solutions. We focus on streamlining business processes through intelligent digital transformation, helping organizations enhance efficiency, transparency, and decision-making.  Our flagship product, Waves (Workforce Automation and Virtual Enterprise Solution), empowers sales and field teams with real-time insights, smart route planning, offline functionality, and seamless ERP integration. In addition, we offer customized ERPNext implementations, HRMS solutions, asset management systems, and workflow automation for industries including manufacturing, distribution, healthcare, MEP contracting, agriculture, and logistics.  Operating from Thapasya Building, Infopark Campus, we collaborate closely with businesses across India and the Middle East, delivering solutions that combine innovation, reliability, and scalability. Guided by the vision “Imagine the Future, Innovate Solutions, Implement Success,” Spiralcode Innovates LLP continues to drive digital transformation with a focus on customer satisfaction and sustainable growth.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('SS Consulting', 'IT Services', '', '+91 8129688272', 'admin@ssconsult.in', 'www.ssconsult.in', 'SS Consulting is a premier Global Advisory and Management Consulting firm, established in January 2015 by senior professional experts with global and diverse experience. Leveraging the extensive expertise of its leadership, including key members of the former Arbitron India team who successfully scaled and merged the business with Nielsen, SS Consulting specializes in Strategy, People, Process, and Technology.We provide professional expertise to enable business success for IT SMEs, IT product startups, and offshore captive firms (GICs). Our key areas of expertise include Offshore Advisory & Governance, Technology Incubation and Development, Human Capital Management and Organizational Effectiveness, and Operational Process Improvement. Since its inception, SS Consulting has played a pivotal role in enabling the scalability of IT SMEs by enhancing revenue, marketing, organisational structures, infrastructure, and governance. Notably, the firm has signed a Memorandum of Understanding with Technopark Kerala to position Kerala as a preferred IT investment destination and has pioneered Robotic Process Automation in several transformational engagements.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Steigend IT Solutions', 'IT Services', '', '9946161106', 'info@steigendit.com', 'steigendit.com', 'Steigend IT Solutions is an India based State-of-Art information technology company operating from Infopark Kaloor, Ernakulam. Our company is mainly focused in providing Open Source Enterprise Resource Planning (Odoo) services and solutions for enterprises across the globe. With our well experienced team in Odoo, provides consultancy, development, customization, training, support and maintenance to partners and customers. We have live experiences in delivering customized ERP solutions based on this fastest developing Open Source ERP application especially in the non English European market. We also undertake training for end users and works on pre-sales activities. Our company has a dedicated network team to deploy and monitor servers remotely and onsite. We have 24/7 helpline and service on demand. Apart from Odoo solutions our company also provide Infrastructure Services mainly including Cloud Solutions');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Stepping Stone Consultancy Services', 'HRTech', '', '+91- 0484 - 2989811', 'hire1.steppingstone@gmail.com', 'www.steppingstoneconsultancy.com', 'Stepping Stone Consultancy Services is a leading recruitment consultancy service provider based in Kochi, Kerala. Stepping Stone on account of its vast network of contacts around the world is a good partner for customers in service industry. Stepping Stone identifies the right resources for the right job at the right time. We provide training and development of human resources and play a key role in the service industry. We develop in-depth partnerships with clients and candidates - this understanding is what guides us when we work with our clients.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Strands Energy Pvt. Ltd', 'IT Services', '', '+91 480 2731126', 'jobs@strandsenergy.com', 'www.strandsenergy.com', 'Strands Energy Private Limited (SEPL) is a software development company that builds IoT and Cloud platforms for the energy industry. We are dedicated to building high quality software that our customers find easy to configure, deploy, and support.   Strands Energy serves as the extended software development team for our sister concern, Spirae LLC, based in the USA. Spirae’s Wave platform is used by energy service providers to integrate their customers’ renewables, storage, conventional generation, load control, and EV smart chargers to reduce carbon footprint, increase resilience, manage energy costs, and meet corporate sustainability goals.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Stream Perfect Global Services (SPGS)', 'IT Services', '', '0484-2972793', 'info@stream-perfect.com', 'www.stream-perfect.com', 'Stream Perfect Global Services (SPGS), an IT-BPM Service provider established in 2005. We provide EDMS services to EPC''s, owner operators and document management system implementation contractors for managing the engineering drawings and documents of O&G industries, Petrochemical Industries and other heavy industries. Tag relationship indexing and classification, Metadata indexing, Submittal preparation etc is some of the services, offered by SPGS. SPGS has expertise in digital transformation process flow and working with several international clients, to streamline their day-to-day requirements. SPGS have a high client retention rate, (>93%), staring from its inception. We are ISO 27001:2013 certified to ensure world class data security for the business data.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('SupportHub360', 'IT Services', '9633 024 360', '2B-5, Wing 2, Second floor, Jyothirmaya, Infopark phase 2, Kochi, Kerala -682303', 'sales@supporthub360.com.au', 'www.supporthub360.com.au', 'SANSIA DIGITAL Technology India Pvt Ltd is an IT consulting company operating under the brand SupportHub360. We are a technology consulting company. Headquartered in Perth, Western Australia, and operating in N. America and UK, we are a unique team of exceptionally skilled IT Professionals, designers, and developers who keep close tabs on the market to ensure you are getting the industry’s best support solutions around the clock, 365 days. Kochi is our support center for global operations. SupportHub360 provides back-office support for technology companies such as IT support, digital marketing, and application development with reduced cost (Approx.70% lesser on your current running cost). We also provide 24/7 support, 365 days a year. Some of the services we offer are,   Technology support center – Remote infrastructure management   Voice & chat support   Data center & NOC monitoring   SOC Monitoring   24/7 ServiceDesk support   Leasing of trained technology resources   IT support officers   Network & Server engineers   System integrator   Software developers   Web developers   Mobile application developers   Database administrators   Information security professionals');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('SurveySparrow Pvt Ltd', 'SaaS', '', 'Jyothirmaya, Infopark, Jyothirmaya Rd, Infopark Phase 2, Kakkanad, Kerala - 682030', 'careers@surveysparrow.com', 'www.surveysparrow.com', 'SurveySparrow is a young product startup founded by Freshdesk Veteran Shihab Muhammed who has built and scaled multi-million dollar SaaS products. An online survey platform, SurveySparrow let users create and share highly engaging, mobile-first surveys that offer a chat-like experience. The Conversational User Interface (CUI) makes surveys more personal and engaging, directly leading to up to 40% higher completion rates. With 10000+ happy customers and a very unique work culture that their employees swear by, SurveySparrow has proved itself to be a startup to watch out for.');
