INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Talk Digital Pvt. Ltd.', 'Digital Marketing', '', '9446581090', 'hr@talkdigital.co.in', 'www.talkdigital.com.au', 'Talk Digital was founded with the vision of providing businesses with a chance at a meaningful and honest partnership within the digital marketing industry. When we work with you, we see it as a collaboration. It is important to us that a business bases their decisions on valuable advice that is beneficial to their bottom line. This is where we move away from the pack. We don’t want to dazzle you with numbers and false promises. Instead, we implement strategies that have powerful long-term potential. Our goal is to become a partner in your journey for business growth. Technology has expanded so rapidly in the last ten years, that strategies used in the last 12 months, are often already outdated. Small to medium businesses very rarely have the resources and capacity to stay ahead of the curb because of this exact reason. This is what we want to influence. With the right touch, a well formulated online presence can act as a multiplier to various business process. Sometimes all it needs, is a push in the right direction.');
