INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('TECFORZ INNOVATIONS', 'Healthcare', '', '0484 4632159', 'info@tecforz.com', 'tecforz.com', 'Tecforz Innovations Pvt. Ltd. is a dynamic healthtech startup actively engaged in advancing healthcare technology through the Ayushman Bharat Digital Mission (ABDM). Our focus is on developing innovative and cutting-edge solutions that cater to both healthcare providers and payers. By leveraging the latest in health technology, we aim to streamline operations, improve patient care, and enhance the overall efficiency of healthcare systems.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Tech Aventure', 'IT Services', '', '+91-478 2815657', 'info@techaventure.com', 'www.techaventure.com', 'Started as a website development company, Tech Aventure has now grown into a full-fledged IT solutions provider trusted by clients around the world. We specialize in custom software development, mobile app development, eCommerce solutions, and result-driven SEO and digital marketing strategies.  With a passionate team of developers, designers, and project managers, we’ve helped businesses across Asia, the Middle East, and the Americas build and grow their digital presence. Today, we proudly serve global brands, delivering innovative and reliable solutions that make a real difference.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Techfriar Technologies', 'IT Services', '', '+91-7356899156', 'hr@techfriar.com', 'www.techfriar.com', 'Techfriar Technologies, founded in 2019, is a technology solutions company offering bespoke solutions to businesses while aligning with their specific requirements and company objectives. With offices across the USA, the UAE, and India, Techfriar continues to actively listen to and understand clients'' needs to be their trustworthy software partners. We build innovative solutions for our clients and collaborate with them throughout the entire process, from the idea stage to wireframing, design, development, testing, and deployment. Our services include e-commerce, MVP, web3 app development, and staff augmentation. We take pride in being selective about our partner projects because we believe in building strong and lasting collaborations. By working together, we tailor our solutions to meet clients'' specific prerequisites, providing unflinching support throughout their journey. Led by a YCombinator alumnus, our highly competent and diverse tech stack implements the expertise to understand the intricacies of your business and your company culture in achieving growth and operational efficiency. We are happy to be the friars who gather firsthand information about your projects and business goals in helping you accomplish your technological objectives securely and efficiently within reasonable timeframes. For more information about us, please visit: https://techfriar.com/');
