INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('TechNeurons Consulting Solutions Private Limited', 'IT Services', '', '+91 7736001501', 'hrex@techneurons.com', 'www.techneurons.com', 'TechNeurons founded in 2011 and headquartered at Cochin. Since its establishment, our company has achieved outstanding success in developing and delivering a stream of innovative solutions for projects and services in the global market. We see innovation as a clear differentiator, we challenge beliefs, concepts, and push it to boundaries. After 9 years, currently, we hold about 4 offices and active projects in multiple fields ranging from IoT to ERP. We believe that each of our products is unique, and we make sure that it is tailored to resonate with our company''s character. For TechNeurons, people come first. We make sure our customers are happy by creating a unique work environment for our employees, which helps them to think creatively and build long term commitments with us. We can inspire people only by showing them how inspired we are by what we do. We make sure our work environment gives our employees a chance for learning, developing their ideas, improving their skills, and thereby helping us to create great products. We provide professional services in: Web & Mobile App Development Migrating Legacy Models to Cloud Data Warehousing & Analytical Solutions Consumer & Industrial Automation');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Technowave ID Systems PVT.LTD.', 'IT Services', '', '8139021117', 'hr@technowavegroup.com', 'www.technowavegroup.com', 'Technowave International was established in United Arab Emirates in the year 1999. Since then, the firm has grown substantially with its own branch offices in the Kingdom of Bahrain, Sultanate of Oman, India, Saudi Arabia and value added resellers in Qatar and Kuwait.   Technowave Id Systems (P) Limited was established in Cochin in the year 2002. From providing barcoding equipments, the company has diversified into providing the best of the breed Barcoding Technology, Mobile Computing Solutions, Wireless gadgets for enterprises, ID cards solutions, Access Control systems, high quality imported Electronic Weighing Scales, business application softwares like Asset Tracking, RFID based Jewellery & Apparel Tracking, ERP, Warehouse Management Systems (WMS) and banking industry solutions. Technowave has a team of qualified professionals both in technical and marketing fields at its offices across the Middle East and India. The firm has engineers trained by the principals at their own factories and facilities and are well versed with business processes of the industry. It represents the top international companies who are world leaders in their respective industry. Technowave has installations all over Middle East, India, Bangladesh, Africa and CIS countries. In India, we also have an office at Infopark, Cochin, Kerala. In addition, we represent lot of other reputed companies in the world for various accessories and consumables. We have a wide range of products of well known brands such as Zebra, Datalogic, ESSL, Nordic ID, etc.We are committed not only to maintain the high standards of services to our clients, but also to improve it by bringing in technologically advanced products and services. We believe in providing for the needs of the society through solutions rather than offering just a product!');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Techpullers Technology Solutions Pvt Ltd.', 'Digital Marketing', '10C, Trans Asia Cyber Park Infopark SEZ,  Phase II', '919895156580', 'info@techpullers.com', 'techpullers.com', 'Techpullers is a full-service digital marketing agency, started in early 2019 with the aim of helping small and medium-size businesses grow through digital marketing. People have constraints in terms of money, resources, expertise, etc. As a digital marketing agency, we figure out already proven. & creative ways to get around these constraints.Our Mission:To help businesses achieve victory through digital marketing with proven & creative ways.Our Vision:To become a world-class Marketing & Business consultant to provide Consultancy, Training, and Marketing Support service to our clients.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('TechTaliya Informatics Pvt. Ltd.', 'IT Services', '+91 484 403 6777', '', 'info@techtaliya.com', 'techtaliya.com', 'TechTaliya Informatics Pvt. Ltd., founded in 2020, is a premier IT services and solutions provider based in India. We specialize in delivering top-tier software development, cloud services, mobile app development, digital marketing, and AI-driven solutions to clients worldwide. Our mission is to empower businesses with innovative technologies that drive growth and operational efficiency.  We are committed to enhancing business performance by streamlining processes and enabling digital transformation. With our focus on cutting-edge technologies and client satisfaction, we have established ourselves as a trusted partner for businesses seeking impactful solutions.  Our expertise spans a range of industries, offering bespoke solutions such as ERP systems, e-commerce platforms, and specialized applications for the hospitality sector. We also excel in cross-platform mobile application development and emerging technology fields like Data Science, IoT, and Machine Learning. From project inception to implementation and ongoing support, TechTaliya stands as a reliable technology partner, providing comprehensive, scalable solutions tailored to our clients'' needs.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Techversant Infotech Pvt Ltd', 'IT Services', '', '0484 4014666', 'careers@techversantinfotech.com', 'www.techversantinfotech.com', 'Techversant is a leading provider of end-to-end IT services and solutions for Global 1000 companies.  Techversant is a Global Technology Services and Solutions Company providing high-quality end-to-end IT Solutions and Services to its clients across the globe for more than 15 years.Techversant has been providing Technology services in the key areas of Digital Transformation, Understanding the Evolving Industrial Scenarios, Investment Priorities and Technology Disruption.  We offer expertise and consultation in multiple technology domains like – ColdFusion, Python, Java, .NET, NodeJS, Ruby on Rails, Golang, PHP, Angular, ReactJS, VueJS, IOS, Android, Flutter, ReactNative, Artificial Intelligence, Data Science, Blockchain, Business Intelligence etc.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Techware Lab Pvt.Ltd.', 'IT Services', '', '+91  9567787002', 'careers@techwarelab.com', 'www.techwarelab.com', 'Techware Lab is a highly professional software development team based out of Kochi, India with product and sales offices in Canada and UAE. We have delivered our web and mobile solutions and custom software to clients across the world since 2012.  Techware Lab is a leading service and product-based company in India by a group of smart developers who are extremely creative and brilliant to craft breathtaking software solutions as per clients'' request and experts in providing complex enterprise-level apps that are game-changing in scale and scope.  We believe in end-to-end development that scales. From product ideation to system rollout, our goal is to think big, build smart, and deliver excellence. That means we work tirelessly to achieve the outcomes you want without ever compromising.  We’ve got the knowledge, experience, and cutting-edge technologies to bring your business vision to life. Whether you’re interested in product engineering or online marketing, our diverse and talented team has got you covered.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Tecnostac Systems Private Limited', 'FinTech', '401 B, 4th Floor, Lulu Cyber Tower 1, Infopark Phase I, Kakkanad, Kochi- 682 042', '+91 95670 63871', 'hr@tecnostac.com', 'www.tecnostac.com', 'Tecnostac Systems is a leading IT solutions company, bringing together an exceptional team of financial technology experts with over 30 years of collective experience. Our flagship product, Co-Bank+, has been a trusted solution for SACCOs and the MFI sector for 30 years, with more than 4000 successful installations across India, Kenya, Uganda, and Tanzania. For over two decades, Co-Bank+ has empowered various SACCOs and other financial institutions to grow their customer base and enhance their services. We at Tecnostac, lead the transformation of the banking industry with our exceptional services and unparalleled banking experience. Derived from the renowned Co-Bank+ and backed by Naive Plus Software Solutions, our mission is to empower financial institutions such as SACCOs, MFIs, SHGs, and Cooperative societies across Asia and Africa.Our team of seasoned professionals, with decades of expertise, stands at the forefront of delivering comprehensive and scalable banking solutions, ensuring exceptional service and support for seamless navigation in modern banking.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Telious Technologies Pvt Ltd', 'IT Services', 'Carnival Phase 4, Infopark Kochi Phase 1, Kakkanad, Kochi', '+91 94956 58233', 'info@telious.com', 'www.telious.com', 'Telious Technologies was founded in 2003 by a group of management and technology experts, inspired by Java''s potential to deliver high-quality, impactful solutions. The name “Telious,” derived from Greek, means “perfect,” reflecting our commitment to excellence in every project. we offer custom Java solutions across various industries, specializing in supply chain management,  HRMS software, CRM, ERP, business intelligence, and eCommerce. Our dedicated team ensures on-time, cost-effective delivery of solutions that drive business growth and efficiency. With deep industry knowledge and technical expertise, Telious has become a trusted provider in the global IT landscape, recognized as one of India’s leading Java development companies.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Terrific Minds Private Limited', 'E-Commerce', '', '+91 7559903555', 'hello@terrificminds.com', 'www.terrificminds.com', 'Terrific Minds is a digital commerce and design agency offering premium IT Consulting services. We are an Adobe partner globally and we specialize in eCommerce technologies like Magento and Shopify. At Terrific Minds, we craft commerce experiences and digital products for fashion, lifestyle, and consumer brands. Our engineering team caters to a global clientele that includes early-stage start-ups, SMB, and Enterprise customers. Terrific Minds is a technology studio with a design thinking edge. We are a fun loving, young company and we believe in the concept of 10X Value obsession. We deliver class leading UX design to our customers worldwide and we are backed by a fully certified digital Commerce consulting practice with a specific focus on Magento. Geographically distributed between USA, Australia, Switzerland, and India, we are a team driven by high energy and a sense of purpose and we take pride in being an open-minded organization.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Testing Mavens Software Pvt  Ltd', 'IT Services', '', '+91 8138924300', 'hire@testingmavens.com', 'www.testingmavens.com', 'Testing Mavens Software Pvt  Ltd');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Thinkpalm Technologies Pvt.Ltd', 'IT Services', '1st Floor, ''Athulya'' Infopark Kakkanad, Kochi - 682 030', '0484-4104100', 'info@thinkpalm.com', 'www.thinkpalm.com', 'ThinkPalm Technologies Private Ltd. is a product engineering and software services company, formulated by a team of entrepreneurs with boundless passion for technology and innovative thinking. Promoted by a multi-million dollar company, ThinkPalm exists to deliver products and services to clients spread across the globe. Aiming to achieve service excellence through integrity, reliability and our core values, company seek to provide an environment of equal rights and satisfaction to the employees and the stake holders, and thereby build up an improved social system. The founders of ThinkPalm bring in with them extensive experience in some of the most challenging markets viz. US, Japan and EMEA and hence seek to build an organization focusing on continuous learning & innovations, to meet & exceed the expectations of clients in these markets. The current business focus of ThinkPalm will be on two verticals namely ·         Enterprise technologies ·         Platform technologies Enterprise Technologies vertical In the Enterprise technologies vertical, ThinkPalm''s initial focus will be towards developing a comprehensive software suite for Fleet Management. This software suite will be unique in its architecture and design and will become the flagship product of ThinkPalm in future. In addition, we also have expertise to develop Windows/ Macintosh/ Linux based applications and utilities, and web related product development. Platform Technologies Vertical In platform technologies vertical, ThinkPalm will focus on Software & Technology R & D Services in the following areas: ·         Telecom –Cellular Backend ·         Networking Domain ·         Embedded Domain ·         Mobile Application Related Technologies ·         Telecom testing services');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Thomsun Infocare LLP', 'IT Services', '', '919995868299', 'careers@thomsuninfocare.com', 'www.thomsuninfocare.com', 'Thomsun InfoCare (TIC), is an IT Services Company (Infopark, Cochin) helping its customers in providing solutions for their digital transformation requirements including Product Engineering, IT and Cyber Security, Mobile Application Development, Cloud Management and, ERP product development for UAE and US markets. TIC’s parent company Thomsun Group of Companies (TGC) is a conglomerate and a 3000 people company based out of Dubai. TIC is also supporting TGC companies on their e-Commerce, digital Security, and ERP requirements. THOMSUN INFOCARE software development company established in the year 2019. With an eye on delivering IT services that support enterprises with their digital engagement strategies and ERP product development for UAE and US markets.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('ThoughtMinds System Pvt Ltd', 'Artificial Intelligence', '', '+91 7510303111', 'careers@thoughtminds.io', 'https://thoughtminds.ai/', 'ThoughtMinds is a technology solution provider specializing in AI and digital engineering for AI First digital enterprises, from fast scaling startups to global Fortune companies, across industries such as manufacturing, healthcare, technology, banking and finance. We deliver AI business solutions that help organizations innovate and scale with confidence.  With over two decades of entrepreneurial and engineering experience, our founders have built and scaled global technology firms, bringing deep expertise in data modernization, AI driven automation, enterprise grade AI product engineering, and end to end AI business solutions.  What sets us apart is our “Half Human + Half AI” approach, which fuses human creativity with AI precision to design and deliver advanced solutions that drive operational efficiency, innovation, and measurable ROI. We help enterprises strategize, architect, build, and scale their AI initiatives, transforming software development, modernizing global capability centers, and accelerating the journey from AI concept to business impact through powerful AI business solutions.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Titan Tech Emirates Pvt Ltd', 'Digital Marketing', '', '9591546465', 'hr@titantechemirates.com', 'titantechemirates.com', 'Titan Tech Emirates Pvt Ltd is a credible & professional Digital Marketing Consulting company that focused towards providing solutions in Strategy, Marketing Automation, Social Media Management, Social Media Marketing, Search Engine Optimization(SEO), Search Engine Marketing (SEM), Conversion Optimization, App Store Optimization (ASO), Mob App Marketing, Content Marketing, Mobile Marketing, Reputation Management, Brand Management, Viral/Guerrilla Marketing, Local Marketing, Video Marketing, Promotional/Explainer Videos, Sentiment Analysis, Competitor Analysis, Predictive Analytics, Social Analytics, Marketing Analytics, Website Development, Web App Development & Mobile App Development.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('TNP Consultancy Private Limited', 'IT Consulting', '', '+91 8139894880', 'communication.india@tnpconsultants.com', 'www.tnpconsultants.com/en/tnp-india', 'Started India operations in 2017 with the desire to build a technology center to support our global activities, TNP India is the largest subsidiary of TNP Group outside of France. TNP India supports large international companies in India and Asia. The goal is to be a leader in India and Europe of large, complex business transformation programs. We are based in Kochi and have offices in Mumbai , Delhi and soon in Bengaluru. In a constantly changing world, TNP has mastered the art of transformation and performance. Forging a lasting transformation to innovate and prepare for the future. Aiming higher and transcending limits to ensure higher performance, starting now. At TNP, we continue to pursue our primary mission of providing guidance and support to corporate suites at major companies in France, Europe, Africa, India and the Middle East, as they carry out their strategic, operational, regulatory and digital transformations. Our personnel typically boast a track record of experience in both operations and consulting, enabling them to interact more effectively with in-house teams. Consulting is a demanding profession, so a culture based on metrics and results has always been integral to how we operate and something we value highly, as reflected in our practice of tying a portion of our revenue to the effectiveness of the transformations we implement. We excel in working closely with our client firms to co-create new services and products that offer a significant competitive advantage, while preserving each partner’s sovereignty and independence. Our firm has found its calling by addressing the client needs committed, independent, entrepreneurial, international, boasting hybrid (sector/digital) and specialized skills for end-to-end management of complex projects.   We draw strength from our ability to combine industry know-how and high-calibre technological expertise in data, information systems, artificial intelligence and the digital world. TNP’s approach to consult');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Toobler Technologies Pvt. Ltd.', 'IT Services', '', '91-484 4034359', 'info@toobler.com', 'www.toobler.com', 'Toobler Technologies Pvt. Ltd, is an offshore development company based in Cochin offering complete software solutions and consultancy services. With a growing reputation as a quality player, we are keen on providing effective yet simple and user friendly solutions for our clients using the best available technologies. As a result of our forward thinking approach and strong technical fundamentals, we have positioned ourselves as trusted team to work with for our clients.Our main areas of expertise include rich web and mobile application development, Cloud based applications, NoSQL application development among others.Our team of experienced developers and managers provide innovative solutions that fully utilize the power of existing technologies instead of just satisfying the required specifications. We believe in being perfectionists and are bound by a common passion for technology and hunger for innovation, two qualities which we believe gives us a clear vision of the future of technology and design, making us truly exceptional developers.At Toobler, we work, live and breathe the technologies of tomorrow to deliver products that are not just future proof, but the future itself.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('TouchWorld Technology', 'IT Services', '0474 2970 298', '', 'info@touchworldtech.com', 'www.touchworldtech.com', 'TouchWorld Technology is an independent and integrated company that is made up of thinkers and doers, united under the common goal of making businesses grow smoothly. We do not have clients; we have partners. We are always on the lookout for free-thinking souls with a vision, those who are interested in creating history by defining success in business.  10 Years of establishment OUR VALUES: CREATIVITY, INNOVATION, INTEGRITY, ACCOUNTABILITY, HONESTY, DISCIPLINE, AUTHENTICITY & ASSURANCE. OUR VISION & MISSION VISION: To provide our partners valued technology solutions using our expertise in design, development and installation of information technology and services. MISSION: Be Fast, Be Global, Be Connected. SERVICES OFFERED: LOCATION BASED APPLICATION, APP DEVELOPMENT, WEB DEVELOPMENT, SOFTWARE DEVELOPMENT, INTERIOR DESIGNING, 360 VR MAPPING, DIGITAL MARKETING, UI DESIGNING BRANCHES In DUBAI, KOLLAM, KOCHI');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Tranzmeo', 'Artificial Intelligence', '', '0484-4033744', 'hr@tranzmeo.com', 'www.tranzmeo.com', 'We are a Deep tech company focusing on anomaly and intrusion detection in Oil & Gas pipelines using Artificial intelligence, machine learning, High-performance computing, and Distributed Acoustic Sensing.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Travancore Analytics Pvt.Ltd.', 'IT Services', '', '9188955501', 'careers@travancoreanalytics.com', 'www.travancoreanalytics.com', 'Travancore Analytics (TA) is a bespoke software development company - a team of professional and experienced software developers, architects and project managers. We have been in operation from Technopark since August 2007, from Infopark-Kochi since May 2014 and Silver Spirit Tech Park - Mysore since April 2022. TA has its subsidiary company named Travancore Analytics Inc., in California. We have customers and business partners from USA, UK, Europe, Japan, Australia, New Zealand, Middle East and India. Our services portfolio includes Web Application Development, with cloud capable solutions, Mobile Application Development, VR/AR Enablement, Custom Application Development and Maintenance, Data Analytics and Business Intelligence, Product Development Support, Digital Engineering Solutions, Industrial Automation Solutions, Geo-spatial Information Systems and Streaming Media. Team TA continues to serve customers around the globe in various verticals such as Industrial, Healthcare, Financial, Media, Sports, Education and many more. Domain expertise: Web-Mobility Solutions, IoT Solutions, Engineering Solutions, Business Intelligence and Data Science Solutions, Augmented/Virtual Reality Solutions.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Tukxi India Private Ltd', 'E-Commerce', '', '', 'support@tukxi.in', 'www.tukxi.in', 'Tukxi India Private Limited is incorporated in India for providing online auto booking services. And presently the company is looking into expanding the business into the cab or car booking sector also. Tukxi will be providing a technology platform/ mobile application to enable the customers to connect with the cab drivers at a nominal cost.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Turqosoft Solutions Pvt. Ltd.', 'IT Services', '', '+91 98412 05845', 'info@turqosoft.com', 'www.turqosoft.com', 'Turqosoft Solutions Private Limited, a Private Limited Company incorporated on June 28, 2020, stands as a beacon of innovation in the realm of software solutions consulting. Recognized by Startup India and Kerala Startup Mission (KSUM), our journey is fueled by a vision to be the leader in providing avant-garde software solutions to Small and Medium Enterprises (SMEs).We specialize in offering ERPNext & Odoo consulting for business across diverse verticals. Offerings include the powerful ERP solution ERPNext & Odoo, the versatile accounting program Frappe Books and the comprehensive HRMS solution Frappe HRMS.Mission & Vision: • Vision Statement: To be the leader in providing software solutions to SMEs. • Mission Statement: Empowering businesses to thrive by redefining the way they operate. We achieve this by streamlining complex business processes and delivering cost-effective software solutions tailored to the unique needs of organizations.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('TutorComp Infotech (I) Pvt.Ltd', 'EdTech', '', '8590016772', 'info@tutorcomp.com', 'www.tutorcomp.com', 'About US TutorComp is an online tutoring global leader providing personalized tutors all over the world. We enable students across the World to learn, excel and stay ahead of the knowledge and innovation curve. Our exceedingly qualified and expert tutors enable students to outperform and deliver outstanding grades. Our mission is to make learning easily accessible to students, and to leverage technology and global talent.    Our global operations are supported through an extensive network of local office at various worldwide markets of United States, United Kingdom, Hong Kong, Singapore, Australia, France, India, UAE (Abu Dhabi, Ajman, Dubai, and Sharjah), Kuwait, Bahrain, Qatar, Saudi Arabia and Malaysia.');
