INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Unilaw Global Private Limited', 'IT Services', '', '+91 99950 45717', 'info@unilawtech.com', 'www.unilawtech.com', 'UNILAW Technologies, headquartered at Carnival Infopark Phase 2 in Kochi, is a premier provider of custom software engineering and digital infrastructure services.  The company excels in custom software development, delivering enterprise-grade mobile and web applications tailored to client-specific requirements, while powering e‑commerce platforms optimized for scalability and performance.  UNILAW also specializes in server and data center management, offering proactive monitoring, cloud infrastructure maintenance, and cost-efficient operations. Their cloud capabilities include strategic cloud migration, multi‑cloud orchestration, and managed cloud services that modernize legacy systems with minimal downtime. Additionally, the company provides 24×7 web hosting support, ensuring high availability and fast resolution for live platforms.  Operating within the dynamic Infopark ecosystem, UNILAW leverages robust infrastructure and deep technical expertise to support growth-oriented businesses. Its presence in this high-tech hub enables seamless collaboration, access to talent, and operational excellence. UNILAW Technologies is committed to delivering reliable, secure, and customer‑focused IT services that empower clients to achieve digital transformation and sustained competitive advantage.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Urolime Technologies Private Limited', 'IT Services', '', '0484-2984589', 'hr@urolime.com', 'www.urolime.com', 'Urolime Technologies has made ground-breaking accomplishments in DevOps, 24/7 IT Support, Cloud Consulting, Dedicated IT Team and IT Consulting Services. We believe our customers are Smart to choose their IT Partner, and we “Do IT Smart”.Founded in 2011, Urolime Technologies has been bringing great IT values around the globe to small and Medium-sized businesses. We work closely with our customers and partners for the development of long-term Dedicated Team Solution strategies that are practical, sustainable and clearly deliver a return on investment.Our Offerings enable Managed Service Provider(MSP), IT Support, Web Hosting & Data Center, Cloud Solution Provider, DevOps Providers and other IT Solution Providers assisting them in deploying and managing their Servers, Networks and Business Applications with full security. Our well qualified and dedicated staffs will enable our clients to have a reliable offshore partner for increased efficiencies and customer satisfaction. Urolime Technologies has excellent working experience with clients from USA, Europe, Middle East and Africa serving them through our Remote Office located in Cochin, Kerala, India.');
