INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Valoriz Digital Pvt. Ltd.', 'E-Commerce', '', '+91 484 4606193', 'info@valoriz.com', 'www.valoriz.com', 'Valoriz is a digital transformation catalyst, deeply engaged with the retail commerce domain. Our user-centric solutions for core eCommerce and retail commerce business, extensively augmented with sales and revenue enhancement mechanisms, use the latest technologies including Artificial Intelligence and Machine Learning. Our brilliant team of innovative minds bring forth a unique blend of domain expertise and a deep understanding of cloud technologies and agile methodologies to bring you highly customizable eCommerce systems.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('ValueMentor Infosec Pvt. Ltd.', 'IT Services', '', '919745037742', 'help@valuementor.com', 'www.valuementor.com', 'ValueMentor is a leading information security company with offices in the USA, India, and UAE. ValueMentor offers various security services is empanelled by CERT-IN, a Government of India department, to provide security services to government entities in India. It is a PCI QSA Company and listed SWIFT CSP assessor. The company is based out of Kochi, India, and has representations in the USA, UAE, Kuwait, Bahrain, and Saudi Arabia. Our company is fiercely independent and our team prides itself on being able to offer frank and impartial advice that enables our clients to best secure their operational environment. We have a proven track record in ensuring that we deliver high-quality ICT security consulting, testing, and training services for commercial and government clients. Our client base includes some of the most successful technology companies and Banks in the USA, India, and the Middle East. Our Service portfolio includes PCI DSS Audit & Consulting, ISO 27001 Consulting Penetration Testing, Application Security Assessments, Mobile Application Security & Risk Analysis, HIPAA Consulting, Indian IT Act consulting To know more about us, drop us an email at info@valuementor.com or use the contact us form.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Varishtha Infotech Services Pvt Ltd.', 'IT Services', '', '+971 58 5049701', 'vandana@varishthainfotech.com', 'www.varishthainfotech.com', 'Varishtha Infotech Services commenced in 2010 with the aim to build a holistic IT services company that our clients could rely on. Since its incorporation, we have expanded the services we provide, as well as our partners, so that our customers get the best experience. We empower IT functions to transform and innovate, so that we can meet the demands and aspirations of our clients. We provide the following services– Robotic Process Automation (RPA),Staffing Solutions (On-premises and Remote),IT Managed Services,IT Infrastructure Services. With offices in UAE and India, our senior management include professionals with more than 40 years of experience in this industry. As a team, we are dedicated to our customers, and are continuously improving to serve them better.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Veeble SoftTech (P) Ltd.', 'IT Services', '', '7012099465', 'careers@veeble.com', 'www.veeble.com', 'Veeble has been a major player in the web hosting industry since 2011. Over a span of 13 years, we have built a client base of over 50,000 from 155+ countries, making us one of the fastest-growing web hosting and domain providers, currently powering more than 40,000 websites. Our tagline, "Weaving the Web," reflects our commitment to creating a closer and more reliable web by offering services that complement the latest technology. Our dedicated team consists of passionate young professionals who continuously push the boundaries of technical competency. We have proudly assisted entrepreneurs, businesses, marketers, bloggers, developers, designers, and many more to host their websites and share their ideas with the world.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Verteil Technologies Private Limited,', 'TravelTech', '', '+91-484-4019970', 'contact@verteil.com', 'www.verteil.com', 'Verteil Technologies is a travel technology company disrupting the 40 year old legacy airline distribution space with its new direct connect distribution system, based on IATA’s new distribution capability (NDC). Having onboarded 25+ Large Airlines and several large Travel Companies around the globe, Verteil is en route for rapid market capture under the new distribution model.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Viewy Digital P(Ltd)', 'IT Services', '', '914842331101', 'info@viewydigital.com', 'www.viewydigital.com', 'Viewy Digital has established its name among the top IT service provider companies in the world. Owing to our status as one of the leading mobile app and website development companies, we leave no stone unturned to provide the best IT solutions to all our clients. Our creative and technical team of developers assists the brands in creating a strong online identity and leaving a mark in the minds of their target audiences. We have dedicated teams for digital marketers and developers who come up with reliable and cost-effective solutions. We understand the business needs of all our clients and brainstorm our minds to offer the best service and a world-class digital experience.  Our team of experienced professionals who stay updated with the latest trends in the digital world and utilize this knowledge to develop the most technologically-advanced mobile apps and websites. Not just that, our team of digital marketers is also adept with the state of the art tools and technologies of the marketing world and draft the ideal search engine optimization strategy for your brand’s higher ranking. The Innovation Workshop services offered by us help our clients to define their product ideas and discover new opportunities in a cost-effective manner.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Violet Frames', 'Digital Marketing', '', '9744403855', 'info@violetframes.com', 'www.violetframes.com', 'Violet Frames is a dynamic IT, Media Production & Advertising Company that has been making its mark since its inception in 2014. With over 10 years of experience, offering specialised services in Website Development, Digital Marketing, Video Content Creation, Advertising (Tv Commercials, Theatre Ads, Corporate Films, Graphic Ads, 2d, 3d Animation), Complete Film & Video Production (Reels, Product Videos), and Film Post-Production (Film Editing, Animation, VFX, DI Colour Grading) Up to 8k quality. With branches in Infopark Kochi and Thodupuzha, we combine creativity, technology, and innovation to deliver impactful solutions tailored to meet the unique needs of our clients. Backed by a skilled team and deep market expertise, we are dedicated to helping businesses grow, innovate, and succeed in today’s dynamic digital landscape.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('VIPoint Solutions Pvt Ltd', 'IT Services', '', '484-4050222', 'hr@vipointsolutions.net', 'www.vipointsolutions.net', 'VIPoint Solutions Pvt. Ltd a technology-driven IT services provider with an excellent track record in achieving customer satisfaction. ViPoint Solutions offers effective technical support solutions in the web hosting sector. Our clientele ranges from single clients, ISPs, resellers to data centers. ViPoint Solutions’ strength lies in its excellent team of skilled and experienced Server Admins and Database management experts. We offer services in hosting support, data center support, server monitoring/administration, back-up restoration, etc.  By availing technical support from VIPoint Solutions you can get access to qualified and experienced server administrators who possess the know-how to tackle and resolve complex server issues quickly. The level of expertise that we offer coupled with the affordable rates helps take the load off your support staff and allows you to refocus on your core activities. By partnering with VIPoint Solutions, you are not only assured to achieve a significant increase in profit but also improve the levels of customer satisfaction.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Virtual Impulse Technologies', 'IT Services', '', '+91 9847670036', 'vimptech@gmail.com', 'https://vimptech.com/', 'VIMPTECH (Virtual Impulse Technologies) is a complete IT Solution company and an absolute intelligent solution provider. Established in 2004 by core software and hospitality training professionals. Our focus and expertise allows its customers to maximize the business benefits with the latest technology. Celebrating a decade of innovation, passion for this industry and fast paced growth, we believe in cultivating long term strategic relationships with its clients for mutual benefit. Our clock functions to deliver you the very best at the right time at the right cost.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Virtual Sys Technologies', 'IT Services', '', '0478-2554004', 'info@vstbiz.com', 'virtualsystechnologies.com', 'VsT was established in 2007, (and In UAE we are in the Market since 2010). to provide information technology solutions for small to medium sized businesses and companies . We are a technology intensive corporation geared to deliver state-of-the-art solutions in areas of integrated business solutions, system applications, product development, Internet/Intranet applications.  VsT provides clients with a comprehensive range of solutions including Infrastructure consultancy, onsite/offsite services, custom software development, web development, software and web application testing and enterprise consulting. We strive to deliver rapid, reliable and robust information technology solutions that work. Since inception our mission has been to develop partnerships with clients to provide effective and reliable information technology solutions that provide operational efficiency, productivity gains and cost savings to our clients. OUR MILESTONES  2022: Virtual Sys Technologies, Inc. is now officially Established & Registered in Delaware, US. 2021: In the GCC region, an affiliate platform for development, business scaleup, and automation has been launched  2020 : Implemented hybrid work model...and upgraded our services.  2019 : VST Dev Office Expansion & Added 25+ Workstations @INFOPARK- INDIA.  2017 : On 10th Year , Our Official Websites Revamped , Also Added More Service & Products .  2016 : Dubai New Office Opened @ The Binary by Omniyat Tower.  2015 : Our DXB Sales Scaled Up With More Team Members.  2014 : Our New Development Office Inaugurated @ INFOPARK CHERTHALA INDIA.  2013 : Dubai DED Registration Done L.L.C & Sales Team Setup.  2012 : Indian Office Renovated & Upgrade the Dev Team.  2012 : UAE Free Zone Company Started FZ L.L.C .  2011 : 1st Onsite Project @ Dubai.  2010 : Signed Contract with UAE/Middle East Projects.  2009 : SSI Registration & Initial Team Setup.  2008 : 1st Office Setup @Home Roof Top.  2007 : Company founded.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Vistas Global Intellect Private Limited', 'IT Services', '', '918138914366', 'careers@ariaholding.com', 'vistasglobal.com', 'Vistas Global is a wholly owned subsidiary of M/s Vistas Global W.L.L, Qatar. The main objective is to carry on the business of providing Information Technology and related services, applications, implementation, support and management; software development, sales, services, and maintenance; business process outsourcing; knowledge process outsourcing and Human resource consultancy.  Vistas Global, an established online outsourcing business with a team of 50 employees, with an expansion plan upto 120 employees ,  dedicated to providing services to customers based out of EMEIA region. Our core focus is on digital transformation consulting, program management, digital strategy implementation, technology solutions, and facade design & architecture. We cater to a diverse customer base, including corporate executives, small business owners, and architects, offering customized solutions to meet their unique needs. The Company is engaged in the business of facade design engineering & design engineering support services for building envelope (such as aluminum composite panel, glazing glass panel, etc.) for companies based in the EMEIA region using design engineering software / IT Infrastructure. It also deals with the shop drawing/fabrication drawing related to the facade industry.  Currently, the Company is looking forward to expansion programs with winning sizeable projects and wants to win the clients'' confidence by delivering quality service and thereby have a long-term relationship. It focuses, and investments will now be on growing further and gaining more market share in this space. Towards this, they are investing in deepening their transformation capabilities. Additionally, the company is strengthening its partnerships with large technology providers as well as start-ups to co-innovate and collaborate on creating new service offerings.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Vortexen Dynamics', 'Industrial Automation', 'Infopark Thapasya Block 04th Floor  Office Number: 10 Kakkanadu, Kochi', '918848850414', 'hr@vortexen.com', 'www.vortexen.com', 'We specialize in delivering comprehensive industrial solutions tailored to meet the diverse needs of modern industries. With a dedicated focus on innovation and efficiency, we provide a range of services and products that optimize industrial processes, enhance productivity, and elevate operational performance.Operating in India and UAE since 2011.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Voxtron Solutions LLP', 'IT Services', '', '+91-7356218111', 'lavanya@voxtronme.com', 'www.voxtronme.com', 'Voxtron is based in Dubai , U.A.E and has offices/affiliates in Qatar, India, Germany, Austria, Belgium, Italy, Turkey, Tunisia, Hong Kong, Portugal and Thailand. For over a decade, we have been providing affordable customer engagement optimization solutions in partnership with leading technology vendors such as Enghouse interactive, SAGE, Verint, Clarabridge, Odoo, Microsoft etc. This wide portfolio places us in a unique position to offer customers and partners a complete, fully-featured solutions. Our customers include Government organizations, Outsourcing companies, Corporates, Financial and Insurance organizations etc. Voxtron specializes in providing customer engagement/interaction optimization solutions such as Omni Channel Contact Centers, Self service applications, ERP / CRM solutions, Attendant Operator Consoles, Workforce Optimization Suite, Messaging Solutions, Social Media monitoring etc. These solutions help organizations enrich customer interactions, improve business processes, and optimize their workforce in order to enhance loyalty, increase revenue, mitigate risk, and manage operational costs. These solutions support the full range of deployment methods from premise-based to private, public or community cloud and even hybrid requirements. Our solutions are based on the realization of numerous projects and the needs of our customers. Solutions today are rarely simple — they demand technologies from a range of vendors plus skills across a number of disciplines. We have highly skilled, highly experienced, highly competent resources to deliver the most challenging projects. Our involvement spans consulting, design, implementation and comprehensive post-sales support, including 24/7 cover and a quick response time, which is unmatched and unique to the region.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Voyager IT Solutions Pvt Ltd', 'IT Services', '', '+91 478 2553310', 'info@itvoyager.com', 'www.itvoyager.com', 'Voyager IT Solutions Pvt Ltd is an Internet / IT Business Solutions Provider offering a wide range of services in the following areas of expertise.E-Business ConsultingWeb Designing & DevelopmentWeb-based Applications Development Online MarketingE-CommerceMobile AppsBusiness Process OutsourcingDigital Property InvestmentsWe have offices in Singapore and the Kingdom of Bahrain. Management Team:Mr. Mohammed Bin Adel Fakhro, a Bahraini National, is the Founder, Owner, and Chairman-cum-Managing Director of Voyager IT Solutions. Mr. Fakhro is also Director on the Board of Fakhro Group-Bahrain, and holds key positions as Director on the Board and Chairman-Entrepreneurship Committee of the Bahrain Chamber of Commerce & Industry (BCCI). With a heritage that includes two of the Arab World’s premiere merchant dynasties, the Fakhros and the Almoayyeds, Mr. Mohammed Bin Adel Fakhro has entrepreneurship firmly in his blood. An Economics (Honours) Graduate of Stanford University-USA, he has spent much of the past decade devoting his time to the field of entrepreneurship and intrapreneurship (the latter being entrepreneurship within an established entity). He has done this by creating his own new companies within his family’s holding companies.Mr. Deepu Krishnan R K is the Director & Chief Executive officer of Voyager IT Solutions. Our Vision:It is our Vision to be the Leading and Most Reliable Provider of IT Services / Internet Business Solutions on time to satisfy the business requirements of Clients worldwide and to help their businesses grow by providing solutions seamlessly and without hampering their budget.Our mission:Our Mission is to provide state-of-the-art and cost-effective IT / Web Solutions that meet customers’ needs, through our dedicated professional workforce who help you find and implement feasible solutions for your IT / Internet / Online requirements leading to sustained success of your businesses. In line with the Vision and Mission stated above, we intend ste');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Voyon Technology Pvt Ltd', 'IT Services', '', '6282685797', 'careers@voyon.net', 'www.voyonfolks.com', 'Voyon is a company on the fast track, offering advanced IT solutions and services to clients belonging to various industry verticals. Leveraging world class talent, mature processes and proven methodologies, and taking full advantage of emerging technology trends, Voyon develops solutions that enable organizations to achieve greater efficiency at significantly lower costs.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Vtrio Solutions Private Limited', 'IT Services', '', '91-9656600307', 'hr@vtrio.com', 'www.vtrio.com', 'Vtrio Solutions is a leading Mobility solution provider and a consulting firm Since 2004. Known for its innovative and smart solutions, Vtrio is a trusted partner in Software, Web & Mobile application development. Over the years, we have nurtured our portfolio with more than 100 direct clients, and over 1,00,000 web application end users. We have extensive experience in PHP, WordPress, Joomla. Drupal, iOS, Android, Angular JS, Ruby on Rails, Magento, Shopify, WooCommerce.  We provide fool-proof solutions that require the least maintenance and can be upgraded with ease. We also provide Remote Infrastructure Management services with our 24 X 7 customer support and online Live Chat support catering to client''s needs instantly.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('VVDN Technologies Pvt Ltd', 'IT Services', '', '+91 9778642081', 'info@vvdntech.com', 'www.vvdntech.com', 'VVDN is a Product Engineering & Manufacturing company focused on designing & manufacturing end-to-end products across several technology vertical markets (5G, DataCenter, Networking and Wi-Fi, Vision, Automotive, IoT, Cloud & Apps). VVDN’s India HQ is located at Gurgaon, India and its North America HQ’s is located in Fremont, CA, USA. VVDN serves global customers across several regions including US, Canada, Europe, India, Vietnam, Korea, and Japan. VVDN has 11 advanced Product Engineering Centres in India and across the globe, which are fully equipped to design & test the complete hardware & software required to develop a complete product or solution. VVDN’s 7 Manufacturing facilities are located at Manesar, Gurgaon, and Pollachi, Tamil Nadu, India, which includes in-house best-in-class SMT Factory, Molding & Tooling Factory, Die Casting, Antenna Assembly, Sheet metal fabrication facility, Product Assembly Factory, and Product Certifications labs. VVDN’s Engineering & Manufacturing facilities are fully compiled to develop & manufacture Enterprise, Consumer, Industrial, and Automotive-grade products.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Wazeefa1 Technologies Pvt. Ltd.', 'IT Services', '', '+91-487-2970765, +91-9188339903', 'info@wazeefa.in', 'www.wazeefa.in', 'Wazeefa1 Technologies Pvt. Ltd., located in Infopark Thrissur, Kerala, is a global IT services provider and a subsidiary of AAA Warranty Services, headquartered in Kuwait. We deliver high-quality digital solutions to clients across India, the Middle East, and beyond. Our service offerings include Web & eCommerce Development, Mobile App Development, CMS Solutions, Software Development, ERP, Digital Marketing, and Web Hosting. With a team of skilled and passionate professionals, we are committed to driving business transformation through innovative technologies and client-centric service. Wazeefa1 has earned trust across industries by consistently delivering reliable, scalable, and cost-effective IT solutions.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Webandcrafts', 'IT Services', '', '+91 480 2733999', 'info@webandcrafts.com', 'www.webandcrafts.com', 'Being known as a website development company in the initial stages, Webandcrafts (WAC) has blossomed into a global IT solution provider. Today, we create custom-made mobility solutions, web and mobile applications and dynamic digital marketing strategies for our customers in Asia, the Middle East, Northern and Southern parts of America. The journey was not easy, but with a team of talented developers, designers, and managers, we’ve been able to make ourselves known to some of the big names in the industry and help them redesign and power up their digital marketplace. Along with other services, e-commerce development is a service we actively proffer and have been able to successfully land customers whose names are recognized worldwide.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Webdura Technologies', 'IT Services', '', '8714746555', 'careers@webdura.in', 'www.webduratech.com', 'Webdura Technologies is a full-service web and mobile development company established in 2010. We create cost-effective and reliable software technology solutions for big and small enterprises to help them simplify business processes. From developing simple business website and mobile applications to enterprise-grade software solutions, we have been driving digital transformation for a diverse set of clients from around the globe.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('White Rabbit Group', 'IT Services', '', '6282370765', 'careers@whiterabbit.group', 'www.whiterabbit.group', 'Our ‘What’ - We Build We build web and mobile apps and provide a great experience for our partners. A better experience that people never even knew existed, one that fundamentally sets the bar higher. Everything we do is backed by a great experience.  Our ‘How’ - Our People Passionate people are the ones that are moving the world. While technology can deliver amazing change, it’s the ability of people to shape technology and each other that truly drives change. '' Through the people that we hire, the world is gravitating towards us ''  Our ‘Why’ - Impact Our why is to make an impact on the world and the lives of people around us. To better the internet, improve people’s lives, all while building a lasting legacy together on this planet.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Windfall Productions Pvt.Ltd.', 'Media and Entertainment', '', '9072312681', 'hr@windfallproductions.org', 'www.windfallproductions.org', 'Windfall Productions Pvt Ltd is a media post production company based out of Infopark koratty, and our core activities are Editing, Graphics, Promo production, Animation (2D & 3D), background music, creative production, Designing, etc. We have international clients from 5 countries as of now including US.');
