INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('WOC Branding Systems Pvt Ltd', 'Digital Marketing', '#30, 8th Floor, Vismaya, Infopark - Phase I, Kochi, Kakkanad, Kerala-682 042', '+91 9447306003', 'mail@wocbranding.com', 'www.wocbranding.com', 'WOC Branding is one of the top branding agency in Kochi that specialize in developing BRAND ARCHITECTURE. Established in 2011, we have quite an amazing journey and a wonderful clientele to our credit. Our team comprises extremely talented, vibrant, and resourceful designers, developers, and strategists who don’t hesitate to walk that extra mile to get you the best results. What’s more, we follow a thorough and meticulous brand development method that encompasses everything from research to strategizing to post-launch services. In the last one and half decades since our inception, we have partnered with many brands and helped them earn a permanent place in the highly competitive and ever-changing market.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('WORKSENT TECHNOLOGIES PVT LTD', 'IT Services', '', '79941677773/ 7994917773', 'careers@worksent.com', 'www.worksent.com', 'Worksent is a White Label Partner to Managed Service Providers (MSP), IT Service Companies, Cloud Service Providers and SAAS vendors. We started our operations in 2014, with an idea to help MSP’s & IT Service companies. With a team of 90+ Techs, we work 24/7, 365 days to meet the customer requirements. Our team comprises of certified professionals with MCITP, RHCE & CCNA along with bachelor degree in IT/Electronics Engineering. The services that we offer are purely white-label, where our techs will work as a remote employee, using your email, ticketing system, RMM and documentation system to support your customers. With our help you can reduce your staffing cost upto 60%.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Woxro', 'Digital Marketing', '', '+91 480 2081730', 'hello@woxro.com', 'www.woxro.com', 'We are a dynamic technology company driven by expertise in three core areas: Design, Development, and Marketing. These pillars form the foundation of our mission to deliver transformative solutions that empower businesses in the digital era.Design: Our Design team is at the forefront of crafting visually stunning and user-centric experiences. We blend creativity with cutting-edge design principles to create websites, applications, and interfaces that captivate and engage users. From sleek user interfaces to immersive user experiences, our design expertise ensures your brand stands out in a crowded digital landscape.Develop: In the world of Development, we thrive on turning ideas into reality. Our Development experts possess a deep understanding of programming languages, frameworks, and the latest technologies. We engineer robust, scalable, and tailor-made software solutions that meet your unique business needs. Whether it''s web applications, mobile apps, or complex software systems, we build the digital infrastructure that powers your success.Market: In the digital age, effective Marketing is essential. Our Marketing team excels in creating strategies that drive growth and visibility. We employ data-driven insights to tailor marketing campaigns that resonate with your target audience. From SEO and content marketing to social media and paid advertising, we deploy an array of tactics to ensure your brand reaches its full potential in the digital marketplace.At Woxro, we don''t just specialize in these core areas – we excel in them. Our multidisciplinary approach enables us to provide end-to-end solutions that seamlessly integrate design, development, and marketing to help businesses thrive and prosper in today''s competitive landscape. Partner with Woxro to harness the power of Design, Development, and Marketing to achieve your business goals and embark on a journey of digital success.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Yatnam Technologies', 'IT Services', '', '+91484-404-9024', 'mail@yatnam.com', 'www.yatnam.com', 'Yatnam Technologies Pvt Ltd is a Web Development company specializing in E-commerce development, as well as providing custom web and mobile application development services to clients worldwide. Established in 2008 by a group of engineers, we are proud to have completed 15 successful years in business, delivering over 2500 commercial projects to clients spanning 40 different countries. Since our inception, Yatnam has consistently worked towards its mission of becoming the most customer-satisfying and innovative company in the industry. Our commitment revolves around developing feature-rich, high-quality products and services that ensure customer satisfaction. We serve as outsourcing partners for agencies in the UK, Europe, Australia, the Middle East, and the USA. One of our major strengths lies in our extensive experience in e-commerce development, particularly with Magento, Woocommerce, and Shopify. Additionally, we specialize in CMS-based website development using WordPress, including the creation of plugins and themes. Our multi-platform solutions encompass the development of Custom Web Apps and Mobile Apps tailored to our clients'' unique specifications. We excel in offering Serverless Apps utilizing technologies such as AWS Lambda, DynamoDB, AWS AppSync, and Azure Function App.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Yavun Technologies', 'IT Services', '', '9654765276', 'djk@webcontentor.com', 'www.webcontentor.com', 'Yavun Technologies, a unit of Webcontentor is a young and vibrant organization with rapid growth in the areas of IT Services and Product Development with offices in Boston, MA, Delhi-NCR and Infopark Cherthala. We are always learning and sell the products of our learning. We are diverse people with diverse skills, capable and experienced to deliver a range of Web and Mobile business solutions. We are an end-to-end IT Services company with primary focus on Cloud Based SaaS products, Web and Mobile Applications, Demand Generation Tools, Prototypes. We work with a marquee list of IT Services and IT Product companies in USA.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Yellowfish Digital Innovations Pvt Ltd.', 'IT Services', '+91 484 402 3747', '', 'hr@yellowfish.in', 'www.yellowfish.in', 'Transforming enterprises digitally  At Yellowfish, we mix ideas and technology to create meaningful experiences. We are a digital-first technology partner who puts customers at the centre of everything. We are a group of passionate, creative people who won’t hesitate to break the code to deliver a new experience. We work across technologies, industries and geographies to come up with connections and solutions that truly transform businesses.  With customer experience becoming the key, any business transformation process has to look beyond technology and categories. Customer expectations depend on their best user experiences and any successful solution should aim at bettering that. This is why we focus on delivering solutions and products that move beyond functionality and offer an experience that people love, share and do business with.  Read more about us @ www.yellowfish.in');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Ynot Infosolutions', 'IT Services', '', '+91 9544885558', 'hr@ynotinfo.com', 'www.ynotinfo.com', 'YNOT INFOSOLUTIONS is a leading Web & Mobile App Development Company based in Infopark, Kerala, India. With over a decade of experience, we take pride in our young and dynamic team of creative designers, expert developers, and technology strategists. Our passion for digital innovation and commitment to excellence have earned us recognition across various industries.  We collaborate closely with clients to deliver cutting-edge solutions that maximize business growth and efficiency. By leveraging the latest digital technologies, we ensure that every project is built from the ground up for long-term success. Our exposure to businesses across India and 20+ other countries has strengthened our expertise in crafting scalable and customized digital solutions.  Our Services: ✅ Mobile App Development ✅ Web Design & Development ✅ E-Commerce Platform Development ✅ Web Applications ✅ Website Hosting  At YNOT INFOSOLUTIONS, we innovate, create, and transform ideas into reality, empowering businesses to thrive in the digital age.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('YOUGotaGift Pvt Ltd', 'FinTech', '', '+91 9895482001', 'info-ekm-in@yougotagift.com', 'www.yougotagift.com', 'YOUGotaGift Pvt Ltd is a premier provider of digital gift card solutions, recognized for its expertise in delivering tailored, cutting-edge applications for businesses and consumers.  YOUGotaGift offers comprehensive end-to-end technology services for the gift card industry, spanning concept development, system integration, deployment, and long-term support, ensuring seamless operations for clients and their end-users.  YOUGotaGift designs custom platforms that align with the specific needs of diverse industries, regions, and use cases. These include loyalty programs, employee reward systems, and consumer gifting platforms that are secure, scalable, and optimized to drive engagement.  YOUGotaGift’s omnichannel infrastructure enables seamless operation across web, mobile, and in-store environments, creating a unified gifting experience from online purchase through to point-of-sale redemption. Its proven track record in the field reflects a strong commitment to delivering reliable and user-friendly platforms that support merchant networks, corporate reward programs, and consumer gifting solutions across multiple sectors.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Zamorins Solutions (P) Ltd', 'IT Services', '', '+91 8304004275.', 'info@zamorinstech.com', 'https://www.zamorinstech.com/', 'Founded in 2014 in Des Moines Iowa, our company is one of the leading IT companies in Iowa and we also have our office in India, Kerala, Kochi. Zamorins started as a web development company and quickly moved into the mobile development market, business analysis and digital marketing.  Today we are a full-cycle service provider with a dedicated development team with expertise in web & mobile development, project management, digital design, technical support, digital marketing, and quality assurance.  Our strength lies in our ability to keep moving with the pace of the global web industry making innovations and adapting to the finest technologies and latest trends have been instrumental in taking zamorins to the next level.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Zapare Technologies Private Limited', 'Healthcare', '+91 811 388 55 44', '', 'HR@zaparetech.com', 'www.zaparetech.com', 'Listed in CEO Magazine as 25 Most valuable Management & Business Consulting Companies in India 2019.  Zapare Technologies works with Hospitals, Physician groups, Financial institutions, Clearing houses and Billing agencies to streamline, scale and improve their healthcare payment processing by efficiently deploying an array of intelligent technologies, staffing and business process management solutions.  With an innovative and automated approach, we smoothen the workflow to accelerate the growth of the organization by utilizing minimal resources.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Zealogics IT Solutions', 'IT Services', 'Suite 16 FGH, Tower 2, Trans Asia Cyber Park, Infopark Phase 2, Kochi', '0484 4049055', 'PRAVEEN@ZEALOGICS.COM', 'www.zealogics.com', 'We Zealogics LLC, we provide a broad range of IT consulting, systems implementation and application outsourcing services through an optimized global delivery model. With an expertise on various technology platforms, we enable our global customers achieve digital transformation and provide smart product solutions with our tech consulting, bespoke solutions, as well as professional services. We enable clients across the globe to navigate their digital journey with integrated technology models, business intelligence, and next-gen tech expertise to catalyze change.  Our pragmatic approach to technology with agile methodologies helps deliver unprecedented levels of solutions, service performances and customer delight.  With almost two decades of experience and more than 80% of referral business, we have delivered with process discipline while following CMMI Level 3, ISO 27001 standards and partnering with Microsoft Gold partner, Google cloud partner, Amazon cloud partner as well as other OEMs. Zealogics value engineering techniques, automation frameworks, and reference models are refined through engagements with Fortune 500 enterprises and OEMs.');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Zellis HR India Pvt.Ltd.', 'HRTech', '+91 484 486 5758', '6th Floor, Athulya Building, Special Economic Zone (SEZ) Kakkanad, Athulya Rd, Infopark Campus, Infopark, Kochi, Kerala 682042 & C1-02, First Floor, Chaithanya SEZ, Infopark Cherthala, Pallipuram P.O, Alappuzha, Kerala', 'careers.india@zellis.com', 'www.zellis.com', 'Zellis is the leading provider of payroll and HR solutions for the UK and Ireland. Together with Benefex and Moorepay, we form the Zellis Group, serving a vast array of companies across every vertical and industry.  Our purpose is to make people feel appreciated for the work they do – through precision, choice, and magic.  Our history We have over 50 years of heritage and industry experience – and we’ve been ahead of the curve throughout. Following acquisition in February 2018, Zellis is now a standalone UK & Ireland company, no longer a subsidiary of the global NGA Human Resources business. We are very proud of being the market leader in our chosen field - Payroll and Human Resources Software and Service. After acquiring Benefex, we’re now even better equipped to serve the complex needs of our customers.  Our vision Our vision is to be the clear leader in pay, reward, analytics, and people experiences. There’s nothing more important to us than building trusting and beneficial relationships with our customers, using our size, scale, and breadth of experience to offer tailored solutions that precisely meet their business needs. We design solutions that keep our customers ahead of change as they navigate the regulatory complexity and workforce uncertainty which exists in today’s business landscape. At the heart of everything we do are our highly qualified payroll and HR experts, who are committed to always delivering first-class customer service.  We’re proud of our culture At Zellis we work hard to create a culture where people want to join, belong to, and be part of a progressive organisation. We’re committed to recruiting and retaining a diverse and inclusive workforce that is representative of the customers we serve and the communities we operate in.  Our values, which were defined with input from all of our 2,000 colleagues, are not empty words on a poster. They reflect who we are, and how we operate as a business');
INSERT INTO companies (name, category, address, phone, email, website, short_description) VALUES ('Zinbay India Pvt.Ltd.', 'IT Services', '+91 999 590 7220', '12A2, Trans Asia Cyber Park,  Infopark Phase II,  Brahmapuram P.O., Cochin 682303, Kerala, India', 'office@zinbay.in', 'www.zinbayindia.com', 'Zinbay India Private Limited is a global End-to-End IT/ITES services and solutions provider based in Cochin, India. We have extensive & in-depth knowledge in Application Development. Our experience in managing technology projects, right from selecting tools and platforms, to implementing information technology solutions has shown results.  Our objective is to deliver quality Application Development Services while incorporating supreme value to enterprises globally. In order to provide world class solutions, we have tailored our in-house proven methodology, which helps us provide reliable software solutions that meet present as well as future demands.');
